// 文法詳解 N2(老師口吻,scripts/gen-grammar-detail.mjs 產生、build-grammar-detail.mjs 合併;改風格改 scripts/grammar-detail-samples.js 再重產)。
// key=文法 id;value=HTML(渲染時 .gd-jp 日文過 furiganaHTML→furigana+即點即查;中文解說不動)。
window.GRAMMAR_DETAIL = window.GRAMMAR_DETAIL || {};
Object.assign(window.GRAMMAR_DETAIL, {
  "n2-8": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜からには」就是中文的<b>「既然～，就要～」</b>。前面放一件已經決定、已經發生、改不了的事，後面說「那我就一定要…」。像中文常說「既然要做，就做到最好」，日文就是：<span class='gd-jp'>やるからには、一番を目指す。</span>（既然要做，就以第一名為目標）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>最常接動詞。重點是前面用「た」還是原形（辭書形），意思不一樣：<br><b>已經做了的事</b>：た形＋からには　<span class='gd-pair'><span class='gd-jp'>引き受けた</span> → <span class='gd-jp'>引き受けたからには</span></span>（既然已經接下了）<br><b>決定要做、還沒做的事</b>：辭書形＋からには　<span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するからには</span></span>（既然要去留學）<br><b>名詞、な形容詞</b>：中間要加「である」　<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロであるからには</span></span>（既然是專業的）</div><div class='gd-h'>後面要接什麼</div><div class='gd-sec'>からには後面一定是「所以我該有什麼態度」，不會只是講一件事情發生了。最常見的有這四種：</div><div class='gd-sec'><span class='gd-tag'>決心</span>我一定會做到。</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず守る。</span>（既然答應了，就一定會遵守）</div><div class='gd-sec'><span class='gd-tag'>義務</span>常配「なければならない」「べきだ」。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に出るからには、毎日練習しなければならない。</span>（既然要出賽，就得每天練習）</div><div class='gd-sec'><span class='gd-tag'>要求對方</span>常配「てください」。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に住むからには、ゴミの出し方はちゃんと覚えてください。</span>（既然住在日本，就請好好記住垃圾怎麼丟）</div><div class='gd-sec'><span class='gd-tag'>理所當然的判斷</span>常配「はずだ」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼がやると言ったからには、ちゃんとやるはずだ。</span>（既然他說了要做，應該就會好好做）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>這幾句幾乎是固定說法，直接整句記起來：</div><div class='gd-ex-line'>・<span class='gd-jp'>やるからには、本気でやろう。</span>（既然要做，就認真做吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>こうなったからには、もうやるしかない。</span>（事到如今，只能硬著頭皮做了）</div><div class='gd-ex-line'>・<span class='gd-jp'>自分で決めたからには、最後までがんばる。</span>（既然是自己決定的，就努力到最後）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面不能只講一件已經發生的事。<br>×<span class='gd-jp'>日本に来たからには、寿司を食べた。</span><br>○<span class='gd-jp'>日本に来たからには、本場の寿司を食べたい。</span>（既然來了日本，就想吃道地的壽司）<br>・名詞不能直接接：不是プロからには，要說<span class='gd-jp'>プロであるからには</span>。<br>・た形和原形別亂用：<span class='gd-jp'>結婚したからには</span>是已經結婚了，<span class='gd-jp'>結婚するからには</span>是決定要結婚了。<br>・它帶著「我扛下來了」的決心，語氣很重。單純講原因，例如「下雨了所以帶傘」，用「から」就好，不用からには。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>からこそ</b>（n2-9）＝<b>正因為～才～</b>，重點在強調「原因就是這個」。<br><b>からには</b>＝<b>既然～就要～</b>，重點在「接下來我該怎麼做」。<br>同樣講喜歡的工作：<br>・<span class='gd-jp'>好きな仕事を選んだからには、簡単にはやめない。</span>（既然選了喜歡的工作，就不會輕易放棄）<br>・<span class='gd-jp'>好きな仕事だからこそ、毎日がんばれる。</span>（正因為是喜歡的工作，才能每天努力）</div><div class='gd-sec'><b>上は</b>（n2-32）＝意思跟からには幾乎一樣，但比較硬、比較正式，多用在文章或正式場合。另外常聽到的「以上（は）」意思也很接近。<br>・<span class='gd-jp'>引き受けたからには、最後までやります。</span>（既然接下了，就會做到最後：平常講話就能用）<br>・<span class='gd-jp'>引き受けた上は、最後までやり遂げる所存です。</span>（既然接下了，定當貫徹到底：正式場合）</div><div class='gd-warn'>判斷小訣竅：「既然～就要～」用からには；「正因為～才～」用からこそ；同樣是「既然」，想講得更正式就換成上は。</div>",
  "n2-25": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜どころか」就是中文的<b>「哪裡是～啊，根本是…」「別說～了，連…都…」</b>。先講一個大家以為的A，再告訴你：實際狀況跟A差很遠，常常還是<b>完全相反</b>。像你以為放假可以休息，結果「休息どころか、比上班還累」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞：辭書形＋どころか　<span class='gd-pair'><span class='gd-jp'>やせる</span> → <span class='gd-jp'>やせるどころか</span></span><br>い形容詞：直接接　<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いどころか</span></span><br>な形容詞、名詞：直接接，<b>不要加だ</b>　<span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>簡単どころか</span></span><span class='gd-pair'><span class='gd-jp'>旅行</span> → <span class='gd-jp'>旅行どころか</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>反而相反</span>A不但沒發生，還往反方向走。後面常接<span class='gd-jp'>逆に</span>、<span class='gd-jp'>かえって</span>、<span class='gd-jp'>もっと</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエットしているのに、やせるどころか太ってしまった。</span>（我明明在減肥，別說變瘦了，反而還胖了）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んだのに、よくなるどころか、もっと悪くなった。</span>（吃了藥，不但沒好，反而更嚴重）</div><div class='gd-sec'><span class='gd-tag'>別說A，連B都不</span>A是比較難的事，B是更基本的事。連B都做不到，A就更不用說了。後面常接「も」「さえ」＋否定。</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、旅行どころか、週末に休むこともできない。</span>（忙到別說旅行了，連週末休息都沒辦法）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は漢字どころか、ひらがなも読めない。</span>（他別說漢字了，連平假名都看不懂）</div><div class='gd-sec'><span class='gd-tag'>豈止A</span>實際比A誇張很多，同方向但遠遠超過。</div><div class='gd-ex-line'>・<span class='gd-jp'>1万円どころか、5万円もかかった。</span>（哪裡只要一萬，結果花了五萬）</div><div class='gd-sec'><span class='gd-tag'>それどころか</span>放在句子開頭，接對方的話：「哪會，其實反而…」，會話很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>「迷惑だった？」「それどころか、すごく助かったよ。」</span>（「有給你添麻煩嗎？」「哪會，反而幫了我大忙。」）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面不要加だ：說<span class='gd-jp'>簡単どころか</span>，不說簡単だどころか。<br>・「別說A，連B都」的順序別放反：A放<b>比較難的</b>，B放<b>比較基本的</b>。要說「漢字どころか、ひらがなも読めない」，倒過來說「ひらがなどころか、漢字も読めない」，意思就怪掉了。<br>・A和B都是好事、只是想「再補充一個」的時候，不能用どころか：「這家店好吃，而且便宜」不能說美味しいどころか安い，要用<span class='gd-jp'>ばかりか</span>或<span class='gd-jp'>だけでなく</span>。<br>・どころか帶著「出乎意料、有點傻眼」的情緒，適合講令人意外的結果，平鋪直敘的事情不要硬套。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是下雨天：<br><b>ばかりか</b>＝A<b>成立</b>，再加碼B：<span class='gd-jp'>雨ばかりか、雷まで鳴りだした。</span>（不只下雨，連雷都打起來了）<br><b>どころか</b>＝A<b>被推翻</b>，實際相反：<span class='gd-jp'>雨がやむどころか、どんどん強くなっている。</span>（雨哪裡有要停，反而越下越大）<br><b>どころじゃない</b>＝現在<b>根本沒餘力</b>做A：<span class='gd-jp'>雨がひどくて、花見どころじゃない。</span>（雨大成這樣，哪有辦法賞花）</div><div class='gd-warn'>判斷小訣竅：「不只A，還B」是ばかりか；「哪是A，根本相反」是どころか；「現在哪有空/心情A」是どころじゃない。</div>",
  "n2-26": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ばかりか」「〜ばかりでなく」就是中文的<b>「不只～，連～也」「不但～，而且～」</b>。先講一件事，再往上<b>加碼</b>一件。日常口語比較常說「〜だけじゃなくて」，ばかりか、ばかりでなく聽起來比較正式，文章、新聞、演講很常出現。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>好事加碼</span>優點一個接一個。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いばかりでなく、味もいい。</span>（這家店不只便宜，味道也很好）</div><div class='gd-ex-line'>・<span class='gd-jp'>その歌は子どもばかりか、大人にも人気がある。</span>（那首歌不只小孩，連大人也很喜歡）</div><div class='gd-sec'><span class='gd-tag'>壞事加碼</span>已經很糟了，結果還有更糟的。ばかりか特別常用在這種「居然還～」的時候，帶一點驚訝或不滿。</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻したばかりか、資料も忘れてきた。</span>（不但遲到，連資料都忘了帶）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は謝らないばかりか、文句まで言ってきた。</span>（他不但不道歉，還反過來抱怨）</div><div class='gd-sec'>後半句常搭配<b>「も」「まで」「さえ」</b>，表示「連～都」，加碼的感覺會更清楚。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接　<span class='gd-pair'><span class='gd-jp'>遅刻した</span> → <span class='gd-jp'>遅刻したばかりか</span></span><br><b>い形容詞</b>：直接接　<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いばかりか</span></span><br><b>な形容詞</b>：要加「な」　<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利なばかりか</span></span><br><b>名詞</b>：直接接，不加だ　<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもばかりか</span></span><br>（比較正式的文章裡，な形容詞、名詞也可以用「である」來接，例如<span class='gd-jp'>学生であるばかりでなく</span>）<br>ばかりでなく的接法完全一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は交通が便利なばかりか、家賃も安い。</span>（這個城鎮不只交通方便，房租也便宜）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面不能加だ：說<span class='gd-jp'>日本語ばかりか</span>，不能說「日本語だばかりか」；な形容詞要記得加な：<span class='gd-jp'>きれいなばかりか</span>。<br>・<b>ばかりか後面不能接「請你～」「你給我～」「我要～」</b>這種要求或決心。這時候改用ばかりでなく（或だけでなく）：<span class='gd-jp'>肉ばかりでなく、野菜も食べなさい。</span>（不要只吃肉，青菜也要吃）說成「肉ばかりか、野菜も食べなさい」就不自然。<br>・不要跟單獨的「ばかり」搞混：<span class='gd-jp'>日本語ばかり勉強している</span>是「<b>只</b>讀日文」，<span class='gd-jp'>日本語ばかりか英語も勉強している</span>是「<b>不只</b>日文，英文也讀」。多了一個か，意思差很多。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>どころか</b>也常翻成「不但～」，但用法不一樣。關鍵在<b>前面那件事有沒有成立</b>。<br><b>ばかりか</b>：前面成立，後面再加碼。<br><span class='gd-jp'>彼は英語ばかりか、フランス語も話せる。</span>（他不只會英文，連法文也會：英文會）<br><b>どころか</b>：前面那件事根本談不上，甚至差更遠。<br><span class='gd-jp'>彼はフランス語どころか、英語も話せない。</span>（別說法文了，他連英文都不會：法文不會）<br><span class='gd-jp'>やせるどころか、太ってしまった。</span>（不但沒瘦，反而胖了）</div><div class='gd-sec'><b>のみならず</b>意思跟ばかりか、ばかりでなく差不多，只是更書面、更硬，多半出現在文章或正式場合。</div><div class='gd-warn'>判斷小訣竅：前面那件事「有」，再加一件，用ばかりか、ばかりでなく；前面那件事「根本沒有」，或結果完全相反，用どころか。後面要叫人做事，就選ばかりでなく。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「不只～」的家族，可以接著看<span class='gd-jp'>〜のみならず</span>、<span class='gd-jp'>〜はもちろん</span>、<span class='gd-jp'>〜上に</span>、<span class='gd-jp'>〜に限らず</span>，比較它們各自的語感。</div>",
  "n2-35": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ざるを得ない」就是<b>「不得不～」「只好～」</b>。心裡其實不太想，但情況擺在那裡，<b>沒有別的路可以選</b>，只能這樣做。像中文說「沒辦法，只好硬著頭皮去了」的那種感覺。</div><div class='gd-sec'>拆開看比較好記：<span class='gd-jp'>ざる</span>是古文的「不」，<span class='gd-jp'>得ない</span>是「不能」，合起來就是「<b>不能不做</b>」，所以等於「不得不」。<span class='gd-jp'>得ない</span>念<b>えない</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>情勢所逼</span>因為某個原因，被迫做自己不太想做的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>台風が来るので、旅行を中止せざるを得ない。</span>（因為颱風要來，只好取消旅行）</div><div class='gd-ex-line'>・<span class='gd-jp'>人が足りないので、休みの日も出勤せざるを得なかった。</span>（人手不夠，放假那天也只好去上班）</div><div class='gd-sec'><span class='gd-tag'>不得不承認・不得不說</span>常跟<span class='gd-jp'>認める</span>、<span class='gd-jp'>言う</span>一起用，意思是「雖然不想，但事實就是這樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力は認めざるを得ない。</span>（他的實力我不得不承認）</div><div class='gd-ex-line'>・<span class='gd-jp'>残念ながら、この計画は失敗だったと言わざるを得ない。</span>（很遺憾，不得不說這個計畫失敗了）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'>做法是先變成ない形，<b>把ない拿掉</b>，再加ざるを得ない。</div><div class='gd-sec'><b>第一類（五段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span> → 把ない拿掉 → <span class='gd-jp'>行かざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>従う</span> → <span class='gd-jp'>従わない</span> → <span class='gd-jp'>従わざるを得ない</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>諦める</span> → <span class='gd-jp'>諦めざるを得ない</span></span></div><div class='gd-sec'><b>第三類（兩個都是例外，直接背）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せざるを得ない</span></span>（不是しざる）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ざるを得ない</span>（こざるをえない）</span></div><div class='gd-sec'>過去式是<span class='gd-jp'>得なかった</span>，客氣一點說<span class='gd-jp'>得ません</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>する</span>要變<b>せざる</b>，寫成「しざるを得ない」是錯的。<span class='gd-jp'>中止する</span>、<span class='gd-jp'>出勤する</span>這種「名詞＋する」也一樣是<span class='gd-jp'>中止せざるを得ない</span>。<br>・<span class='gd-jp'>言う</span>、<span class='gd-jp'>従う</span>這種う結尾的，ない形是<b>わ</b>：<span class='gd-jp'>言わない</span>，所以是<span class='gd-jp'>言わざる</span>，不是「言あざる」。<br>・<span class='gd-jp'>得ない</span>念<b>えない</b>，不要念成とくない或うない。<br>・這是偏正式、偏書面的說法，新聞、報告、正式場合常見。跟朋友聊天講「不得不」，通常會用<span class='gd-jp'>行くしかない</span>這種說法比較自然。<br>・它帶有「其實不想」的味道，自己很想做的事不要用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>なければならない</b>＝規定上、道理上<b>該做</b>，不一定帶情緒：<br><span class='gd-jp'>明日は会議だから、早く行かなければならない。</span>（明天有會，得早點去）<br><b>ざるを得ない</b>＝本來不想，但<b>被情況逼到沒得選</b>：<br><span class='gd-jp'>熱があるが、代わりの人がいないので、行かざるを得ない。</span>（雖然發燒，但沒人能代班，只好去）</div><div class='gd-sec'><b>ずにはいられない</b>（長得很像，都有ず/ざる）＝心裡<b>壓不住、忍不住</b>，是情緒自己冒出來：<br><span class='gd-jp'>部長の冗談がおもしろくて、笑わずにはいられなかった。</span>（部長的笑話太好笑，忍不住笑了）<br><span class='gd-jp'>部長の冗談はつまらなかったが、笑わざるを得なかった。</span>（部長的笑話很無聊，但只好陪笑）</div><div class='gd-warn'>判斷小訣竅：單純「該做」用なければならない；「不想但沒得選」用ざるを得ない；「忍不住」用ずにはいられない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>常跟「既然～」一起出現：<span class='gd-jp'>上司の判断である以上、従わざるを得ない。</span>（既然是上司的判斷，就不得不服從）。可以接著學<span class='gd-jp'>〜上は</span>、<span class='gd-jp'>〜からには</span>這類「既然～就～」的說法。</div>",
  "n2-37": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜かねる」就像客服常說的<b>「這部分恕我們無法處理」</b>、公文裡的<b>「礙難照辦」</b>。字面上是「想做也不方便做」，其實是在<b>很客氣地拒絕</b>，或表示自己很為難。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>客氣拒絕</span>店員、客服、公司對外最常用。把「不行」講得很軟。</div><div class='gd-ex-line'>・<span class='gd-jp'>返品はお受けいたしかねます。</span>（恕不接受退貨）</div><div class='gd-ex-line'>・<span class='gd-jp'>その件についてはお答えしかねます。</span>（那件事恕我無法回答）</div><div class='gd-ex-line'>・<span class='gd-jp'>申し訳ございませんが、私ではわかりかねます。</span>（很抱歉，這部分我不太清楚）</div><div class='gd-sec'><span class='gd-tag'>心裡無法接受</span>立場或感情上過不去，沒辦法點頭。</div><div class='gd-ex-line'>・<span class='gd-jp'>その意見には賛成しかねます。</span>（那個意見我沒辦法贊成）</div><div class='gd-sec'><span class='gd-tag'>拿不定主意</span><span class='gd-jp'>決めかねる</span>是很常見的固定說法，意思是「猶豫、決定不了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>どちらにするか決めかねている。</span>（還在猶豫要選哪一個）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，把「ます」拿掉，再加「かねる」。<br><span class='gd-pair'><span class='gd-jp'>答えます</span> → <span class='gd-jp'>答えかねる</span></span><span class='gd-pair'><span class='gd-jp'>わかります</span> → <span class='gd-jp'>わかりかねる</span></span><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しかねる</span></span><br>想更客氣，就把する換成謙虛說法いたす：<span class='gd-pair'><span class='gd-jp'>いたします</span> → <span class='gd-jp'>いたしかねます</span></span><br>實際上最常聽到的是禮貌形<b>「〜かねます」</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>能力上做不到不能用</b>。「太重拿不動」要說<span class='gd-jp'>重くて持てない</span>，不能說重くて持ちかねる。かねる是規定、立場、心情上「不方便、不願意」。<br>・<span class='gd-jp'>わかりかねます</span>看起來沒有否定，意思卻是「我不清楚」，別聽成「我知道」。<br>・<b>かねます和かねません意思相反</b>：<span class='gd-jp'>お答えしかねます</span>是「無法回答」；<span class='gd-jp'>起こりかねません</span>是「很可能會發生」。只差一個ん，不要搞混。<br>・語氣很正式，跟朋友講會很怪，朋友之間說<span class='gd-jp'>ちょっと無理</span>就好。<br>・兩個慣用說法要另外記：<span class='gd-jp'>見るに見かねて手伝った</span>（看不下去就幫忙了）、<span class='gd-jp'>お待ちかねの新商品</span>（大家期待已久的新商品）。這兩個不是拒絕。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是客人要求退貨：<br><b>できない</b>＝直接說不行，比較硬：<span class='gd-jp'>返品はできません。</span>（不能退貨）<br><b>かねる</b>＝客氣委婉地拒絕：<span class='gd-jp'>返品はお受けいたしかねます。</span>（恕無法受理退貨）<br><b>がたい</b>不是拿來拒絕人，而是形容一件事「讓人很難～」：<span class='gd-jp'>信じがたい話だ。</span>（真是令人難以置信的事）<br><b>かねない</b>＝擔心壞事可能發生：<span class='gd-jp'>このままでは事故になりかねない。</span>（這樣下去很可能出事）</div><div class='gd-warn'>判斷小訣竅：客氣拒絕對方的要求，用かねる；形容事情讓人很難相信、很難接受，用がたい；擔心「搞不好會～」，用かねない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>下一課「〜かねない」，長得幾乎一樣、意思卻相反，剛好一起記。</div>",
  "n2-54": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜につれて」就是中文的<b>「隨著～，（就）漸漸～」</b>。前面那件事慢慢在變，後面那件事也跟著慢慢變。像「天氣越來越冷，喝熱飲的人越來越多」這種一起變的感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>動詞</span>辭書形（字典上查到的原本樣子）直接加につれて。<br><span class='gd-pair'><span class='gd-jp'>時間が経つ</span> → <span class='gd-jp'>時間が経つにつれて</span></span>（隨著時間過去）<br><span class='gd-pair'><span class='gd-jp'>慣れる</span> → <span class='gd-jp'>慣れるにつれて</span></span>（隨著習慣）</div><div class='gd-sec'><span class='gd-tag'>名詞</span>直接加につれて，但這個名詞本身要帶有「變化」的意思，像<span class='gd-jp'>成長</span>、<span class='gd-jp'>進化</span>、<span class='gd-jp'>変化</span>、<span class='gd-jp'>高齢化</span>。<br><span class='gd-pair'><span class='gd-jp'>成長</span> → <span class='gd-jp'>成長につれて</span></span>（隨著成長）</div><div class='gd-sec'>文章裡也常寫成短一點的「<span class='gd-jp'>につれ</span>」，意思一樣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>兩件事都是<b>一點一點慢慢變</b>的時候。後半句常會配「<span class='gd-jp'>〜てきた</span>」「<span class='gd-jp'>〜ていく</span>」「<span class='gd-jp'>〜くなる</span>」，把「漸漸」的感覺講出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の生活に慣れるにつれて、毎日が楽しくなってきた。</span>（隨著習慣日本的生活，每天變得越來越開心）</div><div class='gd-ex-line'>・<span class='gd-jp'>年を取るにつれて、体力が落ちてきた。</span>（隨著年紀增長，體力變差了）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの成長につれて、家が狭く感じるようになった。</span>（隨著孩子長大，開始覺得家裡變窄了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>一下子就結束的事不能用</b>。「畢業」「搬家」「結婚」是一次性的，不能說<span class='gd-jp'>卒業するにつれて</span>。前面一定要是會慢慢進行的變化。<br>・<b>後半句不能是「我要～」「請～」</b>。後面要寫自然跟著發生的變化，不能接自己的打算或叫別人做事。像「隨著日文變好，我們多聊天吧」這種句子就不能用につれて。<br>・<b>名詞不能隨便放</b>。<span class='gd-jp'>雨につれて</span>不行，因為「雨」本身不是變化；要說<span class='gd-jp'>雨が強くなるにつれて</span>（隨著雨越下越大）。<br>・中文「隨著」用得很寬，但日文につれて只管「兩邊同步慢慢變」，不要看到「隨著」就直接套。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>に伴って</b>：意思很接近，但比較正式，新聞、公告很常用；而且前面可以是<b>一次性的事</b>。<br>・<span class='gd-jp'>人口が増えるにつれて、ゴミの問題が深刻になった。</span>（隨著人口增加，垃圾問題變嚴重了）<br>・<span class='gd-jp'>人口が増えるに伴って、ゴミの問題が深刻になった。</span>（同上，語氣比較正式）<br>兩句都可以。可是換成搬家這種一次性的事：<br>・<span class='gd-jp'>引っ越しに伴って、住所が変わります。</span>（因為搬家，地址會變更）<br>這裡就不能用につれて。</div><div class='gd-sec'><b>に応じて</b>：「依照～而不同」，重點是對應關係，不是隨時間變化。<br>・<span class='gd-jp'>年齢に応じて、料金が違います。</span>（費用依年齡而不同）<br>這句是不同年齡的人價錢不一樣，不是一個人越長越大、價錢跟著變，所以不能用につれて。</div><div class='gd-warn'>判斷小訣竅：講得出「隨著～，漸漸～」就用につれて；比較正式，或前面是一次性的事件，用に伴って；意思是「依照～而不同」，用に応じて。</div>",
  "n2-2": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「辭書形＋ばかりだ」就是中文的<b>「只會越來越～」「有增無減」「每況愈下」</b>。事情一直往同一個方向變，看不到好轉或回頭的跡象，講的人通常帶著無奈或擔心。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>越來越糟</span>最常見的用法。抱怨物價、景氣、身體、工作量，都很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がるばかりだ。</span>（物價只漲不跌）</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなるばかりだった。</span>（爸爸的病只是一天比一天嚴重）</div><div class='gd-sec'><span class='gd-tag'>放在句子中間</span>改成「ばかりで」，後面接另一件讓人更無奈的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は増えるばかりで、給料は全然上がらない。</span>（工作只增不減，薪水卻完全沒漲）</div><div class='gd-sec'><span class='gd-tag'>偶爾用在好的方向</span>有，但比較少，大多是描述客觀趨勢。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店の人気は高まるばかりだ。</span>（這家店越來越受歡迎）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形（字典上查到的原形）＋ばかりだ。前面放的一定是<b>「會變化」的動詞</b>，像<span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>上がる</span>、<span class='gd-jp'>広がる</span>、<span class='gd-jp'>悪化する</span>。<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えるばかりだ</span></span><br>形容詞要先加「なる」變成「變得～」，再接ばかりだ：<br><span class='gd-pair'><span class='gd-jp'>悪い</span> → <span class='gd-jp'>悪くなる</span> → <span class='gd-jp'>悪くなるばかりだ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便になる</span> → <span class='gd-jp'>不便になるばかりだ</span></span><br>講過去的事就用<b>ばかりだった</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面如果不是變化動詞，意思會跑掉，變成「只是一直～」：<span class='gd-jp'>彼女はただ泣くばかりだった。</span>（她只是一直哭）這不是「越來越」。<br>・「<span class='gd-jp'>あとは</span>～ばかりだ」是「只差～了」：<span class='gd-jp'>準備はできた。あとは出発するばかりだ。</span>（都準備好了，就差出發）<br>・名詞＋ばかり是「淨是～」：<span class='gd-jp'>甘い物ばかり食べている。</span>（淨吃甜的）跟這裡的「越來越」是兩回事。<br>・講自己的進步不太會用它，說「日文越來越好」一般講<span class='gd-jp'>日本語がどんどん上手になっている</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>同樣是ばかり，前面接的形不同，意思完全不同：</b></div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりだ。</span>（我剛來日本：た形＋ばかり＝剛～）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日ゲームをしてばかりいる。</span>（每天老是在打電動：て形＋ばかりいる＝老是～）</div><div class='gd-ex-line'>・<span class='gd-jp'>帰国してから、日本語は忘れるばかりだ。</span>（回國之後，日文只會越忘越多：辭書形＋ばかりだ＝越來越～）</div><div class='gd-sec'><b>跟「～つつある」比：</b>兩個都講變化，但口氣不同。</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は回復しつつある。</span>（景氣正在慢慢恢復）</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は悪くなるばかりだ。</span>（景氣只會越來越差）</div><div class='gd-sec'>つつある只是冷靜描述「變化正在進行中」，偏書面、好壞都能用；ばかりだ強調「停不下來、只往一邊走」，帶著無奈。<br>另外還有一個<span class='gd-jp'>～一方だ</span>，意思跟ばかりだ幾乎一樣，常常可以互換：<span class='gd-jp'>人口は減る一方だ。</span>（人口只減不增）</div><div class='gd-warn'>判斷小訣竅：看ばかり前面——た形是「剛～」，て形是「老是～」，辭書形加上變化動詞就是「越來越～」。</div>",
  "n2-5": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たとたん（に）」就是中文的<b>「才剛一～，就突然～」</b>。像你一推開門，貓就衝出來；一站起來，就頭暈。前面那個動作才剛做完，後面就<b>冒出一件你沒料到的事</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成た形（就是過去式「～た」那個形），後面加とたん。「に」可加可不加，意思一樣。<br><span class='gd-pair'><span class='gd-jp'>開ける</span> → <span class='gd-jp'>開けたとたん</span></span><span class='gd-pair'><span class='gd-jp'>出る</span> → <span class='gd-jp'>出たとたん</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだとたんに</span></span><br>前面通常是一下子就完成的動作，像開門、出門、站起來、看到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>外面突然發生的事</span>別人、動物、天氣突然有動靜。</div><div class='gd-ex-line'>・<span class='gd-jp'>家を出たとたん、雨が降り出した。</span>（一出門就開始下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けたとたん、虫が入ってきた。</span>（一打開窗戶，蟲就飛進來了）</div><div class='gd-sec'><span class='gd-tag'>身體、心情不受控</span>自己身上發生的反應也可以，只要不是你故意做的。</div><div class='gd-ex-line'>・<span class='gd-jp'>立ち上がったとたん、めまいがした。</span>（一站起來就頭暈）</div><div class='gd-ex-line'>・<span class='gd-jp'>母の声を聞いたとたん、涙が出てきた。</span>（一聽到媽媽的聲音，眼淚就流出來了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面一定是た形：說<span class='gd-jp'>開けたとたん</span>，不能說「開けるとたん」。<br>・後面接的是<b>已經發生、出乎意料</b>的事，所以句尾通常是過去式。<br>・後面不能接「我要～」「～吧」「請～」這種意志、邀約、命令。「家に着いたとたん、電話してください」是錯的。<br>・後面也不能接<b>自己故意做的動作</b>。「家に帰ったとたん、シャワーを浴びた」不自然，因為洗澡是你自己決定要做的。這時候改用<span class='gd-jp'>家に帰ってすぐ、シャワーを浴びた。</span>（一回家就馬上洗澡）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜次第</b>也常翻成「一～就～」，但用法剛好相反。看同一個情境：<br><span class='gd-jp'>駅に着いたとたん、電車が行ってしまった。</span>（我一到車站，電車就開走了）<br>→ 已經發生、沒料到，用とたん。<br><span class='gd-jp'>駅に着き次第、連絡します。</span>（一到車站，我就跟你聯絡）<br>→ 還沒發生、是我<b>打算要做</b>的事，用次第。<br>次第接的是ます形把ます拿掉的樣子（<span class='gd-pair'><span class='gd-jp'>着きます</span> → <span class='gd-jp'>着き次第</span></span>），而且常用在工作、正式場合。</div><div class='gd-warn'>判斷小訣竅：後面是「突然冒出來、我控制不了的事」用とたん；後面是「我接下來會去做的事」用次第。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「とたん」也可以放在句子開頭，寫成「その途端」，意思是「就在那一瞬間」：<br><span class='gd-jp'>ドアを開けた。その途端、猫が飛び出した。</span>（我打開門。就在那一瞬間，貓衝了出來）</div>",
  "n2-6": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜次第」就是<b>「等～一好，就馬上～」</b>。像客服常講的「貨一到馬上通知您」「結果出來立刻跟您說」，那種<b>正式、有點商務感</b>的「一～就」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：先變成ます形，把ます拿掉，直接接次第。<br><span class='gd-pair'><span class='gd-jp'>届きます</span> → 把ます拿掉 → <span class='gd-jp'>届き次第</span></span><br><span class='gd-pair'><span class='gd-jp'>終わります</span> → <span class='gd-jp'>終わり次第</span></span><span class='gd-pair'><span class='gd-jp'>わかります</span> → <span class='gd-jp'>わかり次第</span></span><span class='gd-pair'><span class='gd-jp'>見つけます</span> → <span class='gd-jp'>見つけ次第</span></span></div><div class='gd-sec'><b>可以加する的動作名詞</b>（像<span class='gd-jp'>到着する</span>、<span class='gd-jp'>決定する</span>）：通常把する拿掉，名詞直接接次第。<br><span class='gd-pair'><span class='gd-jp'>到着する</span> → <span class='gd-jp'>到着次第</span></span><span class='gd-pair'><span class='gd-jp'>決定する</span> → <span class='gd-jp'>決定次第</span></span><br>（也會看到<span class='gd-jp'>到着し次第</span>，意思一樣。）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>我會馬上做</span>前面是「還沒發生、但等著它發生」的事，後面是說話者打算做的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物が届き次第、ご連絡いたします。</span>（包裹一到就會聯絡您）</div><div class='gd-ex-line'>・<span class='gd-jp'>詳しいことがわかり次第、お知らせします。</span>（詳細情況一確定就通知您）</div><div class='gd-sec'><span class='gd-tag'>請對方馬上做</span>後面也可以是請求、指示。</div><div class='gd-ex-line'>・<span class='gd-jp'>到着次第、お電話ください。</span>（一到就請打電話給我）</div><div class='gd-ex-line'>・<span class='gd-jp'>準備ができ次第、始めてください。</span>（準備好了就請開始）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>不能講已經發生的事</b>：「一到車站就下雨了」不能用次第。次第的後面是「接下來要做」的事，不會是過去式。<br>・後面要是<b>人能決定去做</b>的事（聯絡、出發、請對方做），不能接「下雨了」「嚇一跳」這種控制不了的結果。<br>・不能接辭書形：是<span class='gd-jp'>届き次第</span>，不是届く次第。<br>・語氣很正式，跟朋友講會顯得很生硬，朋友之間說<span class='gd-jp'>着いたらすぐ連絡するね</span>（到了馬上跟你說喔）就好。</div><div class='gd-h'>另一個意思：取決於～</div><div class='gd-sec'><span class='gd-tag'>名詞＋次第だ／次第で</span>「次第」還有一個常見用法，意思是「要看～」「取決於～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>成功するかどうかは、君の努力次第だ。</span>（成不成功，要看你的努力）</div><div class='gd-ex-line'>・<span class='gd-jp'>天気次第で、予定が変わるかもしれません。</span>（看天氣，行程可能會改）</div><div class='gd-sec'>這跟上面的「一～就」是兩回事。前面如果是<b>一般名詞</b>（努力、天氣、錢等），常用<b>次第だ／次第で</b>，意思是「取決於」；如果是<span class='gd-jp'>到着</span>、<span class='gd-jp'>決定</span>這類<b>能加する的動作名詞</b>，後面接著說要做的事，那就是「一～就」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「一到家就～」：<br><b>次第</b>＝還沒發生，<b>到時候我會馬上去做</b>：<span class='gd-jp'>家に着き次第、電話します。</span>（我一到家就打給你）<br><b>たとたん</b>＝已經發生，<b>那一瞬間突然冒出意外</b>：<span class='gd-jp'>家に着いたとたん、雨が降り出した。</span>（一到家就突然下起雨來）</div><div class='gd-warn'>判斷小訣竅：「還沒發生、等它好了我馬上去做」用次第；「已經發生、一瞬間出了意外」用たとたん。</div>",
  "n2-11": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ものの」就是中文的<b>「～是～了，可是…」</b>。像「票是買了，可是最後沒去成」：前面那件事是真的，你也承認，但後面的發展跟你本來以為的不一樣，常常帶一點「唉，結果沒做到」的感覺。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>做了但沒下文</span>最常見的用法。前面做了某件事，後面卻沒有照預期走下去。</div><div class='gd-ex-line'>・<span class='gd-jp'>チケットを買ったものの、結局行けなかった。</span>（票是買了，結果還是沒去成）</div><div class='gd-ex-line'>・<span class='gd-jp'>ジムに入会したものの、忙しくて一度しか行っていない。</span>（健身房是加入了，可是太忙只去過一次）</div><div class='gd-ex-line'>・<span class='gd-jp'>やると言ったものの、正直自信がない。</span>（話是說要做，老實說沒什麼把握）</div><div class='gd-sec'><span class='gd-tag'>前後有落差</span>前面的特點會讓人想到某個結果，後面卻不是那樣。後面不一定是壞事。</div><div class='gd-ex-line'>・<span class='gd-jp'>このアパートは駅から遠いものの、家賃が安い。</span>（這間公寓離車站是遠了點，但房租便宜）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>買った</span> → <span class='gd-jp'>買ったものの</span></span><span class='gd-pair'><span class='gd-jp'>遠い</span> → <span class='gd-jp'>遠いものの</span></span><br><b>な形容詞</b>：把「だ」換成「な」，或換成「である」。<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単なものの</span></span><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単であるものの</span></span><br><b>名詞</b>：把「だ」換成「である」。<br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるものの</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>とはいうものの</span>「話是這麼說，可是…」。可以接在句子後面，也可以單獨放句首。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>（雖說在日本住了十年，敬語還是不太行）</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエット中だ。とはいうものの、甘いものはやめられない。</span>（我在減肥。話是這麼說，甜食還是戒不掉）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞不能直接接「だ」：不是<span class='gd-jp'>静かだものの</span>，是<span class='gd-jp'>静かなものの</span>；名詞要用<span class='gd-jp'>学生であるものの</span>。<br>・後半句<b>不能接自己的打算、命令、請求</b>。不能說<span class='gd-jp'>高いものの、買おう</span>或<span class='gd-jp'>高いものの、買ってください</span>，這時候用「けど」：<span class='gd-jp'>高いけど、買おう</span>。<br>・前半句要是<b>已經是事實</b>的事。還沒發生、只是假設的事不能用。<br>・語氣偏正式，常出現在文章、新聞、正式場合。跟朋友聊天說<span class='gd-jp'>買ったけど、行けなかった</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ものの</b>＝「是～了，可是…」，重點是<b>承認前面，但結果有落差</b>，常帶遺憾：<br><span class='gd-jp'>チケットを買ったものの、行けなかった。</span>（票是買了，可是沒去成）<br><b>にもかかわらず</b>＝「明明～，卻～」，重點是<b>前後反差很大</b>，常帶驚訝或不滿，很常拿來講別人：<br><span class='gd-jp'>チケットを買ったにもかかわらず、彼は来なかった。</span>（明明都買了票，他卻沒來）<br><b>ものなら</b>只是長得像，意思完全不同，是「如果能～的話」：<br><span class='gd-jp'>行けるものなら、行きたかった。</span>（如果能去的話，我是很想去的）</div><div class='gd-warn'>判斷小訣竅：想說「～是～了，可是…」用ものの；想說「明明～卻～」用にもかかわらず；看到「如果能～」就是ものなら，不是逆接。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>意思接近、也是「雖然」的還有<span class='gd-jp'>とはいえ</span>、<span class='gd-jp'>つつも</span>、<span class='gd-jp'>ながらも</span>，可以放在一起比較。</div>",
  "n2-15": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にしても」就是中文的<b>「就算～，也～」</b>。先讓一步，承認對方的理由（好，就算你很忙），但結論不變（至少也該聯絡一聲吧）。很常帶著「這樣還是說不過去」的抱怨或批評口氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：普通形直接接。<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいにしても</span></span><span class='gd-pair'><span class='gd-jp'>知らなかった</span> → <span class='gd-jp'>知らなかったにしても</span></span><br><b>名詞、な形容詞</b>：現在式<b>不要加だ</b>，直接接；過去式用だった。<br><span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談にしても</span></span><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変にしても</span></span><span class='gd-pair'><span class='gd-jp'>冗談だった</span> → <span class='gd-jp'>冗談だったにしても</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>就算～也</span>讓一步，後面講自己的意見或不滿。前面常加「いくら」（再怎麼）。</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら忙しいにしても、返事ぐらいはしてほしい。</span>（再怎麼忙，至少也回個話吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にしても、言っていいことと悪いことがある。</span>（就算是開玩笑，也有分能說跟不能說的）</div><div class='gd-sec'><span class='gd-tag'>不管～都</span>前面放「何、どこ、誰」這類疑問詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>何をするにしても、健康が一番だ。</span>（不管做什麼，健康最重要）</div><div class='gd-sec'><span class='gd-tag'>AにしてもBにしても</span>不管 A 還是 B，結果都一樣。A、B 通常是同類的東西，或是兩個相反的選擇。</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにしても行かないにしても、早めに連絡してください。</span>（不管去不去，都請早點跟我說）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車にしてもバスにしても、朝は混む。</span>（不管電車還是公車，早上都很擠）</div><div class='gd-sec'><span class='gd-tag'>それにしても</span>變成一個固定的詞，意思是「就算這樣」「話說回來」，聊天超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>「バスが遅れたんだって。」「それにしても遅すぎるよ。」</span>（「聽說公車誤點了。」「就算這樣也太晚了吧。」）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面不要加だ：說<span class='gd-jp'>冗談にしても</span>，不能說「冗談だにしても」。<br>・後半句通常是<b>你的看法</b>：批評、不滿、建議、判斷，很常搭「はずだ」「べきだ」「〜てほしい」「〜ない」。<br>・中文「就算」可以很中性，但「にしても」常常帶有「我能理解，可是還是不行」的味道。對長輩直接說，可能聽起來像在指責。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にしては</b>＝「以～來說，竟然～」，結果<b>跟預期不一樣</b>：<br><span class='gd-jp'>初めてにしては上手だね。</span>（以第一次來說，算很厲害耶）<br><b>にしても</b>＝「就算是～，也～」，理由<b>不能當藉口</b>：<br><span class='gd-jp'>初めてにしても、これはひどすぎる。</span>（就算是第一次，這也太糟了）</div><div class='gd-sec'><b>にしろ・にせよ</b>：意思跟用法和にしても幾乎一樣，只是比較正式。<b>にしても</b>最口語，<b>にせよ</b>偏書面、正式場合。<br><span class='gd-jp'>いずれにしても、明日また連絡します。</span>／<span class='gd-jp'>いずれにせよ、明日また連絡します。</span>（無論如何，明天再跟你聯絡）</div><div class='gd-warn'>判斷小訣竅：想說「就算～也」用にしても；想說「以～來說竟然」用にしては。差一個字，意思差很多。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>比較正式的同義說法：<span class='gd-jp'>〜にしろ・〜にせよ</span>。</div>",
  "n2-18": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ものなら」有兩種意思，<b>看前面的動詞是什麼形</b>就分得出來：<br>・前面是<b>可能形</b>（<span class='gd-jp'>行ける</span>、<span class='gd-jp'>戻れる</span>）：「<b>要是能～就好了</b>（可是很難）」。就像中文嘆氣說「要是能重來一次就好了」。<br>・前面是<b>意向形</b>（〜よう、〜おう）：「<b>萬一～的話，就慘了</b>」。就像警告別人「你敢遲到一分鐘試試看」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>用法①：可能形＋ものなら</b>（可能形就是「能～」的形）<br><span class='gd-pair'><span class='gd-jp'>戻る</span> → <span class='gd-jp'>戻れるものなら</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられるものなら</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できるものなら</span></span></div><div class='gd-sec'><b>用法②：意向形＋ものなら</b>（意向形就是「〜よう／〜おう」那個形，所以常看到「〜ようものなら」）<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうものなら</span></span><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れようものなら</span></span><span class='gd-pair'><span class='gd-jp'>失敗する</span> → <span class='gd-jp'>失敗しようものなら</span></span></div><div class='gd-sec'>口語裡常把ものなら講成<b>もんなら</b>：<span class='gd-jp'>戻れるもんなら戻りたいよ。</span>（要是能回去，我也想回去啊）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>嘆氣的願望</span>用法①。你心裡知道很難、幾乎不可能，還是忍不住說「要是可以的話……」。後面通常接「〜たい」「〜てあげたい」這類願望。</div><div class='gd-ex-line'>・<span class='gd-jp'>戻れるものなら、高校時代に戻りたい。</span>（要是能回去，真想回到高中時代）</div><div class='gd-ex-line'>・<span class='gd-jp'>代われるものなら、代わってあげたい。</span>（要是能代替你就好了，真想替你承受）</div><div class='gd-ex-line'>・<span class='gd-jp'>休めるものなら、一週間ぐらい休みたい。</span>（要是能請假，真想休個一星期）</div><div class='gd-sec'><span class='gd-tag'>嗆聲</span>也是用法①，但後面接命令形「〜てみろ」。意思是「你做得到就做做看啊」，認定對方辦不到，故意挑釁。</div><div class='gd-ex-line'>・<span class='gd-jp'>やれるものなら、やってみろ。</span>（有本事你就做做看啊）</div><div class='gd-sec'><span class='gd-tag'>警告</span>用法②。意思是「只要做了～，就會很慘」，常跟「<span class='gd-jp'>少しでも</span>」「<span class='gd-jp'>一度でも</span>」「<span class='gd-jp'>一分でも</span>」一起用，誇張地強調後果有多可怕。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの父は、門限を一分でも過ぎようものなら、すごく怒る。</span>（我爸啊，門禁只要晚一分鐘回家，就會大發脾氣）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長の前でそんなことを言おうものなら、大変なことになるよ。</span>（要是在部長面前講那種話，事情就大條了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・用法①前面一定要用<b>可能形</b>：要說<span class='gd-jp'>行けるものなら</span>，不說行くものなら。<br>・用法②前面要用<b>意向形</b>：<span class='gd-jp'>言おうものなら</span>、<span class='gd-jp'>遅れようものなら</span>。兩種接法不要混在一起。<br>・用法①帶有「很難辦到」的感覺。如果事情其實很容易做到，用它會很怪，一般的「〜たら」就夠了。<br>・用法①後面通常接願望（〜たい）或命令（〜てみろ），不太接普通的敘述句。<br>・「<span class='gd-jp'>やれるものならやってみろ</span>」是在嗆人，對長輩、主管講保證吵架。<br>・兩種用法翻成中文都可能是「要是～的話」，但意思差很多：可能形是「好想，但做不到」，意向形是「千萬別做」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「想去」，用<b>〜たら</b>和<b>〜ものなら</b>講，你心裡的把握度不一樣：<br><b>〜たら</b>＝單純假設，真的有機會發生：<span class='gd-jp'>時間があったら、行きたい。</span>（有時間的話我想去）<br><b>〜ものなら</b>＝你自己覺得幾乎不可能，只是說說：<span class='gd-jp'>行けるものなら、行きたい。</span>（要是能去就好了……但大概去不了）</div><div class='gd-warn'>判斷小訣竅：覺得「有機會」就用たら；覺得「沒什麼希望，只是說說」就用可能形＋ものなら；要警告別人「敢做就完了」就用〜ようものなら。</div>",
  "n2-19": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ないことには」就是中文的<b>「不先～的話，根本沒辦法～」</b>。前面那件事是<b>門檻</b>，沒跨過去，後面就免談。像台灣人常講的「沒吃過怎麼知道好不好吃」「老闆沒點頭，什麼都不能做」，就是這種感覺。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>沒試過不知道</span>最常見的用法，前面幾乎都配「〜てみない」（不試試看）。</div><div class='gd-ex-line'>・<span class='gd-jp'>食べてみないことには、おいしいかどうかわからない。</span>（不吃吃看，就不知道好不好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>やってみないことには、何とも言えません。</span>（不實際做做看，我也很難說）</div><div class='gd-sec'><span class='gd-tag'>先決條件</span>某件事沒先完成，後面就沒辦法進行。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長がOKしないことには、この企画は進められない。</span>（部長沒點頭，這個企畫就沒辦法推動）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的ない形，後面直接加「ことには」。先複習ない形怎麼變：<br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加ない。<span class='gd-pair'><span class='gd-jp'>行く</span> → く換成か → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span>（う要變成わ）<br><b>第二類（一段動詞）</b>：把「る」拿掉，加ない。<span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>第三類</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span><br>接起來：<span class='gd-pair'><span class='gd-jp'>確認しない</span> → <span class='gd-jp'>確認しないことには</span></span></div><div class='gd-sec'>後半句最常接的幾個說法，直接整組記：<span class='gd-jp'>わからない</span>、<span class='gd-jp'>何とも言えない</span>、<span class='gd-jp'>始まらない</span>、<span class='gd-jp'>決められない</span>、<span class='gd-jp'>話にならない</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後半句要是<b>「沒辦法、不知道、不成立」</b>這種結果。不能接好的結果：<span class='gd-jp'>勉強しないことには、合格できる</span>是錯的。<br>・後半句也不能接命令、請求、邀約：<span class='gd-jp'>確認しないことには、電話してください</span>不自然。<br>・別跟「<span class='gd-jp'>〜ないことはない</span>」搞混，那是「也不是不～」：<span class='gd-jp'>行けないことはない</span>（也不是不能去）。差一個字，意思完全不同。<br>・語氣偏正式，在工作場合、文章裡常見，跟朋友聊天比較常說「<span class='gd-jp'>やってみないとわからない</span>」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ないことには</b>＝事情還沒發生，強調「<b>不先做就免談</b>」，後句只接負面：<br><span class='gd-jp'>住んでみないことには、その町のよさはわからない。</span>（沒實際住過，不會知道那個城市的好）<br><b>てはじめて</b>＝事情已經做了，「<b>做了之後才第一次</b>」體會到，後句是「才發現、才明白」的內容（好壞都可以）：<br><span class='gd-jp'>住んでみてはじめて、その町のよさがわかった。</span>（實際住了之後，才知道那個城市的好）<br><b>ないと／なければ</b>＝最一般的「如果不～」，後句限制比較少，可以接警告、結果、判斷等（但「<span class='gd-jp'>〜ないと</span>」後面不接「～ましょう」「～てください」這類意志、請求的句子）：<br><span class='gd-jp'>予約しないと、入れないよ。</span>（不預約的話會進不去喔）<br>換成「<span class='gd-jp'>予約しないことには、入れない</span>」也可以，但口氣更硬，像在強調「預約是絕對門檻」。</div><div class='gd-warn'>判斷小訣竅：想說「沒做之前免談」用ないことには；「做了才知道」用てはじめて；只是普通的「不～的話」，用ないと／なければ就好。</div>",
  "n2-29": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にすぎない」就是中文的<b>「只不過是～罷了」「充其量就是～」</b>。說話的人刻意把事情<b>往小裡說</b>，意思是「就只是這樣，沒什麼大不了」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接接，中間不加だ。<br><span class='gd-pair'><span class='gd-jp'>噂</span> → <span class='gd-jp'>噂にすぎない</span></span>（不過是謠言）<br><b>動詞</b>：用普通形（辭書形、た形）接。<br><span class='gd-pair'><span class='gd-jp'>従った</span> → <span class='gd-jp'>従ったにすぎない</span></span>（只是聽命行事）<br>要說過去就變成<b>にすぎなかった</b>，禮貌一點就說<b>にすぎません</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>把事情說小</span>強調「就只是這樣，別想太多」。</div><div class='gd-ex-line'>・<span class='gd-jp'>それはただの噂にすぎない。</span>（那不過是謠言而已）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は命令に従ったにすぎない。</span>（他只是聽命行事罷了）</div><div class='gd-sec'><span class='gd-tag'>數量很少</span>常跟「わずか」（區區）一起出現，強調數字少。</div><div class='gd-ex-line'>・<span class='gd-jp'>参加者はわずか5人にすぎなかった。</span>（參加的人只有區區 5 個）</div><div class='gd-sec'><span class='gd-tag'>被稱讚時謙虛</span>拿來講自己，就變成「我沒做什麼特別的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>私は当たり前のことをしたにすぎません。</span>（我只是做了該做的事而已）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>前面常加<span class='gd-jp'>ただの</span>、<span class='gd-jp'>単なる</span>（單純的）、<span class='gd-jp'>ほんの</span>（一點點）、<span class='gd-jp'>わずか</span>，把「只是」的感覺再加強。<br>句子還沒講完、要接下去時，會寫成<b>にすぎず</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>これは一つの例にすぎず、問題はほかにもたくさんある。</span>（這只是其中一個例子，問題還有很多）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面<b>不要加だ</b>：寫<span class='gd-jp'>噂にすぎない</span>，不是「噂だにすぎない」。<br>・它跟「〜すぎる」（太～）是兩回事。<span class='gd-jp'>高すぎない</span>是「不會太貴」；<span class='gd-jp'>にすぎない</span>前面一定有「に」，意思是「只不過是」。<br>・語氣偏正式，新聞、報告、演講很常見。跟朋友聊天，說<span class='gd-jp'>ただの噂だよ</span>、<span class='gd-jp'>〜だけだよ</span>比較自然。<br>・它帶有「不值一提」的評價。拿來講別人，像<span class='gd-jp'>彼はまだ新入社員にすぎない</span>，可能聽起來有點看不起人；拿來講自己，才會變成謙虛。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にすぎない</b>＝把事情<b>往小說</b>，「只不過是～」：<br><span class='gd-jp'>今回の成功は偶然にすぎない。</span>（這次成功不過是碰巧而已）<br><b>にほかならない</b>＝<b>斬釘截鐵地說</b>「正是～，不是別的」：<br><span class='gd-jp'>今回の成功はみんなの努力の結果にほかならない。</span>（這次成功正是大家努力的結果）<br>兩個都是「〜にＸない」，中文也都能翻成「無非是」，所以很容易混。其實語氣剛好相反：前者是貶低，後者是強力肯定。</div><div class='gd-warn'>判斷小訣竅：想說「沒什麼了不起」用にすぎない；想說「就是它，沒有別的」用にほかならない。</div>",
  "n2-41": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に違いない」就是中文的<b>「一定是～」「肯定是～」</b>。你看到某個線索，心裡很有把握地下結論，像偵探在推理：「燈亮著，裡面<b>一定</b>有人」。它講的是你的<b>推測</b>，不是確定的事實。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>看到線索下結論</span>眼前有證據或狀況，讓你很確定。</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がついている。誰かいるに違いない。</span>（燈亮著，一定有人在）</div><div class='gd-ex-line'>・<span class='gd-jp'>顔がそっくりだ。あの二人は兄弟に違いない。</span>（長得一模一樣，那兩個人一定是兄弟）</div><div class='gd-sec'><span class='gd-tag'>推測過去的事</span>前面用過去式，猜「當時一定是～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はもう知っていたに違いない。</span>（她一定早就知道了）</div><div class='gd-sec'>常常跟<span class='gd-jp'>きっと</span>一起出現，語氣更肯定：<span class='gd-jp'>きっと疲れているに違いない。</span>（他一定很累）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接，現在、過去、否定都可以。<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るに違いない</span></span><span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たに違いない</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないに違いない</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いに違いない</span></span></div><div class='gd-sec'><b>な形容詞、名詞</b>：把「だ」拿掉再接。<br><span class='gd-pair'><span class='gd-jp'>大変だ</span> → <span class='gd-jp'>大変に違いない</span></span><span class='gd-pair'><span class='gd-jp'>犯人だ</span> → <span class='gd-jp'>犯人に違いない</span></span><br>比較正式的文章也會寫成<span class='gd-jp'>犯人であるに違いない</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞後面不能留「だ」：<span class='gd-jp'>大変だに違いない</span>是錯的。<br>・中文的「一定」也有「一定要做」的意思（你一定要來喔），但「に違いない」只有「猜得很有把握」的意思，不能拿來要求別人。<br>・自己清楚知道的事不用它。說自己的身分、心情時用<span class='gd-jp'>私は学生に違いない</span>，聽起來像在猜自己，很奇怪。<br>・它帶一點書面、小說的味道。跟朋友聊天時，日本人更常說<span class='gd-jp'>きっと〜だよ</span>或<span class='gd-jp'>〜に決まってる</span>。<br>・禮貌說法是<span class='gd-jp'>〜に違いありません</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>はず</b>＝根據已知的事實或安排，「照理說應該～」：<br><span class='gd-jp'>昨日送ったから、今日届くはずだ。</span>（昨天寄的，照理說今天會到）<br><b>に違いない</b>＝看到線索，推理出結論：<br><span class='gd-jp'>窓が割れている。泥棒が入ったに違いない。</span>（窗戶破了，一定是小偷闖進來）<br>這句換成はず就不自然，因為你不是照著已知的安排在推算，而是看到現場才下的判斷。另外，はず可以接「結果卻不是這樣」：<span class='gd-jp'>来るはずなのに来ない。</span>（照理說會來，卻沒來）に違いない沒有這種用法。</div><div class='gd-sec'><b>に決まっている</b>＝「當然是～啦」，更主觀、口語，常帶情緒：<br><span class='gd-jp'>そんな話、嘘に決まってるよ。</span>（那種話當然是騙人的啦）<br><b>に相違ない</b>＝意思跟に違いない一樣，但更硬、更書面，大多出現在文章裡。</div><div class='gd-warn'>判斷小訣竅：照道理、照安排推算用「はず」；看到線索推出結論用「に違いない」；聊天時有情緒的「當然是～啦」用「に決まってる」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看同樣表示有把握的<span class='gd-jp'>〜に決まっている</span>和<span class='gd-jp'>〜に相違ない</span>，把語氣和場合的差別分清楚。</div>",
  "n2-43": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に相違ない」就是「〜に違いない」的<b>西裝版</b>，意思是「一定是～」「肯定是～」。你心裡很有把握，但它<b>還是推測</b>。口氣很像中文寫在報告、新聞評論裡的「想必是～」「必定是～」，平常聊天不會這樣講。</div><div class='gd-sec'>先認識這個詞：<span class='gd-jp'>相違</span>念<b>そうい</b>，意思是「不一樣、有出入」。所以<span class='gd-jp'>相違ない</span>字面上就是「沒有出入」，也就是「錯不了」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞、い形容詞：直接接普通形（就是沒有ます、です的說法）。<br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>知っているに相違ない</span></span>（一定知道）<br><span class='gd-pair'><span class='gd-jp'>高かった</span> → <span class='gd-jp'>高かったに相違ない</span></span>（當時一定很貴）</div><div class='gd-sec'>名詞、な形容詞：<b>不加だ</b>，直接接。<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼に相違ない</span></span>（一定是他）<br><span class='gd-pair'><span class='gd-jp'>有名</span> → <span class='gd-jp'>有名に相違ない</span></span>（一定很有名）<br>過去的話用<span class='gd-jp'>だった</span>：<span class='gd-jp'>彼だったに相違ない</span>（當時一定是他）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>書面推測</span>報告、論文、新聞評論、推理小說裡，根據線索下判斷。</div><div class='gd-ex-line'>・<span class='gd-jp'>犯人はこの近くに住んでいるに相違ない。</span>（犯人一定住在這附近）</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は全員の努力の賜物に相違ない。</span>（這個結果一定是大家努力換來的）</div><div class='gd-sec'><span class='gd-tag'>禮貌版</span>改成<span class='gd-jp'>〜に相違ありません</span>，在正式場合講出自己的推測。</div><div class='gd-ex-line'>・<span class='gd-jp'>犯人はあの男に相違ありません。</span>（犯人一定是那個男人）</div><div class='gd-sec'><span class='gd-tag'>確認事實：作證、文件</span>這一類<b>不是推測</b>。在作證、回答警察、填寫文件時，<span class='gd-jp'>相違ありません</span>是固定說法，意思是「確實如此、沒有錯」，講的是自己本來就知道的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の財布に相違ありません。</span>（這確實是我的錢包）</div><div class='gd-ex-line'>・<span class='gd-jp'>上記のとおり相違ありません。</span>（以上所述屬實）</div><div class='gd-sec'>第二句常印在申請書、切結書最後面，前面沒有に，因為意思是「跟上面寫的沒有出入」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面<b>不能加だ</b>：是<span class='gd-jp'>彼に相違ない</span>，不是彼だに相違ない。<br>・<span class='gd-jp'>相違</span>的「相」念<b>そう</b>，整個念そういない。<br>・跟朋友說<span class='gd-jp'>あの店、おいしいに相違ない</span>會很怪，像在演偵探劇。口語請用<span class='gd-jp'>おいしいに違いない</span>或<span class='gd-jp'>きっとおいしいよ</span>。<br>・當作推測用的時候，核心是有把握的推測，自己親眼確認過、本來就知道的事，不會用「〜に相違ない」來推測。但<span class='gd-jp'>相違ありません</span>當作確認、證明的固定說法時例外（就是上面作證、文件那一類）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：他成功了，原因是什麼？<br><b>に違いない</b>＝一般的「一定是～」，口語、書面都能用：<br><span class='gd-jp'>彼が成功したのは、努力したからに違いない。</span>（他會成功，一定是因為努力）<br><b>に相違ない</b>＝意思一樣，但更硬、更正式，幾乎只出現在文章裡：<br><span class='gd-jp'>彼が成功したのは、努力したからに相違ない。</span>（他之所以成功，必定是因為努力）<br><b>に決まっている</b>＝口語，主觀上「當然是這樣啊」，常帶點不容反駁的語氣：<br><span class='gd-jp'>努力したからに決まってるよ。</span>（當然是因為他有努力啊）<br><b>にほかならない</b>＝不是推測，而是說話者<b>斷定</b>「不是別的，正是～」，用來說明原因或本質：<br><span class='gd-jp'>彼の成功は、努力の結果にほかならない。</span>（他的成功，正是努力的結果）</div><div class='gd-warn'>判斷小訣竅：一般推測用に違いない；同樣推測但要寫進報告、文章就用に相違ない；跟朋友講「當然是啊」用に決まっている；要強調「正是這個、不是別的」用にほかならない。</div>",
  "n2-50": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に伴って」就是中文新聞、公告裡的<b>「隨著～」「伴隨～」</b>。一件事發生或改變了，另一件事也跟著發生或改變。你在台灣看到的「因辦公室搬遷，電話號碼將有變更」這種公告句，日文就很常用它。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>一起慢慢變</span>前面一變，後面跟著變，常用在人口、經濟、氣溫這類慢慢變化的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>年を取るに伴って、体力が落ちてきた。</span>（隨著年紀增長，體力變差了）</div><div class='gd-ex-line'>・<span class='gd-jp'>気温の上昇に伴い、電気の使用量が増えている。</span>（隨著氣溫上升，用電量一直在增加）</div><div class='gd-sec'><span class='gd-tag'>順便帶出另一件事</span>前面是一次性的事件，因為它而附帶發生了另一件事。公告、新聞超常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>地震に伴い、津波が発生した。</span>（伴隨地震，發生了海嘯）</div><div class='gd-ex-line'>・<span class='gd-jp'>事務所の移転に伴い、電話番号が変わります。</span>（因辦公室搬遷，電話號碼將有變更）</div><div class='gd-ex-line'>・<span class='gd-jp'>工事に伴って、この道は来週から通れなくなります。</span>（因為施工，這條路下週起無法通行）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞＋に伴って</b>：最常見，而且多半是「增加、發展、普及、移轉」這種表示變化或事件的名詞。<br><span class='gd-pair'><span class='gd-jp'>人口の増加</span> → <span class='gd-jp'>人口の増加に伴って</span></span><br><b>動詞辭書形＋に伴って</b>，或中間加個の變成<b>のに伴って</b>，兩種都看得到。<br><span class='gd-pair'><span class='gd-jp'>人口が増える</span> → <span class='gd-jp'>人口が増えるに伴って</span></span><br><span class='gd-pair'><span class='gd-jp'>年を取る</span> → <span class='gd-jp'>年を取るのに伴って</span></span></div><div class='gd-sec'><b>に伴って</b>和<b>に伴い</b>意思一樣，<span class='gd-jp'>に伴い</span>更書面，新聞標題、公告最愛用。<br>後面要直接接名詞時，改成<b>に伴う＋名詞</b>：<span class='gd-jp'>台風に伴う大雨</span>（伴隨颱風而來的大雨）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「伴」念<b>ともなって</b>，不要被中文「伴奏」帶著念成ばん。<br>・它很正式，是新聞、報告、公告在用的。跟朋友聊「天氣變冷了大家都開始穿外套」，用它會像在念新聞稿，口語講<span class='gd-jp'>〜につれて</span>或乾脆用<span class='gd-jp'>〜と</span>比較自然。<br>・接名詞時記得名詞前面通常是「〜の〜」：是<span class='gd-jp'>経済の発展に伴って</span>，不要寫成経済が発展に伴って。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>につれて</b>也是「隨著～」，但它只管<b>「一點一點慢慢變，另一邊也一點一點跟著變」</b>。<br>同樣講人口，兩個都可以，只是語氣不同：<br><span class='gd-jp'>人口が増えるにつれて、町がにぎやかになった。</span>（隨著人口增加，鎮上變熱鬧了：說明、聊天都行）<br><span class='gd-jp'>人口の増加に伴って、住宅不足が深刻化した。</span>（隨著人口增加，住宅不足問題惡化：新聞、報告口吻）<br>但如果前面是<b>一次性的事件</b>，就只能用に伴って：<br>○<span class='gd-jp'>地震に伴い、津波が発生した。</span><br>×地震につれて、津波が発生した。（地震不是「慢慢變化」，不能用につれて）</div><div class='gd-warn'>判斷小訣竅：地震、搬家、施工這種「發生一次」的事，只能用に伴って；兩邊都在慢慢變的話兩個都行，聊天偏につれて，新聞、公告偏に伴って。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣講「前後連動」的還有<span class='gd-jp'>〜に応じて</span>（依照～而調整），例如<span class='gd-jp'>人数に応じて、部屋を選べます。</span>（可以依人數選房間）。它重點是「配合不同情況做對應」，不是「跟著變化」，可以拿來和に伴って對照著記。</div>",
  "n2-57": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜まい」可以想成意向形「〜よう」的<b>反面</b>，而且是文章裡才常見的硬說法。<span class='gd-jp'>行こう</span>是「我要去」，<span class='gd-jp'>行くまい</span>就是「我絕不去了」。它還有第二個意思「大概不會～吧」，很像中文書面語的「決不」和「想必不會」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>決心不做</span>自己下定決心「絕不再～」。常跟<span class='gd-jp'>二度と</span>（再也）一起出現，後面常接<span class='gd-jp'>と思う</span>、<span class='gd-jp'>と心に誓う</span>、<span class='gd-jp'>と決める</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店には二度と行くまい。</span>（那家店我絕不再去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>二度とあのようなミスは犯すまいと心に誓った。</span>（我在心裡發誓，絕不再犯那樣的錯）</div><div class='gd-sec'><span class='gd-tag'>推測不會</span>意思跟<span class='gd-jp'>ないだろう</span>一樣，用來猜別人或某件事「大概不會～吧」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は今さら戻ってくるまい。</span>（事到如今，他大概不會回來了吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことはあるまい。</span>（應該不至於有那種事吧）</div><div class='gd-sec'>怎麼分辨是哪一個：主詞是「我」，而且在講決心，就是第一種；主詞是別人或某件事，就是第二種。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>第一類（五段動詞）</b>：辭書形直接加まい。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまい</span></span><span class='gd-pair'><span class='gd-jp'>乗る</span> → <span class='gd-jp'>乗るまい</span></span><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまい</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉加まい，也可以不拿掉，直接用辭書形加まい，兩種都對。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べまい</span></span>／<span class='gd-jp'>食べるまい</span></div><div class='gd-sec'><b>第三類（する・来る）</b>：寫法比較多，看到都要認得。<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>するまい</span></span>／<span class='gd-jp'>すまい</span>（也有人說<span class='gd-jp'>しまい</span>）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るまい</span></span>／<span class='gd-jp'>来まい</span><br>「来まい」傳統念こまい，現代也常說きまい，兩種念法都看得到。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・第一類是<b>辭書形</b>加まい，不要接成「ない」的樣子：寫<span class='gd-jp'>行くまい</span>，不是「行かまい」，更不是「行かないまい」。<br>・まい本身就是否定，沒有肯定版。想說「我要做」就用意向形<span class='gd-jp'>行こう</span>。<br>・它<b>不能拿來叫別人不要做</b>。<span class='gd-jp'>あなたは行くまい</span>不是「你別去」，聽起來是「你大概不會去吧」。要叫人別去，請說<span class='gd-jp'>行かないで</span>。<br>・句尾直接用「〜まい」表示決心的時候，下決心的人是說話者自己。<br>・很書面、很硬。跟朋友聊天說<span class='gd-jp'>もう行くまい</span>會像小說旁白，口語說<span class='gd-jp'>もう二度と行かない</span>就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：猜他明天會不會來。<br><b>ないだろう</b>：一般說法，講話、寫文章都能用。<br>・<span class='gd-jp'>彼は明日来ないだろう。</span>（他明天大概不會來吧）<br><b>まい</b>：意思一樣，但是書面、生硬，語氣一樣保留，是「大概」。<br>・<span class='gd-jp'>彼は明日来るまい。</span>（他明天想必不會來）<br><b>っこない</b>：口語，而且很肯定，是「才不可能」。<br>・<span class='gd-jp'>あんなに怒っていたんだから、来っこないよ。</span>（他氣成那樣，才不可能來啦）</div><div class='gd-warn'>判斷小訣竅：平常講話用ないだろう；文章裡、語氣保留的「大概不會」用まい；聊天時斬釘截鐵的「才不可能」用っこない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>まい常出現在兩個固定說法裡：<br>「〜うが〜まいが」是「不管做不做」：<span class='gd-jp'>行こうが行くまいが、私の自由だ。</span>（去不去是我的自由）<br>「〜ではあるまいし」是「又不是～」：<span class='gd-jp'>子どもじゃあるまいし、一人で行けるよ。</span>（又不是小孩子，自己去得了啦）</div>",
  "n2-62": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に越したことはない」就是中文的<b>「能～當然最好」「～是再好不過了」</b>。它講的是大家都同意的道理，像在說「這還用說嗎」，口氣溫和，不是在命令人。</div><div class='gd-sec'>字面上，<span class='gd-jp'>越す</span>是「超過」，整句是「沒有比這個更好的事」，所以就變成「這樣最好」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞：辭書形或ない形＋に越したことはない<br><span class='gd-pair'><span class='gd-jp'>確認する</span> → <span class='gd-jp'>確認するに越したことはない</span></span>（確認一下當然最好）<br><span class='gd-pair'><span class='gd-jp'>使わない</span> → <span class='gd-jp'>使わないに越したことはない</span></span>（能不用當然最好）<br>い形容詞：直接接<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いに越したことはない</span></span><br>な形容詞、名詞：直接接，或加である（比較正式）<br><span class='gd-pair'><span class='gd-jp'>安全</span> → <span class='gd-jp'>安全に越したことはない</span></span>／<span class='gd-jp'>安全であるに越したことはない</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>講常識</span>單獨用，表示「這樣做準沒錯」。</div><div class='gd-ex-line'>・<span class='gd-jp'>準備は早いに越したことはない。</span>（準備當然是越早越好）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬は飲まないに越したことはない。</span>（藥能不吃當然最好）</div><div class='gd-sec'><span class='gd-tag'>後面接けど・が</span>這是最常見的用法：先承認「能那樣當然最好」，再說「但是現實上…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>経験はあるに越したことはないが、なくても大丈夫です。</span>（有經驗當然最好，沒有也沒關係）</div><div class='gd-ex-line'>・<span class='gd-jp'>値段は安いに越したことはないけど、品質も大事だよ。</span>（價錢當然越便宜越好，但品質也很重要喔）</div><div class='gd-sec'>徵人廣告很常看到第一句那種寫法，意思就是「不是必備條件，有的話加分」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要寫<b>越した</b>，不是越す：<span class='gd-jp'>越すことはない</span>是錯的。<br>・前面接<b>辭書形</b>，不接た形：<span class='gd-jp'>早く行ったに越したことはない</span>是錯的，要說<span class='gd-jp'>早く行くに越したことはない</span>。<br>・不要只看到後半的「ことはない」就以為是「不必」，意思剛好差很多（看下面比較）。<br>・它是「能做到當然好」，<b>不是「一定要」</b>。要強烈要求別人做，不會用這個。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：「急不急」。<br><b>ことはない</b>＝不必：<span class='gd-jp'>そんなに急ぐことはない。</span>（不用那麼急）<br><b>に越したことはない</b>＝當然最好：<span class='gd-jp'>急ぐに越したことはない。</span>（能快一點當然最好）</div><div class='gd-sec'>同一個情境：「早點出門」。<br><b>ほうがいい</b>＝直接給對方建議：<span class='gd-jp'>早く出たほうがいいよ。</span>（你最好早點出門）<br><b>に越したことはない</b>＝講一般道理，比較委婉、留餘地：<span class='gd-jp'>早く出るに越したことはない。</span>（早點出門當然最好）</div><div class='gd-sec'>另一個意思很像的：<b>に限る</b>＝「～最讚，就選它」，是自己的強烈推薦：<span class='gd-jp'>暑い日は冷たいビールに限る。</span>（熱天就是要喝冰啤酒）。に越したことはない是大家都認同的常識，口氣比較冷靜。</div><div class='gd-warn'>判斷小訣竅：看到「に越した」就想「再好不過」；只有「ことはない」是「不必」；要直接勸對方，用「ほうがいい」。</div>",
  "n2-1": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜つつある」就是中文的<b>「正在逐漸～」「日益～」</b>。它講的是一個<b>變化正在發生、還沒結束</b>，就像新聞常說的「氣溫持續上升」「景氣逐漸復甦」。語氣偏正式，多半出現在新聞、報告、文章裡。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>變化進行中</span>某件事正往一個方向慢慢變，而且現在還在變。</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は少しずつ回復しつつある。</span>（景氣正在慢慢復甦）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の人口は減りつつある。</span>（這個鎮的人口正在逐漸減少）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本でもキャッシュレス決済が広がりつつある。</span>（在日本，無現金支付也越來越普及）</div><div class='gd-sec'><span class='gd-tag'>一步步走向結果</span>搭配「消失、接近」這種一下子就完成的變化，意思是「正在一步步走向那個結果，但還沒到」。</div><div class='gd-ex-line'>・<span class='gd-jp'>台風が日本に近づきつつある。</span>（颱風正在逐漸接近日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>伝統的な祭りが消えつつある。</span>（傳統祭典正在逐漸消失）</div><div class='gd-sec'><span class='gd-tag'>講過去</span>改成「つつあった」，表示當時正在變。</div><div class='gd-ex-line'>・<span class='gd-jp'>当時、この町は大きく変わりつつあった。</span>（當時這個鎮正在發生很大的變化）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，再<b>把ます拿掉</b>，加上「つつある」。<br><span class='gd-pair'><span class='gd-jp'>増えます</span> → <span class='gd-jp'>増えつつある</span></span><span class='gd-pair'><span class='gd-jp'>進みます</span> → <span class='gd-jp'>進みつつある</span></span><br><span class='gd-pair'><span class='gd-jp'>回復します</span> → <span class='gd-jp'>回復しつつある</span></span><span class='gd-pair'><span class='gd-jp'>失われます</span> → <span class='gd-jp'>失われつつある</span></span><br>要講得禮貌一點，就說「つつあります」：<span class='gd-jp'>景気は回復しつつあります。</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接的是ます形，不是辭書形：要說<span class='gd-jp'>増えつつある</span>，不能說「増えるつつある」；要說<span class='gd-jp'>回復しつつある</span>，不能說「回復するつつある」。<br>・最後是<b>ある</b>，不是いる。<br>・只能接「會變化」的動詞，像<span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>変わる</span>、<span class='gd-jp'>広がる</span>、<span class='gd-jp'>進む</span>、「〜化する」。一般的動作不能用：「我正在吃飯」是<span class='gd-jp'>ご飯を食べている</span>，不能說「ご飯を食べつつある」。<br>・它很書面。跟朋友說「最近越來越冷了」，自然的說法是<span class='gd-jp'>最近、だんだん寒くなってきたね。</span>如果講成「寒くなりつつある」，聽起來會很像在播新聞。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜ている</b>：搭配「消失」這類動詞時，表示<b>已經變完了</b>。<br>・<span class='gd-jp'>その技術はもう失われている。</span>（那項技術已經失傳了）<br><b>〜つつある</b>：表示<b>還在變、還沒變完</b>。<br>・<span class='gd-jp'>その技術は失われつつある。</span>（那項技術正在逐漸失傳）<br>如果是「增加、減少」這類動詞，<span class='gd-jp'>人口が減っている</span>也可以表示「正在減少」，意思很接近；差別在つつある更強調「持續在變」的過程，而且比較正式。</div><div class='gd-sec'><b>〜ばかりだ</b>（接辭書形）：只往一個方向變，而且幾乎都是變糟，帶著擔心或抱怨的口氣。<br>・<span class='gd-jp'>景気は悪くなるばかりだ。</span>（景氣只會一直變差）<br><b>〜つつある</b>：單純描述變化，往好的方向、往壞的方向都可以。<br>・<span class='gd-jp'>景気は回復しつつある。</span>（景氣正在逐漸復甦）</div><div class='gd-sec'><b>〜つつ（も）</b>：後面沒有ある，意思就完全不同，是「一邊～」或「明明～卻」。<br>・<span class='gd-jp'>体に悪いと知りつつ、タバコがやめられない。</span>（明知道對身體不好，還是戒不了菸）</div><div class='gd-warn'>判斷小訣竅：看到「つつ＋ある」就翻成「正在逐漸～」；要說「已經變成～了」用ている；要說「只會越來越糟」用ばかりだ；只有「つつ」沒有ある，就是「一邊～／明明～」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是講變化，可以接著學「〜につれて」（隨著～），例如<span class='gd-jp'>年をとるにつれて、体力が落ちてきた。</span>（隨著年紀增長，體力變差了）</div>",
  "n2-3": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AからBにかけて」就是中文的<b>「從A到B這一帶／這段期間」</b>。重點在<b>「大概」</b>：起點跟終點都不是精準的一條線，而是一個模模糊糊的範圍。氣象預報說「今晚到明天會下雨」，不是說幾點幾分開始、幾點幾分停，日文就用にかけて。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>時間範圍</span>某件事發生在一段大概的期間裡。可能一直持續，也可能斷斷續續。</div><div class='gd-ex-line'>・<span class='gd-jp'>今夜から明日の朝にかけて、強い雨が降るでしょう。</span>（今晚到明天早上會下大雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>この辺りは、年末から正月にかけてとても混む。</span>（這一帶從年底到過年期間都很擠）</div><div class='gd-sec'><span class='gd-tag'>地點範圍</span>從某地到某地這一整片區域。氣象、新聞很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>九州から四国にかけて、大雨に注意してください。</span>（九州到四國一帶，請注意豪雨）</div><div class='gd-sec'><span class='gd-tag'>身體部位</span>日常生活也很常聽到，看醫生描述哪裡痛特別好用。</div><div class='gd-ex-line'>・<span class='gd-jp'>首から肩にかけてが痛いんです。</span>（我從脖子到肩膀這一帶都在痛）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本樣子：名詞＋から＋名詞＋にかけて<br><span class='gd-pair'><span class='gd-jp'>3月から4月</span> → <span class='gd-jp'>3月から4月にかけて</span></span><br><br>「から」那一半有時可以省略，只講「往～那邊、到～前後」：</div><div class='gd-ex-line'>・<span class='gd-jp'>週末にかけて、天気が崩れるでしょう。</span>（到週末前後，天氣會變差）</div><div class='gd-sec'>後面要接名詞的時候，變成<b>にかけての</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>春から夏にかけての季節が一番好きだ。</span>（我最喜歡春天到夏天的這段季節）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文「從A到B」都一樣講，但日文要分：<b>時間講得很精準</b>的，像上班時間、營業時間，要用<b>から～まで</b>。<br>　×<span class='gd-jp'>9時から6時にかけて働きます。</span><br>　○<span class='gd-jp'>9時から6時まで働きます。</span><br>・前面只能放<b>名詞</b>，而且是時間、地點、部位這種「可以畫出範圍」的東西。不能接動詞，也不能放人：說「從A先生到B先生」不用にかけて。<br>・後面接名詞時別忘了「の」：是<span class='gd-jp'>夏にかけての旅行</span>，不是夏にかけて旅行。<br>・語氣偏書面、偏正式，新聞、氣象、說明文最常見。日常聊天也聽得到，但講時間時，口語更常直接用から～まで。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>から～まで</b>＝起點跟終點<b>清清楚楚</b>：<span class='gd-jp'>会議は1時から3時までです。</span>（會議是一點到三點）<br><b>にかけて</b>＝<b>大概</b>在這段範圍裡：<span class='gd-jp'>午後から夕方にかけて雨が降る。</span>（下午到傍晚之間會下雨）<br><b>にわたって</b>＝強調<b>整段都涵蓋到、規模很大</b>，常接「3日間」「10年」「全国」這種表示長度、大小的詞：<span class='gd-jp'>雨が3日間にわたって降り続いた。</span>（雨連續下了整整三天）</div><div class='gd-sec'>另外，<b>にかけては</b>多了一個「は」，意思完全不同，是「論～這方面」：<span class='gd-jp'>料理の腕にかけては、彼に勝てる人はいない。</span>（論廚藝，沒人贏得了他）。看到「は」，後面又在誇某人很厲害，就是這個。</div><div class='gd-warn'>判斷小訣竅：時間精準用まで，大概一帶用にかけて，強調「整整一大段」用にわたって；多一個「は」而且在講能力，就是にかけては。</div>",
  "n2-4": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜末（に）」就是中文的<b>「經過一番～之後，最後…」</b>。前面是一段花了時間、費了力氣的過程（討論很久、煩惱很久、努力很久），後面接<b>最後出來的結果</b>。有點像你說「吵了一個晚上，最後決定去日本玩」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞</span>名詞＋の＋末（に）<br><span class='gd-pair'><span class='gd-jp'>議論</span> → <span class='gd-jp'>議論の末に</span></span>（經過討論之後）<br><span class='gd-pair'><span class='gd-jp'>苦労</span> → <span class='gd-jp'>苦労の末に</span></span>（經過一番辛苦之後）</div><div class='gd-sec'><span class='gd-tag'>動詞</span>動詞た形＋末（に）<br><span class='gd-pair'><span class='gd-jp'>悩む</span> → <span class='gd-jp'>悩んだ</span> → <span class='gd-jp'>悩んだ末に</span></span>（煩惱了很久之後）<br><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えた</span> → <span class='gd-jp'>考えた末に</span></span>（想了很久之後）</div><div class='gd-sec'>「に」可以省略，意思一樣。後面要接名詞時用「末の」：<span class='gd-jp'>悩んだ末の決断</span>（煩惱很久才做的決定）。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>後面常跟著「<span class='gd-jp'>ようやく</span>」「<span class='gd-jp'>やっと</span>」「<span class='gd-jp'>ついに</span>」，強調「總算」。</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、やっと契約が決まった。</span>（經過漫長的協商，合約終於談成了）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も迷った末に、この部屋に決めた。</span>（猶豫了好幾次，最後決定租這間）</div><div class='gd-sec'>結果不一定是好事，<b>壞結果也可以用</b>，「末」只是客觀交代最後怎麼了。</div><div class='gd-ex-line'>・<span class='gd-jp'>長い闘病の末に亡くなった。</span>（長期和病魔奮鬥之後，最後還是過世了）</div><div class='gd-ex-line'>・<span class='gd-jp'>悩んだ末、進学を諦めた。</span>（煩惱了很久，最後放棄升學）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞一定要用<b>た形</b>：是<span class='gd-jp'>悩んだ末</span>，不是「悩む末」。<br>・這裡的末念<b>すえ</b>，不是まつ。<br>・前面要是「一段過程」，像討論、努力、煩惱、交涉這種花時間的事。只寫時間不行：「3時間の末」不自然，要說<span class='gd-jp'>3時間の議論の末</span>。<br>・「時間名詞＋の末」是另一個意思「～底」：<span class='gd-jp'>来月の末に引っ越す</span>是「下個月底搬家」，不是「經過下個月之後」。<br>・後面接的是<b>已經出來的結果</b>，通常用過去式（決めた、決まった、出た），不會拿來接「～吧」「請～」。<br>・語氣偏正式，新聞、報告、正式說明常見；跟朋友聊天比較常說「<span class='gd-jp'>結局</span>」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同級的「<b>〜あげく（に）</b>」接法一樣（た形／名詞の），也是「經過一番～最後…」，差別在<b>說話的人的心情</b>。<br><b>末</b>＝客觀交代最後的結果，好、壞、中性都可以：<br><span class='gd-jp'>さんざん迷った末、何も買わなかった。</span>（猶豫了很久，最後什麼都沒買）<br><b>あげく</b>＝帶著不滿、無奈，有「搞了半天，結果竟然…」的感覺：<br><span class='gd-jp'>さんざん迷ったあげく、何も買わなかった。</span>（猶豫了老半天，結果什麼都沒買）<br>所以結果是好事的時候，像<span class='gd-jp'>努力の末に合格した</span>（努力之後考上了），一般不會換成あげく。</div><div class='gd-warn'>判斷小訣竅：單純交代結果用末；帶著抱怨、無奈，覺得「搞了半天竟然這樣」，用あげく。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>可以接著學<span class='gd-jp'>〜あげく（に）</span>，兩個一起練，更容易抓到語氣的差別。</div>",
  "n2-7": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜て以来」就是中文的<b>「自從～之後，就一直…」</b>。前面放一件過去發生的事當作<b>起點</b>，後面講從那時候到現在<b>一直是什麼狀態</b>。像「自從搬家之後，我每天早上都在跑步」這種句子。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞て形＋<span class='gd-jp'>以来</span>（念いらい）。你已經會て形了，直接接上去就好：<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て以来</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会って以来</span></span><span class='gd-pair'><span class='gd-jp'>卒業する</span> → <span class='gd-jp'>卒業して以来</span></span><br>被動也可以：<span class='gd-pair'><span class='gd-jp'>導入される</span> → <span class='gd-jp'>導入されて以来</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>一直保持到現在</span>後面常配「ている」「ずっと」。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来て以来、ずっとこのアパートに住んでいる。</span>（自從來日本，就一直住在這間公寓）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが生まれて以来、ゆっくり映画を見る時間がない。</span>（自從小孩出生，就沒時間好好看電影）</div><div class='gd-sec'><span class='gd-tag'>從那之後就沒再…</span>後面常配「一度も」「〜ていない」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼とけんかして以来、一度も話していない。</span>（自從跟他吵架，就一次都沒講過話）</div><div class='gd-sec'><span class='gd-tag'>從那之後變成…</span>配「〜ようになった」，變了之後一直維持到現在。</div><div class='gd-ex-line'>・<span class='gd-jp'>留学して以来、字幕なしでドラマが見られるようになった。</span>（自從去留學，就變得不用字幕也能看日劇了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接的是<b>て形</b>，不是た形：說<span class='gd-jp'>卒業して以来</span>，不能說「卒業した以来」。<br>・後面<b>不能放只發生一次的事</b>。「自從來日本，我去了一次京都」不能用以来：×日本に来て以来、一度京都へ行った。這種「之後做了某件事」要用<span class='gd-jp'>日本に来てから、京都へ行った。</span><br>・前面只能是<b>已經發生過</b>的事，不能拿來講未來的計畫。<br>・起點通常離現在有一段時間。「剛剛吃完午餐以來」中文怪，日文一樣怪。<br>・口氣偏正式、偏書面。朋友聊天時，很多人會改說<span class='gd-jp'>〜てから、ずっと</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「搬家」這件事：<br><b>てから</b>＝只是講先後順序，「做了A，然後B」：<br><span class='gd-jp'>引っ越してから、ジョギングを始めた。</span>（搬家之後，開始慢跑）<br><b>て以来</b>＝從那時候起<b>一直到現在</b>都這樣：<br><span class='gd-jp'>引っ越して以来、毎朝ジョギングしている。</span>（自從搬家，每天早上都在慢跑）<br><b>をきっかけに</b>＝強調那件事是<b>契機</b>，因為它才開始：<br><span class='gd-jp'>引っ越しをきっかけに、ジョギングを始めた。</span>（以搬家為契機，開始慢跑）</div><div class='gd-warn'>判斷小訣竅：後面的句子能補上「到現在都還是這樣」，就用て以来；只是「然後」就用てから；想說「因為這件事才開始」就用をきっかけに。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>以来</span>前面也可以直接放時間名詞，或用<span class='gd-jp'>それ以来</span>（從那之後）接上一句話：</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の春以来、彼から連絡がない。</span>（從去年春天開始，他就沒聯絡我了）</div><div class='gd-ex-line'>・<span class='gd-jp'>一度飲みすぎて倒れた。それ以来、お酒は飲んでいない。</span>（我曾經喝太多倒下，從那之後就沒再喝酒了）</div>",
  "n2-9": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜からこそ」就是中文的<b>「正因為～，才～」</b>。普通的「から」只是說出理由；加上「こそ」，就像拿螢光筆把理由畫起來，意思是<b>就是這個原因，不是別的</b>。它很常用在跟一般想法相反的時候。一般人覺得A會讓人不想做，你卻偏偏因為A才要做。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>「普通形」就是不加です・ます的說法。<br><b>動詞、い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>思う</span> → <span class='gd-jp'>思うからこそ</span></span><span class='gd-pair'><span class='gd-jp'>頑張った</span> → <span class='gd-jp'>頑張ったからこそ</span></span><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいからこそ</span></span><br><b>名詞、な形容詞</b>：中間要加「だ」。<br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族だからこそ</span></span><span class='gd-pair'><span class='gd-jp'>大切</span> → <span class='gd-jp'>大切だからこそ</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>強調真正的理由</span>告訴對方：我這樣做，原因就在這裡。</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたのことを思うからこそ、厳しく言うんです。</span>（正因為替你著想，我才說得這麼重）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日練習したからこそ、本番で落ち着いていられた。</span>（正因為每天練習，正式上場時才能那麼冷靜）</div><div class='gd-sec'><span class='gd-tag'>跟一般想法相反</span>照常理會往另一個方向想，你卻說「就是因為這樣才要～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいからこそ、休みの日を大切にしている。</span>（正因為忙，我才特別珍惜假日）</div><div class='gd-ex-line'>・<span class='gd-jp'>失敗したからこそ、わかったこともある。</span>（正因為失敗過，才懂了一些事）</div><div class='gd-sec'><span class='gd-tag'>だからこそ</span>放在句子開頭，接上一句講的內容，意思是「也正因為這樣」。這種用法非常常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は大変です。だからこそ、やりがいがあります。</span>（這份工作很辛苦。也正因為這樣，才有成就感）</div><div class='gd-sec'>後半句常常用「<span class='gd-jp'>のだ</span>」或「<span class='gd-jp'>んです</span>」結尾。加了以後會多一種「其實是這樣」的說明口氣，跟からこそ很搭。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞別忘了加「だ」：是<span class='gd-jp'>家族だからこそ</span>，不是「家族からこそ」。<br>・只能用「から」，不能換成「ので」：沒有「ので＋こそ」的說法。<br>・不要拿來講普通的、負面的小理由。像「我睡過頭所以遲到」，用<span class='gd-jp'>寝坊したから遅刻した</span>就好。說成「寝坊したからこそ遅刻した」會很怪，好像在強調睡過頭是什麼了不起的原因。<br>・中文要說「正因為…<b>才</b>…」，日文後半句不用另外找一個字來對應「才」，こそ已經把語氣帶出來了。<br>・這個說法感情很重，比較常出現在講真心話、演講、文章裡。日常閒聊小事一直用，會顯得很戲劇化。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>から</b>＝單純交代理由。<br>・<span class='gd-jp'>心配だから、電話した。</span>（因為擔心，所以打給你）<br><b>からこそ</b>＝強調「就是這個原因」，常用在對方誤會、或你想把話說重的時候。<br>・<span class='gd-jp'>心配だからこそ、何度も電話したんです。</span>（就是因為擔心你，我才一直打給你）</div><div class='gd-sec'><b>からには</b>＝既然～就要～，後面接決心或該做的事。<br>・<span class='gd-jp'>留学するからには、しっかり勉強したい。</span>（既然要去留學，就要好好念書）<br><b>からこそ</b>＝正因為～才～，後面接因此產生的結果或行動。<br>・<span class='gd-jp'>留学したからこそ、台湾の良さに気づいた。</span>（正因為去留學，我才發現台灣的好）</div><div class='gd-warn'>判斷小訣竅：中文講得出「既然～就要～」用からには；講得出「正因為～才～」用からこそ；只是一般的「因為～所以～」，用から就好。</div>",
  "n2-10": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にもかかわらず」就是中文的<b>「儘管～，卻還是～」</b>。前面先講一個事實，後面接一個<b>跟預期相反</b>的結果。它跟「のに」意思很像，但比較<b>正式、客觀</b>，新聞、報告、演講、商務場合很常見，跟朋友聊天比較少用。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>結果出乎意料</span>照理說應該怎樣，結果卻不是那樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も確認したにもかかわらず、同じミスをしてしまった。</span>（儘管確認了好幾次，還是犯了同樣的錯）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が集まった。</span>（儘管下雨，還是來了很多人）</div><div class='gd-sec'><span class='gd-tag'>描述現在的狀況</span>後面不一定要用過去式，正在持續的事也可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>反対が多いにもかかわらず、政府は計画を進めている。</span>（儘管反對聲浪很大，政府還是在推動計畫）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はお金持ちであるにもかかわらず、質素な生活をしている。</span>（他雖然很有錢，卻過著簡樸的生活）</div><div class='gd-sec'><span class='gd-tag'>正式場合的感謝</span>致詞、商務信件常聽到的固定說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>本日はお忙しいにもかかわらず、お集まりいただきありがとうございます。</span>（今天各位在百忙之中仍撥空前來，非常感謝）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：普通形（就是字典上的樣子，或是た形、ない形）直接接。<br><span class='gd-pair'><span class='gd-jp'>努力した</span> → <span class='gd-jp'>努力したにもかかわらず</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いにもかかわらず</span></span></div><div class='gd-sec'><b>名詞、な形容詞</b>：不能加「だ」，要嘛直接接，要嘛加「である」。<br><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨にもかかわらず</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにもかかわらず</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便にもかかわらず</span></span>（也可以說<span class='gd-jp'>不便であるにもかかわらず</span>）<br>過去的話用「だった」就可以：<span class='gd-jp'>学生だったにもかかわらず</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面<b>不能加だ</b>：說<span class='gd-jp'>雨にもかかわらず</span>，不是「雨だにもかかわらず」。<br>・後半講的是<b>事實</b>（已經發生、或目前正在持續的狀況），不能接「～吧」「請～」「我要～」這類意志、邀約、命令、請求。想說「儘管下雨，我們還是出門吧」要用ても：<span class='gd-jp'>雨でも出かけよう。</span><br>・前半也要是<b>事實</b>。中文的「即使、就算」常常是假設（還沒發生），那種要用「ても」，不能用にもかかわらず。<br>・它很正式，跟朋友抱怨「我都說了你還不聽」用のに比較自然，用にもかかわらず會像在念新聞稿。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>のに</b>＝帶著<b>自己的情緒</b>（不滿、可惜、驚訝），口語很常用，還可以放在句尾話講一半。<br><b>にもかかわらず</b>＝比較<b>冷靜客觀</b>地陳述，正式、偏書面。</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も説明したのに、全然わかってくれない！</span>（我都講了好幾次了，你怎麼都聽不懂！）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も説明したにもかかわらず、理解してもらえなかった。</span>（儘管說明了好幾次，還是沒能讓對方理解）</div><div class='gd-sec'><span class='gd-jp'>せっかく作ったのに。</span>（虧我還特地做了）這種講到一半就停的用法，只有のに可以，にもかかわらず不行。</div><div class='gd-sec'>另一個超容易看錯的是少了「も」的<b>にかかわらず</b>，意思完全不一樣，是<b>「不管～」</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢にかかわらず、誰でも参加できます。</span>（不管幾歲，誰都可以參加）</div><div class='gd-ex-line'>・<span class='gd-jp'>天気にかかわらず、試合は行います。</span>（不管天氣如何，比賽照常舉行）</div><div class='gd-warn'>判斷小訣竅：想抱怨、帶情緒就用のに；正式、客觀地說「儘管～還是～」用にもかかわらず。看到「にかかわらず」先找有沒有「も」：有も是「儘管」，沒有も是「不管」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>放在句子開頭變成「<span class='gd-jp'>それにもかかわらず</span>」，意思是「儘管如此」，用來接前一句：<span class='gd-jp'>何度も注意された。それにもかかわらず、彼は遅刻を続けた。</span>（他被提醒了好幾次。儘管如此，他還是一直遲到）<br>同一級的<span class='gd-jp'>ものの</span>、<span class='gd-jp'>とはいえ</span>也是「雖然～但是～」，可以接著比較著學。</div>",
  "n2-12": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とはいえ」就是中文的<b>「雖說～，但是…」「話是這麼說沒錯，可是…」</b>。前面先承認一個事實，後面補一句：「不過，事情沒有你想的那麼簡單。」<br>像你說「雖說是春天，早上還是很冷」，你承認現在是春天，但「春天＝溫暖」這個印象不完全對。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>雖說是～</span>前面是一個事實，大家聽了會有某種印象，後面講實際情況跟這個印象不一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、朝晩はまだ寒い。</span>（雖說是春天，早晚還是很冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に5年住んでいるとはいえ、敬語はまだ苦手だ。</span>（雖說在日本住了五年，我還是不太會用敬語）</div><div class='gd-ex-line'>・<span class='gd-jp'>安いとはいえ、毎日買うと結構な金額になる。</span>（雖說便宜，每天買也是一筆不小的錢）</div><div class='gd-sec'><span class='gd-tag'>放句首</span>單獨放在句子開頭，意思是「話雖如此」，用來接前一句。</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変だ。とはいえ、辞めるつもりはない。</span>（工作很辛苦。話雖如此，我也沒打算辭職）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞、い形容詞：直接接。<br><span class='gd-pair'><span class='gd-jp'>慣れている</span> → <span class='gd-jp'>慣れているとはいえ</span></span><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したとはいえ</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいえ</span></span><br>名詞、な形容詞：後面的「だ」<b>通常省略</b>，直接接とはいえ（加だ也可以）。<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春とはいえ</span></span><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利とはいえ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>便利とはいえ、スマホばかり見るのはよくない。</span>（雖說很方便，一直盯著手機還是不好）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「は」念<b>わ</b>：とはいえ念「とわいえ」。<br>・前面一定是<b>已經成立的事實</b>，不能放還沒發生的假設。「就算明天下雨」要說<span class='gd-jp'>明日雨が降っても</span>，不能用とはいえ。<br>・後半一定是「跟預期不一樣」的內容，常跟<span class='gd-jp'>まだ</span>、<span class='gd-jp'>やはり</span>一起出現。它不是「所以」，後面不能接順著前面說下去的話。<br>・とはいえ帶點書面、正式的感覺。朋友聊天比較常說<span class='gd-jp'>とは言っても</span>或<span class='gd-jp'>って言っても</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ものの</b>也是「雖然～但是」，但最自然的用法是「<b>做了某件事，結果卻不如預期</b>」：<br>・<span class='gd-jp'>チケットを買ったものの、結局行けなかった。</span>（票是買了，結果還是沒去成）<br>前面如果是名詞，ものの要寫成「名詞＋である＋ものの」，比較生硬。這時候用とはいえ就很順：<br>・<span class='gd-jp'>プロとはいえ、ミスすることもある。</span>（雖說是職業選手，也會有失誤的時候）</div><div class='gd-sec'><b>にもかかわらず</b>是「儘管～，卻…」，強調結果<b>出乎意料</b>，常帶有驚訝或責備的語氣：<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（儘管下雨，還是來了很多人）<br>とはいえ沒有那麼強的意外感，比較像是承認前面的事實之後，冷靜地補一句「不過…」。</div><div class='gd-warn'>判斷小訣竅：「雖說是～（這個身分、狀態），但不代表…」用とはいえ；「做了～，結果卻沒…」用ものの；「儘管～，竟然還…」用にもかかわらず。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>意思幾乎一樣的<span class='gd-jp'>とはいうものの</span>，也能放句首當「話雖如此」：<span class='gd-jp'>とはいうものの、やはり心配だ。</span>（話雖如此，還是很擔心）</div>",
  "n2-13": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜くせに」就是中文的<b>「明明～還～」「虧你還～」</b>，而且是帶著火氣講的。聽到有人說「<span class='gd-jp'>知ってるくせに</span>」，意思不只是「明明知道」，背後還有一句「你很過分欸」。它不是客觀描述，是在<b>念人、數落人</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞、い形容詞：直接接（現在、過去都可以）<br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>知っているくせに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いくせに</span></span><span class='gd-pair'><span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったくせに</span></span><br>な形容詞：留著<b>な</b>再接　<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なくせに</span></span><br>名詞：加<b>の</b>再接　<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものくせに</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>數落別人</span>前面講對方的條件，後面講他做出不像話的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>知っているくせに、教えてくれない。</span>（明明知道，卻不告訴我）</div><div class='gd-ex-line'>・<span class='gd-jp'>行くって言ったくせに、来なかった。</span>（明明說要去，結果沒來）</div><div class='gd-ex-line'>・<span class='gd-jp'>下手なくせに、いつも自慢する。</span>（明明就很爛，還老愛炫耀）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものくせに、生意気なことを言うな。</span>（小孩子還敢講這種自以為是的話）</div><div class='gd-sec'><span class='gd-tag'>話只講一半</span>後半句不講，直接停在くせに，常帶點撒嬌或吐槽的語氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>本当は好きなくせに。</span>（明明就喜歡嘛）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞和な形容詞<b>不能接だ</b>：是<span class='gd-jp'>子どものくせに</span>、<span class='gd-jp'>下手なくせに</span>，不是「子どもだくせに」「下手だくせに」。<br>・前後講的要是<b>同一個人</b>。「他明明知道，<b>他</b>卻不講」可以；前後主角不同，就不能用くせに。<br>・語氣很衝，等於在罵人，<b>不要對上司、客人、長輩用</b>，也不適合寫在正式文件裡。<br>・大多是在念別人。用在自己身上，就是在自嘲：<span class='gd-jp'>日本人のくせに、漢字が苦手なんです。</span>（我身為日本人，卻不太會寫漢字）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：他明明知道答案，卻不告訴我。<br><b>くせに</b>＝不爽、在怪他：<span class='gd-jp'>彼は知っているくせに、教えてくれない。</span><br><b>のに</b>＝覺得意外、可惜，語氣比較平：<span class='gd-jp'>彼は知っているのに、教えてくれない。</span><br><b>にもかかわらず</b>＝正式、書面、不帶情緒：<span class='gd-jp'>彼は事情を知っているにもかかわらず、説明しなかった。</span>（他明明了解狀況，卻沒有說明）</div><div class='gd-sec'>のに能用的範圍比較廣，下面這兩種くせに都不能用：<br>前後主角不同：<span class='gd-jp'>雨なのに、彼は出かけた。</span>（明明在下雨，他還是出門了）<br>講自己的遺憾，沒有在怪誰：<span class='gd-jp'>一生懸命勉強したのに、落ちた。</span>（我那麼認真讀書，還是落榜了）</div><div class='gd-warn'>判斷小訣竅：想<b>念某個人</b>用くせに；只是覺得<b>可惜、意外</b>用のに；<b>正式場合</b>寫にもかかわらず。</div>",
  "n2-14": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜一方で」就像中文的<b>「……的同時，另一方面……」</b>。把兩件事並排擺在一起給人看：一邊是A，另一邊是B。新聞、報告、文章特別愛用，口氣比較正式。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>對比兩面</span>同一件事有好有壞，或是兩個人、兩個地方的情況相反，就把它們擺在一起比。</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は大変な一方で、やりがいもある。</span>（這份工作很辛苦，但另一方面也很有成就感）</div><div class='gd-ex-line'>・<span class='gd-jp'>都市部の人口が増える一方で、地方の人口は減っている。</span>（都市人口增加的同時，地方人口卻在減少）</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はスポーツが得意な一方で、弟は本を読むのが好きだ。</span>（哥哥擅長運動，弟弟則喜歡看書）</div><div class='gd-sec'><span class='gd-tag'>同時做兩件事</span>一個人做A，同時也在做B。這時候沒有「相反」的意思，只是說他兩邊都有在顧。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社で働く一方で、週末は小説を書いている。</span>（他在公司上班，同時週末也在寫小說）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中先生は研究を続ける一方で、学生の指導にも力を入れている。</span>（田中老師持續做研究，同時也很用心指導學生）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放「普通形」，也就是不加ます、です的說法。動詞、い形容詞直接接；<b>な形容詞和名詞要特別注意</b>。<br>動詞：<span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増える一方で</span></span>，過去式也可以：<span class='gd-pair'><span class='gd-jp'>伸びた</span> → <span class='gd-jp'>伸びた一方で</span></span><br>い形容詞：<span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しい一方で</span></span><br>な形容詞：留著「な」：<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な一方で</span></span>（也可以說<span class='gd-jp'>便利である一方で</span>）<br>名詞：加「である」：<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生である一方で</span></span><br>「で」可以省略，只說「一方」，感覺更書面。</div><div class='gd-sec'>它也可以單獨放在句子開頭，當「另一方面」用：<span class='gd-jp'>その一方で</span>、<span class='gd-jp'>一方、</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>給料は上がった。その一方で、残業も増えた。</span>（薪水漲了。但另一方面，加班也變多了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞不能接だ：說成「便利だ一方で」是錯的，要說<span class='gd-jp'>便利な一方で</span>。名詞也一樣，不說「学生だ一方で」，要說<span class='gd-jp'>学生である一方で</span>。<br>・它很正式，跟朋友聊天說「仕事は大変な一方で…」會像在念新聞稿。平常講話用<span class='gd-jp'>けど</span>就好：<span class='gd-jp'>仕事は大変だけど、楽しいよ。</span>（工作很累，不過很好玩喔）<br>・<b>「一方」放在句子最後變成「一方だ」，意思就完全不一樣了</b>，看下面。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講人口：<br><b>一方で（在句子中間）</b>＝兩邊對照</div><div class='gd-ex-line'>・<span class='gd-jp'>都市の人口は増える一方で、地方は減っている。</span>（都市人口在增加，另一方面地方在減少）</div><div class='gd-sec'><b>一方だ（在句子最後）</b>＝只往一個方向一直變下去</div><div class='gd-ex-line'>・<span class='gd-jp'>都市の人口は増える一方だ。</span>（都市人口一直不斷增加）</div><div class='gd-sec'>一方だ前面只能放「會變化」的動詞，像<span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>悪くなる</span>，而且大多是往不好的方向變。</div><div class='gd-sec'><b>ばかりだ（變化）</b>跟一方だ意思幾乎一樣，但更偏向「越來越糟」，常帶著擔心、無奈。</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなるばかりだ。</span>（爸爸的病一直在惡化）</div><div class='gd-warn'>判斷小訣竅：「一方」後面還有話、在比兩件事，就是一方で；「一方」放在句尾、整句話到這裡結束，就是「一直～下去」的一方だ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>一方で只是把兩件事並排比較。如果想說「雖然A，結果卻B」，帶有「跟預期不一樣」的轉折感，可以接著學<span class='gd-jp'>〜ものの</span>、<span class='gd-jp'>〜にもかかわらず</span>。</div>",
  "n2-16": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜つつも」就是中文的<b>「明知～，卻還是～」「心裡想著～，結果還是～」</b>。像「明知熬夜傷身，還是滑手機到三點」這種<b>心裡知道、行動卻沒跟上</b>的感覺。它偏<b>書面語</b>，文章、新聞、正式場合比較常看到。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的ます形，把ます拿掉，加つつ（も）。<br><span class='gd-pair'><span class='gd-jp'>思う</span> → <span class='gd-jp'>思います</span> → <span class='gd-jp'>思いつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>知る</span> → <span class='gd-jp'>知ります</span> → <span class='gd-jp'>知りつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言います</span> → <span class='gd-jp'>言いつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span> → <span class='gd-jp'>しつつ</span></span><br>只能接<b>動詞</b>，形容詞、名詞不能直接接。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>雖然～卻～</span>前面是心裡的想法，後面是跟想法相反的行動。最常見的是「<span class='gd-jp'>〜と知りつつ</span>」「<span class='gd-jp'>〜と思いつつ</span>」「<span class='gd-jp'>〜と言いつつ</span>」。後面常接<span class='gd-jp'>てしまう</span>、<span class='gd-jp'>られない</span>，帶一點後悔或做不到的味道。</div><div class='gd-ex-line'>・<span class='gd-jp'>体に悪いと知りつつも、夜更かしがやめられない。</span>（明知對身體不好，卻戒不了熬夜）</div><div class='gd-ex-line'>・<span class='gd-jp'>早く返事をしなきゃと思いつつ、一週間たってしまった。</span>（一直想說要趕快回信，結果一個禮拜就過去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエット中だと言いつつ、ケーキを二つも食べた。</span>（嘴巴說在減肥，結果吃了兩塊蛋糕）</div><div class='gd-sec'><span class='gd-tag'>一邊～一邊～</span>沒有「も」的「つつ」，還有另一個意思：兩件事同時進行，是「ながら」的書面版。</div><div class='gd-ex-line'>・<span class='gd-jp'>景色を楽しみつつ、山道を歩いた。</span>（一邊欣賞風景，一邊走山路）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの意見を聞きつつ、計画を進めていきます。</span>（我們會一邊聽取大家的意見，一邊推動計畫）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接ます形，不是辭書形：<span class='gd-jp'>知りつつ</span>才對，不能說「知るつつ」。<br>・前後必須是<b>同一個人</b>。「媽媽反對，我還是去留學了」是兩個人，不能用つつ，要用<span class='gd-jp'>母は反対したが、私は留学した。</span><br>・加了「も」一定是「雖然～卻～」；只有「つつ」的時候，要看前後文判斷是「雖然」還是「一邊」。<br>・它偏書面，跟朋友聊天一般用「<span class='gd-jp'>〜けど</span>」「<span class='gd-jp'>〜のに</span>」就好。不過「<span class='gd-jp'>〜と思いつつ</span>」「<span class='gd-jp'>〜と知りつつ</span>」這種固定說法，口語也聽得到。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>つつも 和 ながらも</b>：意思幾乎一樣，同一句常可以互換。<br><span class='gd-jp'>悪いと知りつつも、やってしまった。</span><br><span class='gd-jp'>悪いと知りながらも、やってしまった。</span>（明知不對，還是做了）<br>差別在：つつも<b>只能接動詞</b>，語氣更像文章；ながらも還能接形容詞、名詞，例如<span class='gd-jp'>狭いながらも楽しい我が家</span>（雖然小，卻是溫馨的家），這裡就不能換成つつも。</div><div class='gd-sec'><b>つつも 和 つつある</b>：只差一個字，意思完全不同。つつある是「正在慢慢變成～」，沒有「雖然」的意思。<br><span class='gd-jp'>景気は回復しつつある。</span>（景氣正在慢慢回升）</div><div class='gd-warn'>判斷小訣竅：「明知～卻～」用つつも；前面是形容詞或名詞就換ながらも；看到つつある，想的是「正在慢慢變」。</div>",
  "n2-17": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這裡的「〜ながら（も）」就是中文的<b>「雖然～卻～」「明明～還～」</b>。前面先講一個情況，後面接一個「照理說不會這樣」的結果。<br>你在 N4 學過「<span class='gd-jp'>音楽を聞きながら勉強する</span>」（一邊聽音樂一邊讀書），那是<b>同時做兩件事</b>。這裡長得一模一樣，意思卻完全不同。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：用ます形，把ます拿掉再加ながら。最常見的是「〜ている」的樣子。<br><span class='gd-pair'><span class='gd-jp'>住んでいます</span> → <span class='gd-jp'>住んでいながら</span></span><span class='gd-pair'><span class='gd-jp'>知ります</span> → <span class='gd-jp'>知りながら</span></span><br><b>い形容詞</b>：直接接，い不用改。<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いながら</span></span><br><b>な形容詞</b>：把な拿掉再接。<span class='gd-pair'><span class='gd-jp'>残念な</span> → <span class='gd-jp'>残念ながら</span></span><br><b>名詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもながら</span></span><br>後面加「も」變成「ながらも」，意思一樣，「雖然」的感覺更強一點。</div><div class='gd-ex-line'>・<span class='gd-jp'>近くに住んでいながら、一度も行ったことがない。</span>（明明住在附近，卻一次也沒去過）</div><div class='gd-ex-line'>・<span class='gd-jp'>悪いと知りながら、うそをついてしまった。</span>（明知道不對，還是說了謊）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は学生ながら、自分で会社を経営している。</span>（他雖然還是學生，卻自己在經營公司）</div><div class='gd-ex-line'>・<span class='gd-jp'>狭いながらも、住み心地のいい部屋だ。</span>（雖然小，卻是住起來很舒服的房間）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>有幾個已經變成固定說法，日常、職場都很常聽到，整句背起來最快。</div><div class='gd-sec'><span class='gd-tag'>残念ながら</span>很遺憾，常用在宣布壞消息的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>残念ながら、明日の試合は中止になりました。</span>（很遺憾，明天的比賽取消了）</div><div class='gd-sec'><span class='gd-tag'>勝手ながら</span>店家公告常見，意思是「不好意思，我們擅自～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>勝手ながら、本日は休業させていただきます。</span>（很抱歉，本店今天暫停營業）</div><div class='gd-sec'><span class='gd-tag'>陰ながら</span>在背後默默地。</div><div class='gd-ex-line'>・<span class='gd-jp'>陰ながら応援しています。</span>（我會默默為你加油）</div><div class='gd-sec'><span class='gd-tag'>我ながら</span>連我自己都覺得。</div><div class='gd-ex-line'>・<span class='gd-jp'>我ながらよくできたと思う。</span>（連我自己都覺得做得不錯）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接法別亂加東西：是<span class='gd-jp'>狭いながら</span>，不是狭くながら；是<span class='gd-jp'>残念ながら</span>，不是残念なながら；是<span class='gd-jp'>子どもながら</span>，不是子どものながら。<br>・除了上面那些固定說法，這個句型<b>偏書面、正式</b>，像文章、新聞、面試會用。跟朋友聊天說「<span class='gd-jp'>狭いけど、いい部屋だよ</span>」比較自然。<br>・<span class='gd-jp'>昔ながらの</span>、<span class='gd-jp'>生まれながらの</span>不是「雖然」：<span class='gd-jp'>昔ながらの町並み</span>是「保留古早樣子的街道」，<span class='gd-jp'>生まれながらの才能</span>是「天生的才能」，要分開記。<br>・前後講的通常是<b>同一個人或同一件事</b>，例如「他雖然是學生，（他）卻開公司」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>同時的ながら</b>＝一邊～一邊～：<span class='gd-jp'>テレビを見ながらご飯を食べる。</span>（一邊看電視一邊吃飯）<br><b>逆接的ながら</b>＝明明～卻～：<span class='gd-jp'>毎日テレビを見ていながら、そのニュースを知らなかった。</span>（明明每天看電視，卻不知道那則新聞）</div><div class='gd-sec'><b>つつ（も）</b>：意思跟逆接的ながら（も）幾乎一樣，但更書面，而且<b>只能接動詞</b>。<br><span class='gd-jp'>悪いと知りつつも、うそをついてしまった。</span>（明知道不對，還是說了謊）<br>形容詞、名詞不能用：要說<span class='gd-jp'>狭いながらも</span>，不能說狭いつつも。</div><div class='gd-sec'><b>くせに</b>：也是「明明～」，但帶<b>責怪、不滿</b>，是口語的抱怨。<br><span class='gd-jp'>知っているくせに、教えてくれない。</span>（明明就知道，還不告訴我！）<br><span class='gd-jp'>知っていながら、教えてくれなかった。</span>（明明知道，卻沒告訴我：比較像冷靜陳述）</div><div class='gd-warn'>判斷小訣竅：前面是形容詞、名詞，或後面有「も」，就是「雖然」；前面是動詞時，看後半句是不是「跟預期相反」，是的話就是「雖然」，不是就是「一邊～一邊～」。想抱怨對方用くせに，寫文章用ながら或つつ。</div>",
  "n2-20": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に限らず」就是<b>「不只～」「不限於～」</b>。前面先放一個大家直覺會想到的東西，後面再告訴你：其實範圍更大，別的也一樣。<br>像中文說「不只週末，平日也很擠」，日文就是<span class='gd-jp'>週末に限らず、平日も混んでいる。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>名詞</b>，直接接「に限らず」就好。<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生に限らず</span></span>（不只學生）<br><span class='gd-pair'><span class='gd-jp'>日本</span> → <span class='gd-jp'>日本に限らず</span></span>（不只日本）<br>「限らず」念<b>かぎらず</b>，意思是「不限定在」。後半句常常會出現<span class='gd-jp'>も</span>、<span class='gd-jp'>誰でも</span>、<span class='gd-jp'>何でも</span>這類字，把範圍撐大。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>範圍比你想的大</span>大家以為只有A這樣，其實B、C也是。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は週末に限らず、平日もいつも混んでいる。</span>（這家店不只週末，平日也總是很多人）</div><div class='gd-ex-line'>・<span class='gd-jp'>この公園は子どもに限らず、大人にも人気がある。</span>（這座公園不只小孩，大人也很喜歡）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に限らず、アジア全体で少子化が進んでいる。</span>（不只日本，整個亞洲都在少子化）</div><div class='gd-sec'><span class='gd-tag'>不設限、誰都可以</span>公告、活動說明很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>学生に限らず、誰でも参加できます。</span>（不限學生，任何人都可以參加）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>跟「に限り」「に限って」相反</b>：<span class='gd-jp'>本日に限り半額</span>是「只有今天半價」，<span class='gd-jp'>本日に限らず</span>是「不只今天」。多一個「ず」，意思整個反過來，看公告時特別注意。<br>・前面基本上放名詞，動詞不能直接接：不能說「食べるに限らず」。要講動作，改用「〜ばかりでなく」比較自然。<br>・語氣偏正式、書面，新聞、公告、作文常見。跟朋友聊天說<span class='gd-jp'>〜だけじゃなくて</span>就好。<br>・前面放的應該是「大家本來就會想到的那個」，後面才是「其實也包括的」。順序放反，句子會怪。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>に限らず</b>＝前面是<b>一個具體的東西</b>，意思是「不只它」：<br><span class='gd-jp'>学生に限らず、社会人も参加できる。</span>（不只學生，社會人士也能參加）<br><b>を問わず</b>＝前面是<b>可以分成好幾種的類別</b>，意思是「不管是哪一種」：<br><span class='gd-jp'>このイベントは年齢を問わず、誰でも参加できる。</span>（這個活動不管幾歲，誰都能參加）<br>「年齢」可以分成很多種年紀，所以用を問わず；「学生」是一個具體的族群，所以用に限らず。</div><div class='gd-warn'>判斷小訣竅：前面能換成「不管是什麼○○」（年齢、性別、国籍、経験、天候）就用を問わず；前面是一個具體的人事物（学生、日本、週末），就用に限らず。</div><div class='gd-sec'><b>とは限らない</b>：也有「限」，但它放在句尾，意思是「<b>不一定</b>」：<span class='gd-jp'>高い物がいい物とは限らない。</span>（貴的東西不一定好）。這跟「不只～」完全是兩回事。</div><div class='gd-sec'>另外，<span class='gd-jp'>のみならず</span>、<span class='gd-jp'>ばかりでなく</span>也是「不只～，還～」，前面放名詞時常常可以跟に限らず互換。差別是に限らず只接名詞，而且重點放在「範圍不限這裡」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學<span class='gd-jp'>〜を問わず</span>（不管～），還有同樣表示「不只～」的<span class='gd-jp'>〜のみならず</span>、<span class='gd-jp'>〜ばかりか</span>，就能把「範圍」這一組一起搞定。</div>",
  "n2-21": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を問わず」就是中文的<b>「不問～」「不分～」</b>。<span class='gd-jp'>問う</span>是「問、追究」，<span class='gd-jp'>問わず</span>就是「不問」。徵才廣告寫「年齡不拘、經驗不限」，日文就是<span class='gd-jp'>年齢を問わず</span>、<span class='gd-jp'>経験を問わず</span>。意思是不管這個條件是哪一種，結果都一樣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>招募・公告</span>徵人、活動報名、店家公告最常看到，表示「這個條件不設限」。</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢を問わず、どなたでもご参加いただけます。</span>（不論年齡，任何人都可以參加）</div><div class='gd-ex-line'>・<span class='gd-jp'>このアルバイトは経験を問わず、誰でも応募できます。</span>（這份打工不限經驗，誰都可以應徵）</div><div class='gd-sec'><span class='gd-tag'>描述狀況</span>說某件事不受條件影響，到哪種情況都成立。</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は世代を問わず愛されている。</span>（這首歌不分世代都很受喜愛）</div><div class='gd-ex-line'>・<span class='gd-jp'>昼夜を問わず、工事の音がうるさい。</span>（不分白天晚上，施工的聲音都很吵）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接加<span class='gd-jp'>を問わず</span>。前面的名詞有兩種：<br><b>本身就有很多種的詞</b>：<span class='gd-jp'>年齢</span>、<span class='gd-jp'>性別</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>経験</span>、<span class='gd-jp'>天候</span><br><b>一組相反的詞</b>：<span class='gd-jp'>男女</span>、<span class='gd-jp'>昼夜</span>、<span class='gd-jp'>経験の有無</span>（有沒有經驗）<br>也可以接「〜かどうか」：<span class='gd-pair'><span class='gd-jp'>経験があるかどうか</span> → <span class='gd-jp'>経験があるかどうかを問わず</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>は問いません</span>放在句尾，徵才廣告超常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢は問いません。</span>（年齡不拘）</div><div class='gd-sec'><span class='gd-tag'>省略を</span>海報、徵人啟事為了簡短，常寫成<span class='gd-jp'>年齢問わず</span>、<span class='gd-jp'>経験問わず</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放「有不同種類」的詞。<span class='gd-jp'>学生を問わず</span>不通，因為「學生」只有一種，沒有東西可以「不分」。要說<span class='gd-jp'>学生かどうかを問わず</span>，或是<span class='gd-jp'>学生・社会人を問わず</span>。<br>・「問わず」念<b>とわず</b>，是<span class='gd-jp'>問う</span>的否定說法，不要寫成問えず。<br>・這是很正式的書面說法。跟朋友聊天說<span class='gd-jp'>関係なく</span>比較自然：<span class='gd-jp'>年とか関係なく、誰でも楽しめるよ。</span>（不管幾歲，誰都玩得開心喔）<br>・助詞固定用「を」，不要換成に或が。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>に限らず</b>＝<b>不只A，連B也～</b>（舉一個代表，再把範圍往外擴）：<br><span class='gd-jp'>このアプリは若者に限らず、お年寄りにも人気だ。</span>（這個 App 不只年輕人，連老人家也很喜歡）<br><b>を問わず</b>＝<b>不管A是哪一種都一樣</b>（條件根本不列入考慮）：<br><span class='gd-jp'>このアプリは年齢を問わず人気だ。</span>（這個 App 不分年齡都很受歡迎）</div><div class='gd-sec'>另外，<span class='gd-jp'>にかかわらず</span>的意思跟を問わず幾乎一樣：<span class='gd-jp'>天候にかかわらず実施します。</span>（不論天氣如何都照常舉行）<br>中間多一個「も」變成<b>にもかかわらず</b>，意思就完全不同，是「儘管～還是～」：<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（儘管下雨，還是來了很多人）</div><div class='gd-warn'>判斷小訣竅：「不只A，連B也」用に限らず；「不管A是什麼」用を問わず；「儘管A，還是」用にもかかわらず。</div>",
  "n2-22": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にわたって」就是中文新聞常講的<b>「長達～」「遍及～」「連續～」</b>。像「豪雨連下三天」「停電遍及全台」，重點在強調<b>時間很長、範圍很大</b>，而且是從頭到尾、整片都包含在裡面。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋にわたって。前面放的名詞要是<b>一段長度</b>或<b>一整片範圍</b>，最常見的有三種：</div><div class='gd-sec'><span class='gd-tag'>時間很長</span>3日間、10年、長年、長期間</div><div class='gd-ex-line'>・<span class='gd-jp'>会議は5時間にわたって続いた。</span>（會議開了長達五個小時）</div><div class='gd-sec'><span class='gd-tag'>範圍很廣</span>全国、広範囲、関東全域、多方面</div><div class='gd-ex-line'>・<span class='gd-jp'>台風の影響で、関東全域にわたって大雨が降った。</span>（受颱風影響，整個關東地區都下了大雨）</div><div class='gd-sec'><span class='gd-tag'>次數・份量</span>3回、数ページ</div><div class='gd-ex-line'>・<span class='gd-jp'>この特集は3回にわたって放送されます。</span>（這個專題分三集播出）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><b>にわたり</b>：意思一樣，更書面，新聞稿、公告很愛用。</div><div class='gd-ex-line'>・<span class='gd-jp'>調査は全国にわたり実施された。</span>（調查在全國各地進行）</div><div class='gd-sec'><b>にわたる＋名詞</b>：後面要接名詞時，改用這個形。</div><div class='gd-ex-line'>・<span class='gd-jp'>長年にわたる研究の成果が発表された。</span>（多年來的研究成果發表了）</div><div class='gd-sec'><b>にわたった＋名詞</b>：已經結束的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>2時間にわたった話し合いは、結論が出ないまま終わった。</span>（長達兩小時的討論，最後沒有結論就結束了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面不能放<b>時間點</b>或<b>單一地點</b>：不能說「3時にわたって」「月曜日にわたって」。它要的是「一段」或「一整片」，像<span class='gd-jp'>3時間</span>、<span class='gd-jp'>1週間</span>、<span class='gd-jp'>全国</span>。<br>・它帶有「好長、好廣」的口氣，小事用會很怪。<span class='gd-jp'>10分にわたってシャワーを浴びた</span>聽起來像在播新聞報導你洗澡。<br>・語氣偏正式，常出現在新聞、報告、公告裡。跟朋友聊天講<span class='gd-jp'>3日間ずっと雨だった</span>（連續下了三天雨）就自然多了。<br>・後面直接接名詞時要用<b>にわたる</b>：說<span class='gd-jp'>3時間にわたる会議</span>，不要說「3時間にわたって会議」。<br>・這個文法來自動詞<span class='gd-jp'>渡る</span>，偶爾會看到寫成「に渡って」，但多半寫平假名。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>最容易跟它搞混的是<b>〜にかけて</b>，兩個都在講範圍，但看的角度不同。<br><b>にかけて</b>：講<b>從哪裡到哪裡</b>，給的是起點和終點，範圍抓個大概。<br><div class='gd-ex-line'>・<span class='gd-jp'>3月から5月にかけて工事が行われる。</span>（三月到五月左右會施工）</div><b>にわたって</b>：講<b>總共多長、整片多大</b>，強調長、強調廣。<br><div class='gd-ex-line'>・<span class='gd-jp'>3か月にわたって工事が行われる。</span>（施工會長達三個月）</div>地點也一樣：<span class='gd-jp'>九州から関西にかけて雨が降る</span>（從九州到關西一帶會下雨）是在交代範圍；<span class='gd-jp'>西日本全域にわたって雨が降る</span>（整個西日本都會下雨）是在強調範圍很大。</div><div class='gd-warn'>判斷小訣竅：句子裡有「A から B」兩個端點，通常用にかけて；前面只有一個「總長度」或「一整片」，像<span class='gd-jp'>3か月</span>、<span class='gd-jp'>全国</span>，就用にわたって。</div>",
  "n2-23": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をもとに」就是中文的<b>「以～為基礎」「根據～（做出來）」</b>。前面放的是<b>材料、起點</b>，後面是你拿它<b>做出來的新東西</b>。像「改編自真實故事的電影」、「參考奶奶食譜做的咖哩」，就是這種感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一定是<b>名詞</b>，加上<span class='gd-jp'>をもとに</span>或<span class='gd-jp'>をもとにして</span>，意思一樣，有して的稍微完整一點。<br><span class='gd-pair'><span class='gd-jp'>データ</span> → <span class='gd-jp'>データをもとに</span></span>（根據數據）<br>後面要直接接名詞時，改成<b>をもとにした＋名詞</b>：<br><span class='gd-pair'><span class='gd-jp'>実話</span> → <span class='gd-jp'>実話をもとにした映画</span></span>（根據真實故事改編的電影）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>をもとに＋動作</span>後面常接「做、寫、想、決定、預測」這類會產出東西的動詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>アンケートの結果をもとに、新しいメニューを考えた。</span>（根據問卷結果，想了新菜單）</div><div class='gd-ex-line'>・<span class='gd-jp'>祖母のレシピをもとにして、カレーを作ってみた。</span>（以奶奶的食譜為基礎，試做了咖哩）</div><div class='gd-sec'><span class='gd-tag'>をもとに作られた</span>介紹作品來源時很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは人気漫画をもとに作られた。</span>（這部日劇是根據人氣漫畫拍的）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・寫成漢字是<span class='gd-jp'>基に</span>或<span class='gd-jp'>元に</span>，念<b>もとに</b>，不要念成「きに」。平常寫平假名也完全沒問題。<br>・前面只能放名詞。想放一句話，就先用「こと」把它變成名詞：<span class='gd-jp'>調べたことをもとに、レポートを書いた。</span>（根據查到的內容寫了報告）<br>・中文「根據氣象報告，明天會下雨」這種<b>轉述消息來源</b>的「根據」，日文不用をもとに，要用<span class='gd-jp'>によると</span>：<span class='gd-jp'>天気予報によると、明日は雨だそうだ。</span><br>・後面要有「做出／想出／決定」之類的動作或結果，單純「在那裡」「喜歡」這種句子接不上去。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>をもとに</b>＝拿來當<b>素材、起點</b>，之後可以加工、延伸、改編：<br><span class='gd-jp'>このデータをもとに、新しい企画を考えた。</span>（拿這份數據當起點，想出新企劃）<br><b>に基づいて</b>＝<b>照著</b>某個依據，不偏離它：<br><span class='gd-jp'>このデータに基づいて、結論を出した。</span>（依據這份數據下了結論）<br>講到依照法律、規則來判斷，一般用<span class='gd-jp'>法律に基づいて判断する</span>比較自然、正式。をもとに偏重「拿來當材料再做出東西」，用在法律、規則上語感比較弱，正式場合建議用に基づいて。</div><div class='gd-warn'>判斷小訣竅：結果是「以它為底，做出新東西」用をもとに；結果是「照它的規定、證據走」用に基づいて。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「名詞＋を＋〜に」的句型，還有表示「以～為契機」的<span class='gd-jp'>をきっかけに</span>：<span class='gd-jp'>留学をきっかけに、料理を始めた。</span>（因為留學，開始學做菜）。前面是「事情的開端」，不是「材料」，可以對照著記。</div>",
  "n2-24": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に応じて」就是<b>「看～來調整」「依～而定」</b>。像便當店老闆「看人數決定訂多少便當」：前面那個東西不一樣，後面的做法就<b>跟著配合、調整</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>直接接在名詞後面：<span class='gd-pair'><span class='gd-jp'>収入</span> → <span class='gd-jp'>収入に応じて</span></span>（依收入）<br>前面的名詞通常是<b>會因人、因情況而不同</b>的東西，像收入、年齡、能力、程度、預算、狀況、需求。<br>念法是<b>おうじて</b>。寫文章時也常看到省略「て」的<span class='gd-jp'>に応じ</span>，意思一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>収入に応じて、税金が決まる。</span>（稅金依收入而定）</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢に応じて、料金が変わります。</span>（費用依年齡而不同）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>必要に応じて</span>「視需要」，公司、公告超常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>必要に応じて、資料を追加してください。</span>（請視需要補充資料）</div><div class='gd-sec'><span class='gd-tag'>に応じた＋名詞</span>後面要接名詞時，最常用這個。</div><div class='gd-ex-line'>・<span class='gd-jp'>レベルに応じたクラスを選べます。</span>（可以選符合自己程度的班）</div><div class='gd-sec'>也有<span class='gd-jp'>に応じての</span>＋名詞的說法（如：<span class='gd-jp'>能力に応じての配置</span>），意思相同，但比較少見，初學先記<span class='gd-jp'>に応じた</span>即可。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面要是<b>跟著調整、變化</b>的事。單純說「根據消息得知」不能用它：<span class='gd-jp'>ニュースによると、明日は雨だ。</span>（根據新聞，明天會下雨）這裡要用によると。<br>・語氣偏正式，常出現在公告、說明、工作場合。朋友聊天比較常說<span class='gd-jp'>に合わせて</span>或<span class='gd-jp'>によって</span>。<br>・動詞<span class='gd-jp'>応じる</span>單獨用時常是「回應、答應」的意思：<span class='gd-jp'>インタビューに応じる</span>（接受採訪），不要跟「依～調整」混在一起。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講收入跟稅金：<br><b>に応じて</b>＝<b>配合</b>前面來調整：<span class='gd-jp'>収入に応じて、税金が決まる。</span>（稅金依收入來決定）<br><b>によって</b>＝<b>因</b>前面而<b>不同</b>，重點在「不一樣」：<span class='gd-jp'>収入によって、税金が違う。</span>（稅金因收入而有差別）<br><b>につれて</b>＝前面一直變，後面也<b>跟著慢慢變</b>：<span class='gd-jp'>収入が増えるにつれて、税金も増える。</span>（收入越多，稅金也跟著越多）</div><div class='gd-sec'>沒有人在「配合調整」的時候，用によって比較自然：<span class='gd-jp'>国によって、習慣が違う。</span>（各國習慣不同）這句換成に応じて就怪怪的。</div><div class='gd-warn'>判斷小訣竅：「配合它來調整」用に応じて，「因它而不同」用によって，「越～越～」用につれて。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣講「跟著變」的還有<span class='gd-jp'>〜に伴って</span>（隨著～）和<span class='gd-jp'>〜につれて</span>，可以放在一起比較。</div>",
  "n2-27": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜のみならず」就是<b>「不僅～，而且…」</b>的正式版。意思跟大家熟的「<span class='gd-jp'>だけでなく</span>」一樣，但它是<b>寫報告、新聞、演講</b>在用的，跟朋友聊天不會這樣講。<br>拆開來看就懂：<span class='gd-jp'>のみ</span>＝<span class='gd-jp'>だけ</span>（只有），<span class='gd-jp'>ならず</span>＝「不是」，合起來就是「不只是A」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>加碼</span>先講A，再補一個B，而且B通常是更大、更廣的範圍。後半句常常會有<b>も、でも、にも</b>，表示「B也是」。</div><div class='gd-ex-line'>・<span class='gd-jp'>国内のみならず、海外でも高い評価を得ている。</span>（不僅在國內，在海外也獲得很高的評價）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は学生のみならず、社会人にも人気がある。</span>（這家店不只受學生歡迎，上班族也很喜歡）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>日本</span> → <span class='gd-jp'>日本のみならず</span></span><br><b>動詞、い形容詞</b>：用普通形（就是字典上那個樣子，或た形、ない形）直接接。<br><span class='gd-pair'><span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるのみならず</span></span><span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いのみならず</span></span><br><b>な形容詞</b>：要加<b>である</b>，不能用「だ」。<span class='gd-pair'><span class='gd-jp'>静かだ</span> → <span class='gd-jp'>静かであるのみならず</span></span><br>名詞想強調「身分、性質」時也可以加である：<span class='gd-jp'>医者であるのみならず</span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は英語が話せるのみならず、中国語も読める。</span>（他不僅會說英文，也看得懂中文）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は狭いのみならず、駅からも遠い。</span>（這間房間不只小，離車站也很遠）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は静かであるのみならず、交通も便利だ。</span>（這個城鎮不但安靜，交通也很方便）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ただ〜のみならず</span>前面加「ただ」，變成「不單單是～」，語氣更重。</div><div class='gd-ex-line'>・<span class='gd-jp'>これはただ個人の問題のみならず、社会全体の問題でもある。</span>（這不單單是個人的問題，也是整個社會的問題）</div><div class='gd-sec'><span class='gd-tag'>放在句子開頭</span>單獨拿來當連接詞，意思是「不僅如此」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事が速い。のみならず、ミスもほとんどない。</span>（他做事很快。不僅如此，還幾乎不出錯）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞不能說<span class='gd-jp'>静かだのみならず</span>，要說<span class='gd-jp'>静かであるのみならず</span>。<br>・它很硬、很正式。跟朋友說「不只～」請用<span class='gd-jp'>だけじゃなく</span>，用のみならず會像在念公文。<br>・它是<b>往上加</b>，不是「不是A而是B」。前後要對得起來：A是地點，B也要是地點；A是問題，B也要是問題。後面記得補上「も」。<br>・前後方向要一致：好的接好的、壞的接壞的。不能拿來講相反的事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：這款遊戲大人小孩都愛玩。<br><b>だけでなく</b>＝最一般的說法，口語、書面都能用：<span class='gd-jp'>このゲームは子どもだけでなく、大人にも人気がある。</span><br><b>のみならず</b>＝意思一樣，換成正式、書面的口氣：<span class='gd-jp'>このゲームは子どものみならず、大人にも人気がある。</span><br><b>ばかりか</b>＝帶點「沒想到連～都」的驚訝感：<span class='gd-jp'>このゲームは子どもばかりか、大人まで夢中になっている。</span>（不只小孩，連大人都玩到入迷）<br><b>に限らず</b>＝重點是「不限於A這個範圍」，後半句常搭配<span class='gd-jp'>誰でも</span>、<span class='gd-jp'>どこでも</span>：<span class='gd-jp'>このゲームは子どもに限らず、誰でも楽しめる。</span>（這款遊戲不限小孩，誰都能玩得開心）</div><div class='gd-warn'>判斷小訣竅：聊天用だけじゃなく，寫文章用のみならず；想表達「連～都」的意外感用ばかりか；想說「不設限、誰都行」用に限らず。</div>",
  "n2-28": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AはもちろんBも」就是中文的<b>「A就不用說了，連B也～」</b>。A是大家都想得到、理所當然的那個，B是再補上去、比較沒想到的那個。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は味はもちろん、サービスもいい。</span>（這家店味道就不用說了，服務也很好）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本上是名詞直接加「はもちろん」，後面通常用<b>も</b>或<b>まで</b>來呼應：<br><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供はもちろん、大人も</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供はもちろん、大人も楽しめる映画です。</span>（小孩就不用說了，大人也能看得很開心的電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>家具はもちろん、家電までついている部屋だ。</span>（家具就不用說了，連家電都有附的房間）</div><div class='gd-sec'>名詞後面有「で」「に」這類小字的時候，就照樣留著，再加「はもちろん」：</div><div class='gd-ex-line'>・<span class='gd-jp'>日本ではもちろん、海外でも人気がある。</span>（在日本就不用說了，在海外也很受歡迎）</div><div class='gd-sec'>要放動作的話，先在動詞後面加「の」把它變成名詞：</div><div class='gd-ex-line'>・<span class='gd-jp'>話すのはもちろん、書くのも得意だ。</span>（說就不用說了，寫也很拿手）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>順序別放反</b>：前面放「本來就會這樣」的那個。主題樂園大家會先想到小孩，所以說<span class='gd-jp'>子供はもちろん、大人も</span>比較順。<br>・<b>句尾是否定的時候，前面要放「難的」那個</b>：<span class='gd-jp'>漢字はもちろん、ひらがなも書けない。</span>（漢字就不用說了，連平假名都不會寫）漢字寫不出來很正常，連簡單的平假名都不會，才是重點。<br>・後面記得加<b>も</b>或<b>まで</b>。<span class='gd-jp'>英語はもちろん、スペイン語が話せる</span>少了も，聽起來會卡卡的。<br>・跟單獨的「もちろん」（當然）不一樣：<span class='gd-jp'>もちろん行きます</span>是「我當然會去」，沒有「A不用說、連B也」的意思。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>三個都可以翻成「不只A，B也～」，拿同一句來比：<br><b>はもちろん</b>＝A本來就是理所當然的：<span class='gd-jp'>彼は英語はもちろん、中国語も話せる。</span>（英文就不用說了，他中文也會講）<br><b>ばかりか</b>＝重點在B讓人有點意外：<span class='gd-jp'>彼は英語ばかりか、中国語も話せる。</span>（他不只會英文，竟然連中文都會）<br><b>のみならず</b>＝意思跟ばかりか差不多，但是很正式，多半用在文章或演講：<span class='gd-jp'>彼は英語のみならず、中国語も話せる。</span></div><div class='gd-sec'>還有一個實用的差別：<b>はもちろん</b>後面可以接「請～」「我要～」這種拜託或決定，<b>ばかりか</b>就不太這樣用。</div><div class='gd-ex-line'>・<span class='gd-jp'>準備はもちろん、片付けも手伝ってください。</span>（準備就不用說了，收拾也請幫忙）</div><div class='gd-warn'>判斷小訣竅：想說「A不用說」就用はもちろん；想強調「連B都，好意外」就用ばかりか；寫正式文章才用のみならず。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜はもちろんのこと」意思一樣，語氣稍微再強調一點。寫文章時常看到更正式的<span class='gd-jp'>〜はもとより</span>：<span class='gd-jp'>国内はもとより、海外からも注文が来る。</span>（國內就不用說了，連海外都有訂單）</div>",
  "n2-30": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜だけのことはある」就是中文的<b>「不愧是～」「果然沒白～」「難怪～」</b>。你先看到一個很厲害的結果，再回頭說：嗯，這跟他的身分、花的錢、下的功夫完全對得上，<b>名不虛傳</b>。</div><div class='gd-sec'>這裡的<span class='gd-jp'>だけ</span>不是「只有」。整句的感覺是：「他是～，有那個身分就有那個實力，果然如此。」</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身分名不虛傳</span>專家、名店、名人的表現跟名氣一樣好。</div><div class='gd-ex-line'>・<span class='gd-jp'>さすがプロだけのことはある。</span>（不愧是專業的）</div><div class='gd-ex-line'>・<span class='gd-jp'>英語がペラペラだ。5年もアメリカに住んでいただけのことはある。</span>（英文超流利，不愧在美國住了五年）</div><div class='gd-sec'><span class='gd-tag'>錢花得值得</span>中文的「一分錢一分貨」。</div><div class='gd-ex-line'>・<span class='gd-jp'>このいす、全然疲れない。高かっただけのことはある。</span>（這張椅子坐再久都不累，貴果然有貴的道理）</div><div class='gd-sec'><span class='gd-tag'>難怪受歡迎</span>親身體驗後，覺得大家的評價沒錯。</div><div class='gd-ex-line'>・<span class='gd-jp'>このパン、本当においしい。行列ができるだけのことはあるね。</span>（這麵包真的好吃，難怪會大排長龍）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：普通形直接接　<span class='gd-pair'><span class='gd-jp'>練習した</span> → <span class='gd-jp'>練習しただけのことはある</span></span><br><b>い形容詞</b>：直接接　<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いだけのことはある</span></span><br><b>な形容詞</b>：要留著「な」　<span class='gd-pair'><span class='gd-jp'>有名</span> → <span class='gd-jp'>有名なだけのことはある</span></span><br><b>名詞</b>：直接接，不加だ　<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロだけのことはある</span></span><br>講得客氣一點就說<span class='gd-jp'>だけのことはありますね</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>前面常放<span class='gd-jp'>さすが</span>，兩個一起用，「不愧是」的味道更濃。順序很常是<b>先講看到的結果，再補一句だけのことはある</b>當結論。</div><div class='gd-ex-line'>・<span class='gd-jp'>景色が最高だ。さすが有名なだけのことはある。</span>（風景超棒，不愧這麼有名）</div><div class='gd-sec'>結果已經出來的事，也可以用過去式「あった」，常拿來說努力有回報。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できた。毎日勉強しただけのことはあった。</span>（考上了，每天念書果然沒白費）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・看到<span class='gd-jp'>だけ</span>就翻成「只有」，整句會完全看不懂。這裡是「不愧、名副其實」。<br>・名詞後面不要加だ：說<span class='gd-jp'>プロだけのことはある</span>，不是プロだだけのことはある。<br>・な形容詞要留「な」：說<span class='gd-jp'>有名なだけのことはある</span>，不是有名だけのことはある。<br>・一定要有<b>實際看到的結果</b>當證據。事情還沒發生、只是猜想，就不能用。<br>・初學先記：這是<b>稱讚、認同</b>的話。想抱怨東西很爛，先不要用它。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>だけあって</b>：意思一樣是「不愧是」，但它放在<b>句子中間</b>，後面直接接結果，一句講完。<br>・<span class='gd-jp'>さすがプロだけあって、写真がきれいだ。</span>（不愧是專業的，照片拍得很漂亮）<br><b>だけのことはある</b>：放在<b>句尾</b>，當作最後的結論。<br>・<span class='gd-jp'>写真がきれいだ。さすがプロだけのことはある。</span>（照片好漂亮，不愧是專業的）</div><div class='gd-sec'><b>ことだから</b>：同樣跟一個人的個性、實力有關，但它是<b>結果還沒出來時的推測</b>。接法是名詞＋の＋ことだから。<br>・<span class='gd-jp'>田中さんのことだから、きっと今回も合格するよ。</span>（田中那麼厲害，這次一定也會考過）<br>・<span class='gd-jp'>一回で合格した。さすが田中さんだけのことはある。</span>（一次就考過，不愧是田中）</div><div class='gd-warn'>判斷小訣竅：結果還沒出來、在猜，用ことだから。結果出來了、在讚嘆，用だけのことはある。想在同一句裡接著講結果，就改用だけあって。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是給正面評價的<span class='gd-jp'>〜に値する</span>（值得～），例如<span class='gd-jp'>この映画は見るに値する。</span>（這部電影值得一看）。</div>",
  "n2-31": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に値する」就是中文的<b>「值得～」</b>，而且是比較正式、書面的那種。新聞說「這項發現值得關注」、書評寫「這本書值得一讀」，日文就會用它。它的意思是：這個人或這件事<b>夠格、有那個價值</b>，配得上這樣的評價。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋に値する：<span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に値する</span></span>（值得尊敬）<br>動詞辭書形（字典上查到的原形）＋に値する：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに値する</span></span>（值得一讀）<br><span class='gd-jp'>値する</span>念<b>あたいする</b>，本身是一個動詞，變化跟<span class='gd-jp'>する</span>一樣：<span class='gd-jp'>値しない</span>、<span class='gd-jp'>値します</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>正面評價</span>前面最常放這幾個詞：<span class='gd-jp'>尊敬</span>、<span class='gd-jp'>称賛</span>、<span class='gd-jp'>信頼</span>、<span class='gd-jp'>注目</span>、<span class='gd-jp'>一読</span>、<span class='gd-jp'>検討</span>、<span class='gd-jp'>特筆</span>。先把這幾組當成固定搭配記起來就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の努力は称賛に値する。</span>（他的努力值得稱讚）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は一読に値する。</span>（這本書值得一讀）</div><div class='gd-ex-line'>・<span class='gd-jp'>このデータは注目に値する。</span>（這份數據值得關注）</div><div class='gd-sec'><span class='gd-tag'>否定：不值得</span>換成<span class='gd-jp'>値しない</span>，語氣很不客氣，等於「根本不值得理」。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな噂は信じるに値しない。</span>（那種傳聞不值得相信）</div><div class='gd-ex-line'>・<span class='gd-jp'>その意見は検討に値しない。</span>（那個意見不值得考慮）</div><div class='gd-sec'><span class='gd-tag'>放在名詞前面</span>直接拿來形容人或東西。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は信頼に値する人物だ。</span>（他是值得信賴的人）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・助詞固定用<b>に</b>：是<span class='gd-jp'>尊敬に値する</span>，不是尊敬を値する。<br>・念<b>あたいする</b>。<span class='gd-jp'>値段</span>的「値」念ね，別念混了。<br>・前面不能接ます形：不能說「読みますに値する」。要講禮貌，就把最後面改掉：<span class='gd-jp'>読むに値します</span>。<br>・它很硬、很書面。朋友聊天說「這碗拉麵值得吃」，用<span class='gd-jp'>このラーメン、食べる価値あるよ</span>就好；講成食べるに値する，會像在寫美食評論。<br>・中文「超值得」常常是在講划算，例如「打完折超值得」。這種意思日文用<span class='gd-jp'>お得</span>，不用に値する。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>価値がある</b>：意思跟に値する幾乎一樣，但日常、書面都能用，是最常講的說法。<br><span class='gd-jp'>この本は読む価値がある。</span>（這本書值得看：聊天也能講）<br><span class='gd-jp'>この本は一読に値する。</span>（這本書值得一讀：書評、正式場合）</div><div class='gd-sec'><b>だけのことはある</b>：同樣是在稱讚，但重點是「<b>不愧是～、難怪～</b>」，表示結果跟他的背景、付出對得上。同一個情境，聽完一場鋼琴演奏：<br><span class='gd-jp'>彼の演奏は称賛に値する。</span>（他的演奏值得讚賞：說這場演奏夠格得到稱讚）<br><span class='gd-jp'>さすが十年ウィーンで学んだだけのことはある。</span>（不愧是在維也納學了十年：說好的結果跟他的經歷對得上）</div><div class='gd-warn'>判斷小訣竅：想說「值得～」，正式場合用に値する，平常講話用価値がある；想說「不愧是～、難怪～」，用だけのことはある。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>N1 的「〜に足る」意思很接近，是「足以～、夠格～」：<span class='gd-jp'>信頼に足る人物</span>（足以信賴的人）。</div>",
  "n2-32": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜上は」就是中文的<b>「既然～，就（該）～」</b>。前面放一件已經確定的事，例如你的身份、你做的決定、事情發展到的地步；後面說「所以我就要／就該怎麼做」。跟中文「既然答應了，就要做到」的語氣很像，只是聽起來比較<b>正式、比較硬</b>，常帶點下定決心的感覺。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身份帶來的責任</span>既然是這個身份，就該做到應該做的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である上は、生徒の手本にならなければならない。</span>（既然身為老師，就必須當學生的榜樣）</div><div class='gd-sec'><span class='gd-tag'>做了就要負責</span>既然答應了、決定了，就要做到底。</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた上は、最後まで責任を持ちます。</span>（既然接下來了，我就會負責到底）</div><div class='gd-ex-line'>・<span class='gd-jp'>やると決めた上は、もう迷わない。</span>（既然決定要做，就不再猶豫了）</div><div class='gd-sec'><span class='gd-tag'>事到如今</span>事情已經變成這樣，只好面對。</div><div class='gd-ex-line'>・<span class='gd-jp'>こうなった上は、正直に話すしかない。</span>（事到如今，只能老實說了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：辭書形或た形，直接加上は。<br><span class='gd-pair'><span class='gd-jp'>試合に出る</span> → <span class='gd-jp'>試合に出る上は</span></span>（既然要上場比賽）<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した上は</span></span>（既然答應了）<br><b>名詞</b>：中間要加「である」。<br><span class='gd-pair'><span class='gd-jp'>社会人</span> → <span class='gd-jp'>社会人である上は</span></span>（既然是出了社會的人）</div><div class='gd-h'>後面要接什麼</div><div class='gd-sec'>後半句要是<b>你的決心、義務、建議或判斷</b>，最常看到這幾種結尾：<br><span class='gd-jp'>〜なければならない</span>（必須）、<span class='gd-jp'>〜べきだ</span>（應該）、<span class='gd-jp'>〜しかない</span>（只能）、<span class='gd-jp'>〜つもりだ</span>（打算）、<span class='gd-jp'>〜たい</span>（想要）。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に出る上は、絶対に勝ちたい。</span>（既然要上場比賽，就一定想贏）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念<b>うえは</b>，不是じょうは。<br>・名詞不能直接接：<span class='gd-jp'>学生である上は</span>才對，不能說「学生だ上は」。<br>・前面一定是<b>已經確定</b>的事，不是假設。不能加「もし」說「もし約束した上は」。<br>・後面不能只是陳述一個事實。像「日本に来た上は、毎日雨だった」就不行，因為「每天下雨」不是你的決心或判斷。<br>・語氣偏正式、書面，跟朋友聊天直接用很生硬，平常講話多半用<span class='gd-jp'>からには</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>からには</b>：意思幾乎一樣，都是「既然～就～」。<br>・<span class='gd-jp'>引き受けた上は、最後まで頑張ります。</span>（既然接下了，就會努力到最後）<br>・<span class='gd-jp'>引き受けたからには、最後まで頑張ります。</span>（同上）<br>差別在場合：<span class='gd-jp'>上は</span>比較硬，常見於文章、致詞、很鄭重的表態；<span class='gd-jp'>からには</span>正式場合也能用，日常對話更常聽到。</div><div class='gd-sec'><b>上に</b>：只差一個字，意思完全不同，是「不但～而且～」。<br>・<span class='gd-jp'>この店は安い上に、おいしい。</span>（這家店不但便宜，而且好吃）<br>・<span class='gd-jp'>店長である上は、遅刻はできない。</span>（既然是店長，就不能遲到）</div><div class='gd-warn'>判斷小訣竅：後面是「再加一個優點或缺點」用上に；後面是「所以就該、就要、只能」用上は。跟朋友講話時，「既然～」先想到からには。</div>",
  "n2-33": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜上に」就是中文的<b>「不但～，而且～」「～，再加上～」</b>。先講一個特點，再往上疊一個<b>同方向</b>的特點：好的再加好的，慘的再加慘的。</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から近い上に、家賃も安い。</span>（這間房子不但離車站近，房租也便宜）</div><div class='gd-ex-line'>・<span class='gd-jp'>道に迷った上に、雨にも降られた。</span>（不但迷路，還被雨淋）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接，現在、過去都可以。<br><span class='gd-pair'><span class='gd-jp'>寝坊した</span> → <span class='gd-jp'>寝坊した上に</span></span><br><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安い上に</span></span><br><b>な形容詞</b>：要把「だ」換成「な」。<br><span class='gd-pair'><span class='gd-jp'>親切だ</span> → <span class='gd-jp'>親切な上に</span></span><br><b>名詞</b>：加「である」或「の」，寫文章時「である」比較常見。<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者である上に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は親切な上に、仕事も早い。</span>（她人很親切，做事又快）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は寝坊した上に、財布まで忘れてしまった。</span>（今天睡過頭，連錢包都忘了帶）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者である上に、作家としても有名だ。</span>（他是醫生，而且作家身分也很有名）</div><div class='gd-sec'>你會發現後半句常常有<span class='gd-jp'>も</span>或<span class='gd-jp'>まで</span>，因為意思就是「這個<b>也</b>～」「連這個<b>都</b>～」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念<b>うえに</b>，不是じょうに。<br>・前後要同一個方向。<span class='gd-jp'>安い上に、まずい。</span>是錯的，便宜是優點、難吃是缺點，一好一壞要用<span class='gd-jp'>安いけど、まずい。</span>（便宜是便宜，但很難吃）<br>・な形容詞不能留著「だ」：說<span class='gd-jp'>便利な上に</span>，不說便利だ上に。<br>・「上に」這句是在描述、評價事情，後面不要直接接「請你～」「我們～吧」。想勸人，先把兩件事講完，再用<span class='gd-jp'>から</span>帶出來：<span class='gd-jp'>寒い上に風も強いから、今日は家にいよう。</span>（又冷風又大，今天待在家吧）<br>・<span class='gd-jp'>机の上に本がある。</span>的「上に」是「在桌子上面」，是講位置，跟這個文法無關，看前後文就分得出來。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>三個都有「上」，意思完全不同，用「工作」這個情境比比看：<br><b>上に</b>＝而且（兩個事實疊在一起）：<span class='gd-jp'>この仕事は給料が安い上に、残業も多い。</span>（這份工作薪水低，加班又多）<br><b>上で</b>＝先做完A，再做B：<span class='gd-jp'>条件をよく確認した上で、契約します。</span>（先把條件確認清楚，再簽約）<br><b>上は</b>＝既然～就一定要：<span class='gd-jp'>引き受けた上は、最後までやります。</span>（既然接下來了，就會做到最後）</div><div class='gd-warn'>判斷小訣竅：中文能說「而且」是上に，「～之後再」是上で，「既然～就」是上は。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>放在句子開頭的<span class='gd-jp'>その上</span>也是「而且」：<span class='gd-jp'>この店は安い。その上、おいしい。</span>（這家店便宜，而且好吃）<br>想表達更強烈的「不但～甚至～」，可以接著學<span class='gd-jp'>〜ばかりか</span>、<span class='gd-jp'>〜のみならず</span>。</div>",
  "n2-34": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜のことだから」就是中文的<b>「以他的個性啊，一定～」「他那個人喔，應該會～」</b>。你很了解某個人平常的樣子，就拿這份了解當根據，去猜他這次會怎麼做。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>根據個性猜</span>前面講一個你熟悉的人，最好順便講出他的個性；後面講你的推測。</div><div class='gd-ex-line'>・<span class='gd-jp'>時間に厳しい部長のことだから、もう会議室にいるはずだ。</span>（部長對時間那麼嚴格，現在應該已經在會議室了）</div><div class='gd-ex-line'>・<span class='gd-jp'>優しい彼女のことだから、きっと手伝ってくれるよ。</span>（她人那麼好，一定會幫你的啦）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟のことだから、どうせまだ寝ているよ。</span>（我弟那個人喔，反正一定還在睡啦）</div><div class='gd-sec'><span class='gd-tag'>也能講公司、店家</span>只要它平常的作風大家都知道，也可以用。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの会社のことだから、また値上げするだろう。</span>（那家公司的作風，八成又要漲價了吧）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞後面加「の」，再加「ことだから」：<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼のことだから</span></span><br><span class='gd-pair'><span class='gd-jp'>あの会社</span> → <span class='gd-jp'>あの会社のことだから</span></span><br>前面常常再加一個形容個性的詞，讓根據更清楚：<br><span class='gd-pair'><span class='gd-jp'>真面目な彼</span> → <span class='gd-jp'>真面目な彼のことだから</span></span></div><div class='gd-sec'>後半通常是你的猜測，所以很常跟<span class='gd-jp'>だろう</span>、<span class='gd-jp'>きっと</span>、<span class='gd-jp'>はずだ</span>、<span class='gd-jp'>に違いない</span>一起出現。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「の」不能漏：是<span class='gd-jp'>彼のことだから</span>，不是彼ことだから。<br>・前面的人，必須是你很清楚他平常是什麼樣子的人，而且通常聽的人也知道他的個性。第一次見面的人不能用，因為你根本不了解他。<br>・後半是「我猜」「我判斷」，不是在講已經發生的事實。講完全確定的事，就不用這個句型。<br>・中文翻成「因為是他」容易讓人以為只是普通的理由，其實重點在<b>「以我對他的了解」</b>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境，猜朋友會不會準時：<br><b>名詞＋だから</b>＝因為他是某種身分、某種人（理由是事實或類別）：<span class='gd-jp'>彼は日本人だから、時間を守るだろう。</span>（他是日本人，應該會守時吧）<br><b>名詞＋のことだから</b>＝以我對<b>這個人</b>的了解：<span class='gd-jp'>彼のことだから、時間を守るだろう。</span>（以他的個性，應該會守時吧）<br>第一句是拿「日本人」這個身分當理由，第二句是因為你認識他，知道他一向很準時。</div><div class='gd-warn'>判斷小訣竅：理由是「他是～（身分、事實）」就用だから；理由是「我知道他就是這種人」就用のことだから。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後半常用來表達很有把握的推測，可以接著學<span class='gd-jp'>〜に違いない</span>（一定是～）和<span class='gd-jp'>〜に決まっている</span>（肯定是～）：<span class='gd-jp'>あの人のことだから、また忘れたに決まっている。</span>（他那個人喔，肯定又忘了）</div>",
  "n2-36": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ずにはいられない」就是中文的<b>「忍不住～」「不禁～」</b>。心裡冒出一股感覺或衝動，想壓也壓不住，結果就做了。字面意思是「不做～的話，就待不住」，換個說法就是「忍不住做了」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>感情湧上來</span>聽到、看到某個東西，心裡自然冒出某種感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌を聞くと、昔を思い出さずにはいられない。</span>（每次聽到這首歌，就不禁想起從前）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の努力には、感心せずにはいられない。</span>（看到他那麼努力，真的讓人不由得佩服）</div><div class='gd-sec'><span class='gd-tag'>忍不住開口、動手</span>明明可以不做，就是管不住自己。</div><div class='gd-ex-line'>・<span class='gd-jp'>困っている人を見ると、声をかけずにはいられない。</span>（看到有人遇到困難，我就忍不住上前問一聲）</div><div class='gd-ex-line'>・<span class='gd-jp'>あまりにひどい話で、一言言わずにはいられなかった。</span>（實在太過分了，我忍不住說了一句）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'>先把動詞變成「ない」的樣子，再看要接哪一個版本：<br>・<b>ず版</b>：把「ない」拿掉，接<span class='gd-jp'>ずにはいられない</span><br>・<b>ないで版</b>：「ない」留著，接<span class='gd-jp'>ではいられない</span><br>兩個意思一樣。ず版比較常見，也比較書面；ないで版稍微口語一點。</div><div class='gd-sec'><b>第一類（五段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span></span> → 把ない拿掉 → <span class='gd-pair'><span class='gd-jp'>泣か</span> → <span class='gd-jp'>泣かずにはいられない</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わずにはいられない</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べずにはいられない</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないではいられない</span></span></div><div class='gd-sec'><b>第三類（要特別記）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはいられない</span></span><span class='gd-pair'><span class='gd-jp'>心配する</span> → <span class='gd-jp'>心配せずにはいられない</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはいられない</span>（こずには）</span><br>ないで版就照一般的ない形：<span class='gd-jp'>心配しないではいられない</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・する的ず版是<b>せず</b>，不是しず：<span class='gd-jp'>心配せずには</span>才對。但ないで版是<span class='gd-jp'>心配しないでは</span>，兩個不要混在一起。<br>・<span class='gd-jp'>来ずには</span>要念<b>こずには</b>，不是きずには。<br>・<span class='gd-jp'>言う</span>的ない形是<span class='gd-jp'>言わない</span>，所以是<span class='gd-jp'>言わずには</span>，不是言あずには。<br>・看到一堆否定，中文直覺容易翻成「不能不～」，聽起來很像被逼。其實它講的是<b>自己忍不住</b>，記成「忍不住就做了」最準。<br>・主詞通常是<b>我自己</b>。講別人要加<span class='gd-jp'>ようだ</span>或<span class='gd-jp'>らしい</span>：<span class='gd-jp'>彼は文句を言わずにはいられないようだ。</span>（他好像不抱怨一下就受不了）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ざるを得ない</b>＝不想做，但<b>被情況逼著</b>只好做：<br><span class='gd-jp'>部長の冗談は全然おもしろくないけど、笑わざるを得なかった。</span>（部長的笑話一點都不好笑，但我不得不笑）<br><b>ずにはいられない</b>＝心裡冒出來，<b>自己忍不住</b>：<br><span class='gd-jp'>友だちの冗談がおもしろすぎて、笑わずにはいられなかった。</span>（朋友的笑話太好笑，我忍不住笑出來）</div><div class='gd-sec'><b>てたまらない</b>＝講<b>心裡的感覺</b>很強烈，人可能還在忍：<br><span class='gd-jp'>ケーキが食べたくてたまらない。</span>（想吃蛋糕想得不得了）<br><b>ずにはいられない</b>＝講<b>停不下來的行動</b>，通常已經做了：<br><span class='gd-jp'>ケーキを見ると、食べずにはいられない。</span>（一看到蛋糕，就忍不住吃下去）</div><div class='gd-warn'>判斷小訣竅：「忍不住就做了」是ずにはいられない，「雖然不想但只好做」是ざるを得ない，「感覺～得不得了」是てたまらない。</div>",
  "n2-38": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜かねない」就是<b>「這樣下去，搞不好會～」</b>，後面接的一定是<b>壞事</b>。就像台灣人常說「你再這樣熬夜，遲早會出事」，帶一點提醒、警告的口氣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>提醒會有壞結果</span>前面常先講一個原因或條件（<span class='gd-jp'>〜と</span>、<span class='gd-jp'>〜ば</span>、<span class='gd-jp'>このままでは</span>），後面用かねない說出可能發生的壞事。</div><div class='gd-ex-line'>・<span class='gd-jp'>無理を続けると、体を壊しかねない。</span>（一直硬撐下去，搞不好會把身體搞壞）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな言い方をしたら、誤解されかねないよ。</span>（你那樣講，搞不好會被誤會喔）</div><div class='gd-sec'><span class='gd-tag'>那個人做得出來</span>說某個人「那種事他真的幹得出來」，帶有負面評價。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人なら、約束を忘れかねない。</span>（那個人的話，搞不好真的會把約定忘掉）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，把「ます」拿掉，再加「かねない」。<br><span class='gd-pair'><span class='gd-jp'>壊す</span> → <span class='gd-jp'>壊します</span> → <span class='gd-jp'>壊しかねない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れます</span> → <span class='gd-jp'>忘れかねない</span></span><br><span class='gd-pair'><span class='gd-jp'>誤解する</span> → <span class='gd-jp'>誤解します</span> → <span class='gd-jp'>誤解しかねない</span></span><br>要講得客氣一點，就說<b>かねません</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>このままでは、計画が中止になりかねません。</span>（這樣下去，計畫搞不好會被取消）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它結尾雖然有「ない」，意思卻<b>不是「不會」</b>，而是「<b>有可能會</b>」。看到ない不要直覺翻成「不」。<br>・只能用在壞事。好事要用かもしれない：×<span class='gd-jp'>合格しかねない</span> → ○<span class='gd-jp'>合格するかもしれない</span>（搞不好會考上）。<br>・前面只能接「ます形把ます拿掉」的樣子，不能接辭書形或ない形：×<span class='gd-jp'>壊すかねない</span>、×<span class='gd-jp'>壊さないかねない</span>。<br>・語氣偏正式，新聞、公司報告、醫生提醒很常用。跟朋友聊天比較常說<span class='gd-jp'>〜かもしれない</span>或<span class='gd-jp'>〜ちゃうかも</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>かねる</b>＝「（礙於立場）沒辦法～、不方便～」，常是店員、客服客氣地拒絕。<br><b>かねない</b>＝「搞不好會～（壞事）」。<br>同樣是被問了一個敏感問題：</div><div class='gd-ex-line'>・<span class='gd-jp'>その質問にはお答えしかねます。</span>（這個問題恕我無法回答）</div><div class='gd-ex-line'>・<span class='gd-jp'>その質問に答えたら、誤解されかねない。</span>（回答那個問題的話，搞不好會被誤會）</div><div class='gd-sec'><b>かもしれない</b>＝單純「可能」，好事壞事都能用，口氣中性。<b>かねない</b>只用在壞事，還多了「要小心」的警告感。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は晴れるかもしれない。</span>（明天搞不好會放晴）</div><div class='gd-ex-line'>・<span class='gd-jp'>このまま遊んでいたら、試験に落ちかねない。</span>（再這樣玩下去，考試搞不好會落榜）</div><div class='gd-warn'>判斷小訣竅：「沒辦法～、恕難～」是かねる（沒有ない反而是做不到）；「再這樣搞不好會出事」是かねない；不分好壞的「可能」就用かもしれない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><b>〜得る</b>也是「有可能」，但不分好壞，口氣比較客觀：<span class='gd-jp'>これは誰にでも起こり得ることだ。</span>（這是誰都有可能遇到的事）</div>",
  "n2-39": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜得る」就是<b>「有可能～」</b>，「〜得ない」就是<b>「不可能～」</b>。語氣像中文新聞、報告裡的「有發生的可能」「不可能」，比較正式。你最常聽到的應該是日劇裡那句<span class='gd-jp'>ありえない！</span>，意思是「怎麼可能！」「太扯了吧！」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，再把ます拿掉，接上「得る」。<br><span class='gd-pair'><span class='gd-jp'>起こります</span> → ます拿掉 → <span class='gd-jp'>起こり得る</span></span>（有可能發生）<br><span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>あり得る</span></span>（有可能有）<br><span class='gd-pair'><span class='gd-jp'>考えます</span> → <span class='gd-jp'>考え得る</span></span>（想得到的）<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>し得る</span></span>（有可能做）</div><div class='gd-h'>怎麼念：只有一個地方可以選</div><div class='gd-sec'><b>只有「得る」這個原本的樣子</b>（放句尾或接名詞的時候），念<b>うる</b>或<b>える</b>都可以。<span class='gd-jp'>あり得る</span>念ありうる、ありえる都對，新聞、文章裡比較常聽到ありうる。<br><b>其他變化一律念「え」</b>：<span class='gd-jp'>得ない</span>（えない）、<span class='gd-jp'>得ます</span>（えます）、<span class='gd-jp'>得た</span>（えた）。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>有可能</span>客觀地說某件事有發生的可能，好事壞事都能用。</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にでも起こり得る問題だ。</span>（這是任何人都可能遇到的問題）</div><div class='gd-ex-line'>・<span class='gd-jp'>それは十分あり得る話だ。</span>（那是很有可能的事）</div><div class='gd-sec'><span class='gd-tag'>不可能</span>斷定某件事不會發生。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことは現実的にあり得ない。</span>（那種事在現實中不可能發生）</div><div class='gd-sec'><span class='gd-tag'>想得到的・能做到的</span>常跟「限り」「すべて」一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>考え得る方法は全部試した。</span>（想得到的方法全都試過了）</div><div class='gd-sec'><span class='gd-tag'>口語</span><span class='gd-jp'>ありえない</span>是例外，朋友聊天也很常講，用來表示傻眼、不敢相信。</div><div class='gd-ex-line'>・<span class='gd-jp'>え、また遅刻？ありえない！</span>（蛤，又遲到？太扯了吧！）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它講的是<b>事情有沒有可能發生</b>，不是講一個人會不會某種技能。「我會游泳」要說<span class='gd-jp'>泳げる</span>，不能說泳ぎ得る。<br>・否定只能念えない：是<span class='gd-jp'>ありえない</span>，沒有「ありうない」這種念法。<br>・除了<span class='gd-jp'>ありえない</span>、<span class='gd-jp'>ありえる</span>，其他像<span class='gd-jp'>起こり得る</span>都偏書面。平常聊天說<span class='gd-jp'>起こるかもしれない</span>比較自然。<br>・<span class='gd-jp'>ざるを得ない</span>裡面也有「得ない」，但意思完全不同：<span class='gd-jp'>行かざるを得ない</span>是「不得不去」，不是「不可能去」。<br>・「得る」單獨當動詞時念える，意思是「得到」，例如<span class='gd-jp'>賞を得る</span>（得獎），跟這裡的用法是兩回事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>得る vs かねない</b>：兩個都是「有可能」，但かねない只用在<b>擔心會發生壞事</b>。<br><span class='gd-jp'>このままでは事故が起こり得る。</span>（照這樣下去，有可能發生事故：冷靜陳述）<br><span class='gd-jp'>このままでは事故が起こりかねない。</span>（照這樣下去，搞不好會出事：帶著擔心）<br>好事只能用得る：<span class='gd-jp'>努力すれば誰でも成功し得る。</span>（只要努力，誰都有可能成功）這句換成かねない就不對。</div><div class='gd-sec'><b>得ない vs っこない</b>：兩個都是「不可能」，但っこない是<b>很口語、很主觀</b>的「哪有可能啦」。<br><span class='gd-jp'>一日で終わることはあり得ない。</span>（一天之內不可能完成：正式、客觀）<br><span class='gd-jp'>一日で終わりっこないよ。</span>（一天哪可能做完啦：跟朋友抱怨）</div><div class='gd-warn'>判斷小訣竅：客觀說「有可能／不可能」用得る・得ない；擔心壞事發生用かねない；跟朋友說「哪可能啦」用っこない。</div>",
  "n2-40": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜っこない」就是中文的<b>「哪可能～啦」「怎麼可能～」</b>。講話的人心裡已經認定「這件事絕對不會發生」，語氣很衝、很口語，常帶一點「算了吧」「別傻了」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと、できっこないよ。</span>（那種事，怎麼可能做得到啦）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，<b>把ます拿掉</b>，再加「っこない」。<br><span class='gd-pair'><span class='gd-jp'>できます</span> → <span class='gd-jp'>できっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合います</span> → <span class='gd-jp'>間に合いっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>分かります</span> → <span class='gd-jp'>分かりっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>勝てます</span> → <span class='gd-jp'>勝てっこない</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>做不到</span>最常搭「できる」「分かる」「間に合う」，或是「勝てる」「受かる」「取れる」這種表示「能不能做到」的動詞，意思是「根本辦不到」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな強いチームに勝てっこない。</span>（那麼強的隊伍，怎麼可能贏）</div><div class='gd-ex-line'>・<span class='gd-jp'>今から走っても間に合いっこないよ。</span>（現在用跑的也不可能趕上啦）</div><div class='gd-ex-line'>・<span class='gd-jp'>説明したって、あの人には分かりっこない。</span>（就算解釋了，他也不可能懂）</div><div class='gd-sec'><span class='gd-tag'>別人不會那樣做</span>講別人的行為時，意思是「他才不可能那樣做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの頑固な父が謝りっこない。</span>（我那個頑固的爸爸，怎麼可能道歉）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接<b>把ます拿掉之後的樣子</b>，不是辭書形：說<span class='gd-jp'>分かりっこない</span>，不能說「分かるっこない」。<br>・「っこない」本身就已經是否定，前面不要再放ない。<br>・它只接動詞，不能直接接形容詞或名詞。<br>・「っこ」有促音，要停一拍念成「っこ」，不要念成「こない」，不然聽起來像「来ない」。<br>・這是朋友之間的說法，口氣很強。對上司、客人講，或寫在報告裡都不適合。<br>・對著人說「<span class='gd-jp'>君にはできっこない</span>」（你不可能做到）等於當面看扁對方，很傷人，小心使用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事「這麼多工作，一天哪做得完」，三種說法：<br><span class='gd-jp'>一日で終わりっこない。</span>（<b>っこない</b>：口語、帶情緒，像在抱怨）<br><span class='gd-jp'>一日で終わるわけがない。</span>（<b>わけがない</b>：「怎麼可能」，口語、書面都能用）<br><span class='gd-jp'>一日で終わるはずがない。</span>（<b>はずがない</b>：照道理推斷「不可能」，比較冷靜）<br>另外要注意接法不一樣：わけがない、はずがない接的是辭書形（<span class='gd-jp'>終わる</span>），っこない接的是把ます拿掉的樣子（<span class='gd-jp'>終わり</span>）。</div><div class='gd-warn'>判斷小訣竅：跟朋友碎念、發牢騷用「っこない」；要講得正式一點，就換成「わけがない」或「はずがない」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>意思剛好反過來的是「〜に決まっている」＝「一定會～，錯不了」：<span class='gd-jp'>そんなの、失敗するに決まっている。</span>（那種做法，一定會失敗的啦）</div>",
  "n2-42": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に決まっている」就是中文的<b>「一定是～啦，想也知道」</b>。講話的人心裡已經認定了，口氣很篤定，帶點「這還用說嗎」的感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接，過去式、否定也可以。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くに決まっている</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いに決まっている</span></span><span class='gd-pair'><span class='gd-jp'>忘れた</span> → <span class='gd-jp'>忘れたに決まっている</span></span></div><div class='gd-sec'><b>名詞、な形容詞</b>：<b>不要加だ</b>，直接接に。<br><span class='gd-pair'><span class='gd-jp'>嘘</span> → <span class='gd-jp'>嘘に決まっている</span></span><span class='gd-pair'><span class='gd-jp'>無理</span> → <span class='gd-jp'>無理に決まっている</span></span></div><div class='gd-sec'>聊天時常縮成<span class='gd-jp'>〜に決まってる</span>；禮貌一點是<span class='gd-jp'>〜に決まっています</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>想也知道</span>不用證據，心裡就認定一定是這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな時間に電話なんて、急用に決まってる。</span>（這種時間打電話來，一定是有急事）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなに安いのは偽物に決まってるよ。</span>（那麼便宜，一定是假貨啦）</div><div class='gd-sec'><span class='gd-tag'>那還用說</span>對方問了很明顯的事，你回「當然啊」。</div><div class='gd-ex-line'>・<span class='gd-jp'>「一緒に行く？」「行くに決まってるじゃん！」</span>（「要一起去嗎？」「當然要去啊！」）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時間も歩いたんだから、疲れたに決まってるでしょ。</span>（走了 10 個小時，當然累啊）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面不要加だ：說<span class='gd-jp'>嘘だに決まっている</span>是錯的，要說<span class='gd-jp'>嘘に決まっている</span>。<br>・這是<b>講話者的主觀認定</b>，口氣很強。對主管、客人說「〜に決まっています」容易聽起來很武斷，甚至像在嗆人；正式文章、報告也不太用。<br>・中文的「一定」也可以表示「一定要做」，但に決まっている<b>沒有這個意思</b>。想說「明天一定要來」要說<span class='gd-jp'>明日は必ず来てください</span>。<br>・<span class='gd-jp'>決まっている</span>本來是「已經決定好」。所以有時候它就是字面意思：<span class='gd-jp'>会議は月曜日に決まっている。</span>（會議已經定在星期一）要看前後文判斷。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：朋友到現在還沒來。<br><b>に違いない</b>＝有根據的推測，口氣比較冷靜，說話、寫文章都能用：<br><span class='gd-jp'>道が混んでいるに違いない。</span>（一定是塞車了）<br><b>に決まっている</b>＝更主觀、情緒更強，幾乎只在聊天時講：<br><span class='gd-jp'>道が混んでいるに決まってるよ。</span>（一定是塞車啦，想也知道）<br><b>に相違ない</b>＝意思跟に違いない一樣，但很硬，多出現在文章、小說：<br><span class='gd-jp'>道が混んでいるに相違ない。</span>（必定是交通壅塞）<br>反方向的是<b>っこない</b>＝「不可能～啦」，一樣口語、主觀：<br><span class='gd-jp'>あの人が時間通りに来っこないよ。</span>（他不可能準時來啦）</div><div class='gd-warn'>判斷小訣竅：冷靜推理用に違いない，寫文章用に相違ない，帶「想也知道」「那還用說」口氣的用に決まっている。想說「不可能」就用っこない。</div>",
  "n2-44": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ものだ」就是中文的<b>「真是～啊」「想當年啊……」</b>。它不是在報告事實，而是帶著<b>人生感慨</b>在講話，很像長輩看著照片說「時間過得真快啊」的那種口氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞普通形：<span class='gd-pair'><span class='gd-jp'>変わる</span> → <span class='gd-jp'>変わるものだ</span></span><br>い形容詞：<span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早いものだ</span></span><br>な形容詞要留著「な」：<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなものだ</span></span><br>講以前的事就用た形：<span class='gd-pair'><span class='gd-jp'>遊んだ</span> → <span class='gd-jp'>遊んだものだ</span></span><br>口語常縮成<b>もんだ</b>，句尾也常加<b>なあ</b>：<span class='gd-jp'>早いもんだなあ。</span>禮貌一點就說<span class='gd-jp'>ものです</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>人生感慨</span>對時間、人生、變化發出感嘆。</div><div class='gd-ex-line'>・<span class='gd-jp'>月日がたつのは早いものだ。</span>（時間過得真快啊）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町もずいぶん変わったものだ。</span>（這個小鎮也變了好多啊）</div><div class='gd-sec'><span class='gd-tag'>懷念以前</span>た形＋ものだ，常跟「よく」一起出現，講<b>以前常常做</b>的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃はよくこの川で遊んだものだ。</span>（小時候常在這條河玩呢）</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は朝まで友達と話したものだ。</span>（學生時代常跟朋友聊到天亮）</div><div class='gd-sec'><span class='gd-tag'>佩服或傻眼</span>「よく～たものだ」＝竟然能～。</div><div class='gd-ex-line'>・<span class='gd-jp'>よくそんなことが言えたものだ。</span>（虧你說得出那種話）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・懷念用法只能講<b>以前反覆做過</b>的事。只發生一次的事不能用：<span class='gd-jp'>去年京都へ行ったものだ</span>是錯的，直接說<span class='gd-jp'>去年京都へ行った</span>就好。<br>・「よく」有兩個意思：<span class='gd-jp'>よく遊んだものだ</span>的よく是「常常」；<span class='gd-jp'>よく言えたものだ</span>的よく是「竟然」。看前後文判斷。<br>・眼前的小事，像天氣很熱、東西好吃，用<span class='gd-jp'>暑いなあ</span>、<span class='gd-jp'>おいしいね</span>就好。硬加ものだ會像在發表人生心得。<br>・な形容詞不能接「だ」再接ものだ，<span class='gd-jp'>静かだものだ</span>是錯的。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ものだ（本來就～／應該～）</b>：講一般常理或規矩，沒什麼情緒。<br><span class='gd-jp'>年をとると、物忘れが多くなるものだ。</span>（人老了本來就容易忘東忘西）<br><span class='gd-jp'>人の話は最後まで聞くものだ。</span>（別人說話應該聽到最後）<br><b>ものだ（感嘆）</b>：同樣的形，但是帶著感慨。<br><span class='gd-jp'>子供が大きくなるのは本当に早いものだ。</span>（小孩長大真的好快啊）<br><b>ものがある</b>：某個東西讓你<b>感覺到一種特質</b>，用來評價作品、人、表現。<br><span class='gd-jp'>彼の歌には人の心を打つものがある。</span>（他的歌有種打動人心的力量）</div><div class='gd-warn'>判斷小訣竅：句子裡加得進「本当に」「なあ」而且讀起來有感觸，就是感嘆；冷靜講道理、講規矩，是「本來就～」；在說「某東西有種～的感覺」，是ものがある。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看<span class='gd-jp'>〜ものがある</span>，再回頭複習「本來就～」的<span class='gd-jp'>ものだ</span>。三個放在一起比，最不容易搞混。</div>",
  "n2-45": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ぶり」有兩種<b>完全不同</b>的用法：<br>①接在動作後面＝<b>「～的樣子、～的方式」</b>，很像中文說「吃相」「工作態度」。<br>②接在一段時間後面＝<b>「睽違～、隔了～又～」</b>，就是你早就會的<span class='gd-jp'>久しぶり</span>的那個ぶり。</div><div class='gd-h'>用法①：～的樣子</div><div class='gd-sec'><span class='gd-tag'>怎麼接</span>名詞直接加ぶり：<span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事ぶり</span></span>（工作表現）<br>動詞先變ます形，把ます拿掉，再加ぶり：<span class='gd-pair'><span class='gd-jp'>話します</span> → ます拿掉 → <span class='gd-jp'>話しぶり</span></span>（說話的樣子）<span class='gd-pair'><span class='gd-jp'>暮らします</span> → <span class='gd-jp'>暮らしぶり</span></span>（過日子的樣子）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の仕事ぶりはみんなに認められている。</span>（他的工作表現大家都很肯定）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の話しぶりから、自信を感じた。</span>（從她說話的樣子感受到了自信）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の混雑ぶりに驚いた。</span>（車站擠成那樣，嚇了我一跳）</div><div class='gd-sec'>它多半用來描述、評價<b>別人或某個狀況</b>表現出來的樣子。有幾個字習慣念成「っぷり」，像<span class='gd-jp'>食べっぷり</span>、<span class='gd-jp'>飲みっぷり</span>：</div><div class='gd-ex-line'>・<span class='gd-jp'>いい食べっぷりだね。</span>（你吃得真豪邁耶）</div><div class='gd-h'>用法②：隔了～又～</div><div class='gd-sec'><span class='gd-tag'>怎麼接</span>一段時間＋ぶり，後面常接「に＋動詞」「の＋名詞」，或直接「だ／です」。</div><div class='gd-ex-line'>・<span class='gd-jp'>5年ぶりに母校を訪れた。</span>（睽違五年回到母校）</div><div class='gd-ex-line'>・<span class='gd-jp'>10年ぶりの再会だった。</span>（那是隔了十年的重逢）</div><div class='gd-ex-line'>・<span class='gd-jp'>久しぶりの休みだ。</span>（終於等到久違的假日）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、3年ぶりですね。</span>（田中先生，三年不見了耶）</div><div class='gd-sec'>重點是：中間那段時間<b>都沒發生</b>，現在<b>又發生了</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・用法②後面不能接否定。想說「三年都沒見面」，不能講<span class='gd-jp'>3年ぶりに会わなかった</span>，要講<span class='gd-jp'>3年間会っていない</span>。<br>・用法②一定是「以前有過，現在<b>又</b>來一次」。第一次做的事沒有「又」，就不能用ぶり。<br>・用法①不是什麼字都能接，常見的就那幾個：<span class='gd-jp'>仕事ぶり</span>、<span class='gd-jp'>話しぶり</span>、<span class='gd-jp'>暮らしぶり</span>、<span class='gd-jp'>生活ぶり</span>、<span class='gd-jp'>活躍ぶり</span>、<span class='gd-jp'>混雑ぶり</span>，先當單字整組背起來最實在。<br>・動詞要用ます形的樣子接：是<span class='gd-jp'>話しぶり</span>，不是話すぶり。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「畢業後」的情境：<br><b>て以来</b>＝從那之後<b>一直</b>維持某個狀態：<span class='gd-jp'>卒業して以来、彼には一度も会っていない。</span>（畢業之後就一直沒見過他）<br><b>ぶり</b>＝隔了那麼久，<b>又</b>發生了：<span class='gd-jp'>卒業以来、5年ぶりに彼に会った。</span>（畢業後隔了五年，終於又見到他）<br><b>後</b>＝單純「～之後」，不管以前有沒有發生過：<span class='gd-jp'>卒業して5年後に結婚した。</span>（畢業五年後結婚了）</div><div class='gd-warn'>判斷小訣竅：講「從那之後一直怎樣」用て以来；講「隔了好久，又～了」用ぶり；只是講「～之後」用後。</div>",
  "n2-46": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜がたい」就是中文的<b>「難以～」「很難讓人～」</b>。重點不是你能力不夠，而是<b>心裡過不去</b>：事情太離譜，你實在很難相信、很難接受、很難原諒。語氣比較正式，新聞、文章、正式場合很常見。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，把ます拿掉，再加がたい。<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じます</span> → <span class='gd-jp'>信じがたい</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許します</span> → <span class='gd-jp'>許しがたい</span></span><br><span class='gd-pair'><span class='gd-jp'>理解する</span> → <span class='gd-jp'>理解します</span> → <span class='gd-jp'>理解しがたい</span></span><br>接完之後，整個詞就跟い形容詞一樣用：可以放在名詞前面，也可以改成過去式。<br><span class='gd-pair'><span class='gd-jp'>信じがたい</span> → <span class='gd-jp'>信じがたかった</span></span>（過去很難相信）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>放句尾</span>直接說出「我實在很難～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のあの行動は今でも理解しがたい。</span>（他那個舉動，我到現在還是很難理解）</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は受け入れがたい。</span>（這個結果讓人很難接受）</div><div class='gd-sec'><span class='gd-tag'>放名詞前</span>當形容詞用，這種最常見，很多已經是固定搭配。</div><div class='gd-ex-line'>・<span class='gd-jp'>それは信じがたい話だ。</span>（那真是令人難以置信的事）</div><div class='gd-ex-line'>・<span class='gd-jp'>留学は忘れがたい経験になった。</span>（留學成了難忘的經驗）</div><div class='gd-ex-line'>・<span class='gd-jp'>許しがたい行為だ。</span>（這是不可原諒的行為）</div><div class='gd-sec'>其他常見的還有：<span class='gd-jp'>想像しがたい</span>（難以想像）、<span class='gd-jp'>言いがたい</span>（很難說）、<span class='gd-jp'>得がたい</span>（難能可貴）、<span class='gd-jp'>耐えがたい</span>（難以忍受）。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接的是<b>ます形把ます拿掉</b>，不是辭書形：要說<span class='gd-jp'>信じがたい</span>，不能說信じるがたい。<br>・<b>東西本身不好用、不好做</b>，不能用がたい：筆很難寫是<span class='gd-jp'>このペンは書きにくい</span>，不能說書きがたい。<br>・語氣偏硬、偏正式。跟朋友聊天，說<span class='gd-jp'>信じられない</span>、<span class='gd-jp'>許せない</span>比較自然，講信じがたい會有點像在念稿。<br>・文章裡常寫成漢字「難い」，在這裡念<b>がたい</b>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にくい</b>＝東西本身<b>不好～</b>，物理上、技術上有困難：<br><span class='gd-jp'>この説明は分かりにくい。</span>（這個說明很難懂：寫得不清楚）<br><b>がたい</b>＝<b>心裡很難</b>接受、相信、原諒：<br><span class='gd-jp'>彼の考えは理解しがたい。</span>（他的想法我實在無法理解：心裡無法認同）<br><b>かねる</b>＝站在自己的立場<b>不方便做</b>，常用來客氣地拒絕：<br><span class='gd-jp'>その件にはお答えしかねます。</span>（那件事恕我無法回答）</div><div class='gd-warn'>判斷小訣竅：東西不好用、不好懂，用にくい；心裡過不去、難以接受，用がたい；客氣婉拒對方，用かねる。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>你天天在講的<span class='gd-jp'>ありがたい</span>，其實就是從「有り難い」來的，本來的意思是「很難得、很少有」，後來才變成「值得感謝」。</div>",
  "n2-47": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜かける」就是中文的<b>「～到一半」</b>：書讀到一半、飯吃到一半、話說到一半。事情已經開始了，但還沒做完，停在半路上。接在某些動詞後面，還會變成<b>「差點～」「快要～」</b>的意思。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的ます形，把「ます」拿掉，加上「かける」或「かけの」。<br><span class='gd-pair'><span class='gd-jp'>読みます</span> → <span class='gd-jp'>読みかける</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べかける</span></span><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しかける</span></span><br>「かける」本身照第二類（一段動詞）來變：<span class='gd-jp'>かけた</span>、<span class='gd-jp'>かけて</span>、<span class='gd-jp'>かけている</span>。<br>要修飾東西就用<b>かけの＋名詞</b>：<span class='gd-jp'>飲みかけのコーヒー</span>（喝到一半的咖啡）。<br>放句尾就用<b>かけだ</b>：<span class='gd-jp'>この本はまだ読みかけだ。</span>（這本書我還沒讀完）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>做到一半</span>接「讀、吃、寫、說」這種自己會去做的動作，表示做到一半停住了。</div><div class='gd-ex-line'>・<span class='gd-jp'>読みかけの小説が本棚に積まれている。</span>（讀到一半的小說堆在書架上）</div><div class='gd-ex-line'>・<span class='gd-jp'>何か言いかけて、やめた。</span>（他話說到一半就打住了）</div><div class='gd-ex-line'>・<span class='gd-jp'>飲みかけのコーヒー、捨ててもいい？</span>（這杯喝一半的咖啡可以倒掉嗎？）</div><div class='gd-sec'><span class='gd-tag'>差點、快要</span>接「死、溺水、熄滅、忘記」這種一下子就發生的變化，意思是「就快要那樣了」，或「差一點就那樣，結果沒有」。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のころ、海で溺れかけたことがある。</span>（我小時候在海邊差點溺水）</div><div class='gd-ex-line'>・<span class='gd-jp'>道で死にかけた猫を見つけた。</span>（我在路上發現一隻快死掉的貓）</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れかけていた夢を思い出した。</span>（我想起了一個差點忘記的夢想）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>話しかける</span>不是「話說到一半」，是<b>「找人搭話」</b>，要說「說到一半」請用<span class='gd-jp'>言いかける</span>。<span class='gd-jp'>呼びかける</span>（呼籲）、<span class='gd-jp'>出かける</span>（出門）也都是固定的單字，跟「到一半」沒關係。<br>・修飾名詞最常用「かけの」：<span class='gd-jp'>食べかけのパン</span>（吃到一半的麵包），不要寫成「食べかけパン」。<br>・<span class='gd-jp'>ある</span>、<span class='gd-jp'>いる</span>這種表示「存在、狀態」的動詞，沒有開始和結束可言，不能接かける。<br>・同一個「かける」可能是「到一半」也可能是「差點」，要看前面的動詞來判斷：<span class='gd-jp'>死にかける</span>一定是「差點死掉」，不會是「死到一半」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>用同一個情境比較：<br><b>かける</b>＝已經<b>快到那一步</b>，或停在半路：<span class='gd-jp'>火が消えかけている。</span>（火快熄了，只剩一點點）<br><b>つつある</b>＝<b>正在一點一點地變</b>，重點在變化的過程：<span class='gd-jp'>火が消えつつある。</span>（火正在慢慢變小）<br>另外，<span class='gd-jp'>つつある</span>多半用在書面、新聞報導；<span class='gd-jp'>かける</span>和<span class='gd-jp'>かけの</span>平常講話就很常用。</div><div class='gd-warn'>判斷小訣竅：想說「停在一半、差一點就～」用かける；想說「正在逐漸變化中」用つつある。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟它相反的是<span class='gd-jp'>〜きる</span>（做完、做到底）：<span class='gd-jp'>一晩で読みきった。</span>（一個晚上就讀完了）</div>",
  "n2-48": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことなく」就像中文書面語的<b>「毫不～」「未曾～」「一次也沒～」</b>，意思跟「〜ないで」（沒有～就…）一樣，只是正式很多，常出現在新聞、文章、致詞裡。<br>前面放的是<b>沒有發生的那件事</b>：<span class='gd-jp'>休むことなく</span>＝沒休息、一直沒停。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形（字典上那個原本的樣子）直接加ことなく。<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休むことなく</span></span>（不休息）<br><span class='gd-pair'><span class='gd-jp'>迷う</span> → <span class='gd-jp'>迷うことなく</span></span>（毫不猶豫）<br>「名詞＋する」的動詞也一樣：<span class='gd-pair'><span class='gd-jp'>遅刻する</span> → <span class='gd-jp'>遅刻することなく</span></span>（沒遲到）<br>被動的說法也能接：<span class='gd-pair'><span class='gd-jp'>気づかれる</span> → <span class='gd-jp'>気づかれることなく</span></span>（沒被發現）<br><b>ことなく本身不分過去現在</b>，時間看句子最後面。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>一度も・一日も</span>前面加這些詞，強調「一次都沒有」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一日も休むことなく働き続けた。</span>（他一天都沒休息，一直在工作）</div><div class='gd-sec'><span class='gd-tag'>長期堅持</span>講一件事很久都沒變、沒中斷。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は40年間、変わることなく同じ味を守っている。</span>（這家店 40 年來始終守著同樣的味道）</div><div class='gd-sec'><span class='gd-tag'>表決心</span>致詞、得獎感言很愛用。</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも初心を忘れることなく、頑張ってまいります。</span>（今後我也會不忘初心，繼續努力）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は迷うことなく、この道を選んだ。</span>（她毫不猶豫地選了這條路）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面接<b>肯定</b>的辭書形，不是ない形：○<span class='gd-jp'>休むことなく</span>　×休まないことなく。<br>・看到「休む」別以為是「有休息」，ことなく會把前面那件事整個否定掉。<br>・「名詞＋する」的動詞不能把する省掉：×連絡ことなく　○<span class='gd-jp'>連絡することなく</span>。<br>・這個說法很硬。跟朋友講「早餐沒吃就出門」，說<span class='gd-jp'>食べないで出かけた</span>就好，用ことなく會像在念公文。<br>・通常用在「本來可能會發生、結果卻沒發生」的事（累了也沒休息、本來會猶豫卻沒猶豫），所以常帶有「很堅持、很了不起」的感覺。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事「他沒休息，一直工作」，三種講法：<br><span class='gd-jp'>休まないで働いた。</span>（口語，聊天最常用）<br><span class='gd-jp'>休まずに働いた。</span>（稍微正式，講話、寫東西都可以）<br><span class='gd-jp'>休むことなく働いた。</span>（最書面，聽起來有「始終如一」的分量）<br>意思一樣，差在<b>正式程度</b>。</div><div class='gd-sec'>不過「ないで」還有一個用法：<b>不做A，改做B</b>。這種情況通常不用ことなく。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車に乗らないで、歩いて帰った。</span>（沒搭電車，改用走的回家）</div><div class='gd-sec'>這句換成「電車に乗ることなく」就很不自然。</div><div class='gd-warn'>判斷小訣竅：聊天用ないで，正式一點用ずに，想寫得像新聞、致詞，或強調「一次都沒有」才用ことなく。如果是「不A、改做B」，交給ないで或ずに。</div>",
  "n2-49": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようがない」就是中文的<b>「根本沒辦法～」「想～也無從～」</b>。這裡的「よう」是「方法」的意思，所以「ようがない」就是<b>連方法都沒有</b>。不是你不想做，也不是你能力不夠，是情況讓你找不到任何辦法下手。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>缺條件、缺手段</span>想做，但少了關鍵的東西（資訊、工具、線索），根本無從做起。</div><div class='gd-ex-line'>・<span class='gd-jp'>住所も電話番号も知らないので、連絡しようがない。</span>（地址跟電話都不知道，根本沒辦法聯絡）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部品はもう売っていないから、直しようがないね。</span>（這個零件已經沒在賣了，沒辦法修耶）</div><div class='gd-sec'><span class='gd-tag'>ようもない</span>中間多一個「も」，語氣更強，有「連一點辦法都沒有」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>道が雪で埋まっていて、進みようもなかった。</span>（路都被雪埋了，完全沒辦法前進）</div><div class='gd-sec'>書面、口語都常用，跟朋友講「<span class='gd-jp'>直しようがないよ</span>」也很自然。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞ます形，把ます拿掉，加「ようがない」。<br><span class='gd-pair'><span class='gd-jp'>書きます</span> → 把ます拿掉 → <span class='gd-jp'>書きようがない</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べようがない</span></span><span class='gd-pair'><span class='gd-jp'>連絡します</span> → <span class='gd-jp'>連絡しようがない</span></span></div><div class='gd-sec'><span class='gd-tag'>名詞＋のしようがない</span>「連絡、説明、返事」這類名詞，也常說成「名詞＋の＋しようがない」。<br><span class='gd-pair'><span class='gd-jp'>説明しようがない</span> → <span class='gd-jp'>説明のしようがない</span></span>（兩種都對）</div><div class='gd-sec'><span class='gd-tag'>放在名詞前面</span>常把「が」換成「の」，說成「ようのない＋名詞」，用「ようがない＋名詞」也可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>言いようのない寂しさを感じた。</span>（感到一種說不出的寂寞）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>口語裡最常出現的是這幾個固定說法：<br><span class='gd-jp'>どうしようもない</span>：怎麼樣都沒辦法；也可以罵人「無藥可救」。<br><span class='gd-jp'>しょうがない</span>：沒辦法、算了。其實就是「<span class='gd-jp'>しようがない</span>」念快變來的。<br><span class='gd-jp'>言いようがない</span>：（好到、糟到）難以形容。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨じゃしょうがないね。</span>（下雨的話也沒辦法啦）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接的是<b>ます形</b>，不是意向形：是<span class='gd-jp'>書きようがない</span>，不是「書こうがない」。<br>・<span class='gd-jp'>連絡しようがない</span>的「しよう」看起來很像「我們來做吧」的しよう，其實是「し＋よう（方法）」，意思完全不同。<br>・它講的是<b>沒有方法、沒有手段</b>，不是能力問題。「我不會游泳」要說<span class='gd-jp'>泳げない</span>，不能說「泳ぎようがない」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：被問了一個問題，答不出來。<br><b>可能形否定</b>＝單純「不能」，原因什麼都可以：<span class='gd-jp'>その質問には答えられない。</span>（那個問題我沒辦法回答）<br><b>ようがない</b>＝沒有資訊、沒有根據，<b>無從</b>回答：<span class='gd-jp'>何も聞いていないので、答えようがない。</span>（我什麼都沒聽說，根本無從回答）<br><b>かねる</b>＝其實可以答，但<b>立場上不方便</b>，客服、店員客氣拒絕時用：<span class='gd-jp'>その件についてはお答えしかねます。</span>（關於那件事，恕難回覆）</div><div class='gd-warn'>判斷小訣竅：「缺方法、無從下手」用ようがない；「立場上不方便、婉拒」用かねる；什麼原因都行的「不能」就用可能形否定。</div>",
  "n2-51": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜際（に）」就是「～的時候」的<b>正式版</b>。中文其實也有一樣的字：「離開<b>之際</b>」「入場之際」。日本的車站廣播、店家告示、公司信件很常用它，聽起來比「時」更客氣，也更像公告。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>公告・廣播</span>對客人、對大眾講話，提醒「做這件事的時候要注意什麼」。</div><div class='gd-ex-line'>・<span class='gd-jp'>お降りの際は、足元にご注意ください。</span>（下車時請小心腳步）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご利用の際は、こちらのカードをお見せください。</span>（使用時請出示這張卡）</div><div class='gd-sec'><span class='gd-tag'>商務・正式場合</span>寫信、跟上司或客戶講話。</div><div class='gd-ex-line'>・<span class='gd-jp'>先日お会いした際に、いろいろ教えていただきました。</span>（前幾天見面的時候，您教了我很多）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：後面加「の」再接際。<br><span class='gd-pair'><span class='gd-jp'>入場</span> → <span class='gd-jp'>入場の際</span></span><span class='gd-pair'><span class='gd-jp'>申し込み</span> → <span class='gd-jp'>申し込みの際</span></span><br><b>動詞</b>：辭書形或た形直接接際。<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来る際</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った際</span></span></div><div class='gd-sec'>辭書形跟た形的差別，跟「時」一樣：辭書形是<b>還沒做、正要做</b>的時候；た形是<b>做了之後、那一次</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行く際に、パスポートを作りました。</span>（要去日本的時候辦了護照：出發前）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行った際に、友達に会いました。</span>（去日本的時候見了朋友：到了之後）</div><div class='gd-sec'>後面用「に」是一般的「在～時」；換成「は」會帶出「這種時候呢，請…」的提醒感，所以告示很常寫「〜の際は」。兩種都對。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>「お／ご＋名詞＋の際」：前面的お、ご是對客人的敬意，整組背起來就好。<br><span class='gd-jp'>お帰りの際</span>（您回去的時候）、<span class='gd-jp'>お降りの際</span>（您下車的時候）、<span class='gd-jp'>ご来店の際</span>（您來店的時候）、<span class='gd-jp'>ご利用の際</span>（您使用的時候）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面一定要有「の」：是<span class='gd-jp'>入場の際</span>，不是入場際。<br>・際念<b>さい</b>。<br>・日常聊天不要用。「昨天吃飯的時候」說<span class='gd-jp'>昨日ご飯を食べた時</span>就好，講成「食べた際」會像在寫報告。<br>・際講的是<b>做某個動作的那個時刻</b>，不用在一段時期或狀態上：「小時候」是<span class='gd-jp'>子どもの時</span>，不是子どもの際。形容詞一般也不接際，「忙的時候」要說<span class='gd-jp'>忙しい時</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：登入網站。<br><b>時</b>＝一般說法，什麼場合都能用：<span class='gd-jp'>ログインする時、パスワードを入れます。</span>（登入的時候要輸入密碼）<br><b>際</b>＝正式說法，公告、說明文常見：<span class='gd-jp'>ログインの際は、パスワードを入力してください。</span>（登入時請輸入密碼）<br><b>場合</b>＝「如果遇到～的話」，不一定每個人都會碰到：<span class='gd-jp'>パスワードを忘れた場合は、こちらをクリックしてください。</span>（如果忘記密碼，請點這裡）<br>每個人登入都要輸入密碼，所以用際；只有部分人會忘記密碼，所以用場合。</div><div class='gd-warn'>判斷小訣竅：跟朋友聊天用「時」；寫公告、對客人講話用「際」；「萬一～的話」用「場合」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜に先立って」也是正式說法，意思是「在～之前」：<span class='gd-jp'>開会に先立って、社長が挨拶をしました。</span>（開會之前，社長先致詞了）</div>",
  "n2-52": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜からすると」就是中文的<b>「站在～的立場來看」「從～看來」</b>。前面放一個人，就是換到那個人的位置想事情；前面放一個線索（表情、樣子、成績），就是根據這個線索來推斷。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋<span class='gd-jp'>からすると</span>／<span class='gd-jp'>からすれば</span>／<span class='gd-jp'>からしたら</span><br>三個意思一樣，<span class='gd-jp'>からしたら</span>比較口語，聊天很常聽到。<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親からすると</span></span><span class='gd-pair'><span class='gd-jp'>彼の表情</span> → <span class='gd-jp'>彼の表情からすれば</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>站在某人的立場</span>前面放人或團體，例如<span class='gd-jp'>親</span>、<span class='gd-jp'>子供</span>、<span class='gd-jp'>外国人</span>、<span class='gd-jp'>会社</span>。意思是「換成那個人會這樣看」，跟你自己的感覺不一定一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>親からすると、子供の将来を心配するのは自然なことだ。</span>（站在父母的立場，擔心孩子的未來是很自然的事）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供からしたら、大人の話はつまらないだろう。</span>（從小孩的角度來看，大人聊的東西大概很無聊吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>外国人からすれば、敬語はかなり難しい。</span>（從外國人的角度來看，敬語相當難）</div><div class='gd-sec'><span class='gd-tag'>根據線索判斷</span>前面放看得到的線索，例如<span class='gd-jp'>表情</span>、<span class='gd-jp'>様子</span>、<span class='gd-jp'>話し方</span>、<span class='gd-jp'>成績</span>。句尾常接<span class='gd-jp'>ようだ</span>、<span class='gd-jp'>らしい</span>、<span class='gd-jp'>はずだ</span>、<span class='gd-jp'>だろう</span>，表示「我是這樣推測的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の表情からすると、何か隠しているようだ。</span>（從他的表情看來，他好像在隱瞞什麼）</div><div class='gd-ex-line'>・<span class='gd-jp'>この成績からすれば、合格できるはずだ。</span>（照這個成績來看，應該考得上）</div><div class='gd-ex-line'>・<span class='gd-jp'>空の様子からすると、午後は雨になりそうだ。</span>（從天空的樣子看來，下午好像會下雨）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的「から」<b>不是「因為」</b>。<span class='gd-jp'>親からすると</span>不是「因為父母」，是「從父母那邊看」。也不要跟<span class='gd-jp'>からには</span>（既然～就～）、<span class='gd-jp'>からこそ</span>（正因為～）混在一起。<br>・前面只接<b>名詞</b>。想拿某個動作當線索，要先講成名詞，例如<span class='gd-jp'>彼の話し方からすると</span>，不能直接說「話すからすると」。<br>・<span class='gd-jp'>すれば</span>、<span class='gd-jp'>したら</span>長得像「如果～」，但這裡<b>沒有假設的意思</b>，三個都是「從～來看」。<br>・後半句講的是<b>看法或判斷</b>，不會接「我要去做～」「請你～」這種決定或請求的句子。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b><span class='gd-jp'>にとって</span></b>＝這件事<b>對某人來說是什麼</b>，後面常接評價的詞（<span class='gd-jp'>大切</span>、<span class='gd-jp'>ありがたい</span>、<span class='gd-jp'>難しい</span>）。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供にとって、親は一番大切な存在だ。</span>（對小孩來說，父母是最重要的人）</div><div class='gd-sec'><b><span class='gd-jp'>からすると</span></b>＝換到那個人的位置，講他<b>會怎麼看、怎麼想</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供からすると、親の注意はうるさいだけだろう。</span>（從小孩的角度看，父母的叮嚀大概只會覺得囉嗦吧）</div><div class='gd-sec'>另外，「根據線索判斷」的用法不能換成<span class='gd-jp'>にとって</span>，不會說「<span class='gd-jp'>表情にとって</span>」（這時可以用<span class='gd-jp'>からすると</span>或<span class='gd-jp'>から見ると</span>）。<br><br><b><span class='gd-jp'>から見ると</span></b>＝跟<span class='gd-jp'>からすると</span>大多可以互換，「站在某人立場」和「根據線索判斷」兩種用法都能用。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの様子から見ると、何かあったらしい。</span>（從那個樣子看來，好像發生了什麼事）</div><div class='gd-warn'>判斷小訣竅：講「這件事對某人有什麼價值、影響」用<span class='gd-jp'>にとって</span>；講「換成某人會怎麼想」或「根據線索推斷」用<span class='gd-jp'>からすると</span>，這時換成<span class='gd-jp'>から見ると</span>通常也可以。</div>",
  "n2-53": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にかけては」就是中文的<b>「說到～，（某人）可是很厲害的」</b>。先點出一個領域，例如做菜、數學、業務，後面接「沒人比得上」「不輸任何人」這種稱讚。整句話的重點是<b>那個人在這方面特別強</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋にかけては<br><span class='gd-pair'><span class='gd-jp'>料理</span> → <span class='gd-jp'>料理にかけては</span></span>（說到做菜）<br>要講的是一個動作的話，先加「こと」把它變成名詞：<br><span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることにかけては</span></span>（說到跑步）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>誇別人</span>後面最常接「<span class='gd-jp'>右に出る者はいない</span>」（沒有人在他之上）、「<span class='gd-jp'>かなう人はいない</span>」（沒人比得過）。</div><div class='gd-ex-line'>・<span class='gd-jp'>和食にかけては、彼女の右に出る者はいない。</span>（說到日本料理，沒有人比得上她）</div><div class='gd-ex-line'>・<span class='gd-jp'>営業にかけては、彼が社内一だ。</span>（說到跑業務，他是全公司第一）</div><div class='gd-sec'><span class='gd-tag'>講自己</span>後面接「<span class='gd-jp'>誰にも負けない</span>」（不輸給任何人）、「<span class='gd-jp'>自信がある</span>」（很有自信）。</div><div class='gd-ex-line'>・<span class='gd-jp'>記憶力にかけては、誰にも負けない。</span>（說到記憶力，我不輸給任何人）</div><div class='gd-ex-line'>・<span class='gd-jp'>人の名前を覚えることにかけては、自信がある。</span>（說到記人名，我很有自信）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>一種本事、一個擅長的領域</b>，後面要接<b>能力很強的評價</b>。像「<span class='gd-jp'>日本の天気にかけては</span>」這種跟能力無關的話題就不能用。<br>・拿缺點來套，例如「說到找藉口，他可是天才」，就變成挖苦、開玩笑的口氣，不是正經稱讚。<br>・「は」不要漏掉。少了は變成「にかけて」，會被當成另一個講時間、地點範圍的文法。<br>・這個說法偏正式，像在介紹人、寫文章。跟朋友聊天比較常說「<span class='gd-jp'>料理なら誰にも負けない</span>」（做菜的話我不輸任何人）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にかけて</b>（沒有は）＝從哪裡到哪裡的<b>範圍</b>，前面放時間或地點：<br><div class='gd-ex-line'>・<span class='gd-jp'>今夜から明日の朝にかけて、雨が降るでしょう。</span>（從今晚到明天早上會下雨）</div><b>にかけては</b>＝說到某種<b>本事</b>：<br><div class='gd-ex-line'>・<span class='gd-jp'>数学にかけては、クラスで彼に勝てる人はいない。</span>（說到數學，班上沒人贏得了他）</div></div><div class='gd-sec'><b>に関しては</b>＝單純「關於～」，只是點出話題，後面講什麼都可以：<br><div class='gd-ex-line'>・<span class='gd-jp'>料理に関しては、母に聞いてください。</span>（做菜的事情，請去問我媽）</div><b>にかけては</b>＝後面一定是在誇這方面的實力：<br><div class='gd-ex-line'>・<span class='gd-jp'>料理にかけては、母にかなう人はいない。</span>（說到做菜，沒人比得過我媽）</div></div><div class='gd-warn'>判斷小訣竅：前面是時間、地點，用にかけて。只是交代話題，用に関しては。想說「這方面他最強」，才用にかけては。</div>",
  "n2-55": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にしろ／〜にせよ」就是中文的<b>「不管是A還是B，都～」</b>、<b>「就算是～，也～」</b>。前面先丟出幾種可能，後面講一個<b>不會因此改變</b>的結論或看法。兩個意思一樣，<span class='gd-jp'>にせよ</span>比較正式，文章、正式場合比較常看到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>不管A還是B</span>把兩個（或幾個）選項擺在一起，不管是哪一個，結論都一樣。這是最常見的樣子。</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにしろ行かないにしろ、早めに連絡してください。</span>（不管去不去，都請早點聯絡）</div><div class='gd-ex-line'>・<span class='gd-jp'>肉にせよ魚にせよ、新鮮なものを選びたい。</span>（不管是肉還是魚，都想挑新鮮的）</div><div class='gd-sec'><span class='gd-tag'>不管什麼</span>前面放「何」「どちら」「誰」這類問人問事的詞，意思是「不管是哪一種都一樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何をするにしろ、健康が一番大事だ。</span>（不管做什麼，健康最重要）</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、一度会って話しましょう。</span>（總之，先見個面談談吧）</div><div class='gd-sec'><span class='gd-jp'>いずれにせよ</span>、<span class='gd-jp'>どっちにしろ</span>幾乎是固定說法，等於「總之、反正」。開會、日常聊天都很常聽到。</div><div class='gd-sec'><span class='gd-tag'>就算是～</span>只放一個情況，意思是「就算真的是那樣，也～」，常帶一點不以為然或提醒的口氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にしろ、そんなことを言うべきではない。</span>（就算是開玩笑，也不該說那種話）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいにせよ、電話ぐらいできたはずだ。</span>（就算再忙，打個電話總可以吧）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：用普通形（就是不加ます的說法，肯定、否定、過去都可以），直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないにしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ</span></span></div><div class='gd-sec'><b>名詞、な形容詞</b>：直接接，或是先加「である」再接（比較正式）。<b>中間不能放だ</b>。<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生にしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便にせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便であるにせよ</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面<b>不能加だ</b>：<span class='gd-jp'>学生だにしろ</span>、<span class='gd-jp'>不便だにせよ</span>都是錯的。<br>・用「AにしろBにしろ」時，A跟B要是同一類、對等的東西：<span class='gd-jp'>賛成にしろ反対にしろ</span>、<span class='gd-jp'>行くにしろ行かないにしろ</span>。<br>・後半句多半是你的<b>看法、要求或建議</b>，像<span class='gd-jp'>べきだ</span>、<span class='gd-jp'>てください</span>、<span class='gd-jp'>ほうがいい</span>。<br>・<span class='gd-jp'>しろ</span>、<span class='gd-jp'>せよ</span>本來是<span class='gd-jp'>する</span>的命令形，但在這裡<b>完全沒有命令的意思</b>。<span class='gd-jp'>勉強しろ</span>是「給我去念書」，<span class='gd-jp'>勉強にしろ遊びにしろ</span>是「不管念書還是玩」，差別就在有沒有「に」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にしても</b>：意思跟にしろ、にせよ幾乎一樣，差在正式程度。<br>・<span class='gd-jp'>行くにしても行かないにしても、連絡してね。</span>（不管去不去都跟我說一聲喔：朋友之間）<br>・<span class='gd-jp'>出席されるにせよされないにせよ、ご連絡ください。</span>（無論出席與否，都請與我們聯絡：正式通知）<br>由隨興到正式大概是：<span class='gd-jp'>にしても</span> → <span class='gd-jp'>にしろ</span> → <span class='gd-jp'>にせよ</span>。</div><div class='gd-sec'><b>を問わず</b>：「不拘、不分」，前面只接名詞，常是「年齢」「男女」這種整個範圍，用在規定、徵人廣告。<br>・<span class='gd-jp'>年齢を問わず、誰でも参加できます。</span>（不限年齡，誰都可以參加）<br>・<span class='gd-jp'>大人にしろ子どもにしろ、参加費は同じだ。</span>（不管是大人還是小孩，參加費都一樣）</div><div class='gd-warn'>判斷小訣竅：講「不限～」的條件範圍用を問わず；把具體選項一個個列出來再下結論，用にしろ・にせよ；跟朋友聊天用にしても最自然，寫文章、正式場合用にせよ。</div>",
  "n2-56": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にほかならない」就是中文的<b>「正是～」「無非就是～」「說穿了就是～」</b>。說話的人很篤定地下結論：答案就是這個，<b>不是別的</b>。<br>「ほか」是「其他」的意思，「ほかならない」字面上就是「不會是其他東西」，所以才變成「正是」。語氣很硬，多半出現在文章、演講、新聞評論裡。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>斷定本質</span>「A 說穿了就是 B」，把一件事的真面目講出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は、皆さんの協力の成果にほかならない。</span>（這個結果正是各位合作的成果）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、言い訳にほかならない。</span>（他的說明說穿了就是藉口）</div><div class='gd-sec'><span class='gd-tag'>斷定原因</span>用「〜のは、〜からにほかならない」，意思是「之所以～，不是別的，正是因為～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が合格できたのは、毎日努力したからにほかならない。</span>（他之所以能考上，正是因為每天都很努力）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故が起きたのは、安全確認を怠ったからにほかならない。</span>（會發生事故，無非就是因為疏於安全確認）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>努力の結果</span> → <span class='gd-jp'>努力の結果にほかならない</span></span><br><b>講原因</b>：普通形後面先加「から」，再接。<span class='gd-pair'><span class='gd-jp'>努力した</span> → <span class='gd-jp'>努力したからにほかならない</span></span><br><b>講一個動作的本質</b>：動詞辭書形加「こと」，把它變成名詞再接。<span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げることにほかならない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>何もしないのは、問題から逃げることにほかならない。</span>（什麼都不做，說穿了就是在逃避問題）</div><div class='gd-sec'>在演講、正式場合要客氣一點，就說<b>にほかなりません</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・看到「ならない」別以為是否定或「不可以」。它是<b>很強的肯定</b>：「正是」。<br>・動詞不能直接接：說<span class='gd-jp'>遅れたからにほかならない</span>，不能說遅れたにほかならない。<br>・前面用「〜のは」在問「為什麼會這樣」時，後面用「〜からにほかならない」或「〜のおかげにほかならない」比較自然，直接放一個名詞容易變成前後對不上。<br>・跟朋友聊天用它會很像在念論文。口語說「〜からだよ」「まさに〜だ」就好。<br>・它是篤定的斷言，不是猜測。沒把握的事不要用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にすぎない</b>＝「只是～而已」，帶有<b>看輕、小看</b>的感覺。<br><span class='gd-jp'>彼の成功は運がよかったからにすぎない。</span>（他會成功只不過是運氣好而已）<br><span class='gd-jp'>彼の成功は努力の結果にほかならない。</span>（他會成功正是努力的結果）<br>兩個長得很像，但一個是在貶，一個是在下結論。</div><div class='gd-sec'><b>からこそ</b>＝強調「<b>正因為</b>這個原因，才有這個結果」。可以放句子中間，也可以用「〜のは〜からこそだ」放句尾，口語也常講，常帶有感情。<br><span class='gd-jp'>努力したからこそ、合格できた。</span>（正因為努力了，才考上）<br><span class='gd-jp'>合格できたのは、努力したからこそだ。</span>（能考上，正是因為努力了）<br><span class='gd-jp'>合格できたのは、努力したからにほかならない。</span>（能考上，不是別的，正是因為努力）<br>最後兩句意思很接近，差別在語氣：からこそ是在<b>強調那個原因</b>；にほかならない是在<b>斷定「不是別的」</b>，比較硬、比較書面，像在寫報告下結論。</div><div class='gd-warn'>判斷小訣竅：想說「只是～而已」、有點看不起，用にすぎない；想強調「正因為～才…」，用からこそ；想很篤定地下結論說「不是別的，就是～」，用にほかならない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「很篤定」的語氣，可以接著比較<span class='gd-jp'>〜に違いない</span>、<span class='gd-jp'>〜に相違ない</span>：它們是「一定是～」的強烈推測，而にほかならない是直接斷定「就是～」。</div>",
  "n2-58": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とは限らない」就是中文的<b>「不見得～」「未必～」</b>。大家以為「一定是這樣」的事，你出來說一句「不一定喔，也有例外」。像台灣人常說的「貴的不一定好」，日文就是<span class='gd-jp'>高いものがいいとは限らない。</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>打破刻板印象</span>對「大家都覺得理所當然」的想法踩煞車。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人がみんな寿司が好きだとは限らない。</span>（日本人不見得都喜歡壽司）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の言うことがいつも正しいとは限らない。</span>（老師說的不一定每次都對）</div><div class='gd-sec'><span class='gd-tag'>提醒有風險</span>事情不保證會照預期走，所以先做準備。</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報が当たるとは限らないから、傘を持っていこう。</span>（氣象預報不一定準，帶把傘去吧）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放一個完整的句子（普通形，也就是不加です・ます的說法），後面直接接とは限らない。<br>動詞：<span class='gd-pair'><span class='gd-jp'>成功する</span> → <span class='gd-jp'>成功するとは限らない</span></span><br>い形容詞：<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いとは限らない</span></span><br>な形容詞：<span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとは限らない</span></span>（だ也常省略：<span class='gd-jp'>便利とは限らない</span>）<br>名詞：<span class='gd-pair'><span class='gd-jp'>本物だ</span> → <span class='gd-jp'>本物だとは限らない</span></span>（一樣可以說<span class='gd-jp'>本物とは限らない</span>）<br>對長輩、正式場合就說<span class='gd-jp'>とは限りません</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>必ずしも〜</span>前面加<span class='gd-jp'>必ずしも</span>（不一定），「未必」的感覺更清楚，文章裡很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>有名な大学を出た人が、必ずしも仕事ができるとは限らない。</span>（名校畢業的人，未必就很會做事）</div><div class='gd-sec'><span class='gd-tag'>からといって〜</span>「不能因為～就說一定～」，整句一起記最好用。</div><div class='gd-ex-line'>・<span class='gd-jp'>安いからといって、お得だとは限らない。</span>（不能因為便宜就說一定划算）</div><div class='gd-sec'><span class='gd-tag'>みんな・いつも・全て</span>前面常出現這些「全部、每次」的詞，因為とは限らない就是專門用來推翻「全部都這樣」的說法。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它是「<b>不一定</b>」，不是「<b>不是</b>」。<span class='gd-jp'>高いものがいいとは限らない</span>只是說貴的不保證好，沒有說貴的東西不好。<br>・<span class='gd-jp'>必ずしも</span>後面一定要接否定，不能說「必ずしもいい」，要說<span class='gd-jp'>必ずしもいいとは限らない</span>。<br>・小心看到<span class='gd-jp'>〜ないとも限らない</span>，意思會反過來：<span class='gd-jp'>事故が起きないとも限らない。</span>是「也不能保證不會出事」，也就是<b>還是有可能出事</b>，用來提醒要小心。<br>・限る念<b>かぎる</b>，所以是かぎらない，不要念成げんらない。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「週末人多不多」：<br><b>に限らず</b>＝不只～（範圍更大）：<span class='gd-jp'>この店は週末に限らず、いつも混んでいる。</span>（這家店不只週末，平常也都很多人）<br><b>とは限らない</b>＝不一定～（有例外）：<span class='gd-jp'>週末だからといって、混んでいるとは限らない。</span>（就算是週末，也不一定人多）<br><b>に決まっている</b>＝一定～（很有把握）：<span class='gd-jp'>週末だから、混んでいるに決まっている。</span>（週末耶，一定很多人）</div><div class='gd-warn'>判斷小訣竅：<b>名詞＋に限らず</b>＝「不只～」；<b>整個句子＋とは限らない</b>＝「不一定～」。想說「一定」就用に決まっている，想說「不一定」就用とは限らない。</div>",
  "n2-59": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「<span class='gd-jp'>〜をきっかけに</span>」就是中文的<b>「因為～這件事，開始了…」「趁著～，就…」</b>。前面放一件觸發你的事，後面放因此<b>開始的新行動或改變</b>。像是「因為來日本，開始自己煮飯」、「因為生病，開始注意健康」。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たのをきっかけに、料理を始めた。</span>（來日本之後，就開始自己做菜了）</div><div class='gd-ex-line'>・<span class='gd-jp'>入院をきっかけに、健康に気をつけるようになった。</span>（住院之後，我開始注意健康）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞</span>直接接：<span class='gd-pair'><span class='gd-jp'>留学</span> → <span class='gd-jp'>留学をきっかけに</span></span><br><span class='gd-tag'>動詞</span>先加「の」或「こと」，把它變成一件事，再接：<span class='gd-pair'><span class='gd-jp'>子どもが生まれた</span> → <span class='gd-jp'>子どもが生まれたのをきっかけに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが生まれたのをきっかけに、タバコをやめた。</span>（小孩出生之後，我就把菸戒了）</div><div class='gd-sec'>後面常常配「<span class='gd-jp'>始めた</span>」「<span class='gd-jp'>ようになった</span>」「<span class='gd-jp'>やめた</span>」這類講「開始、改變」的說法。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>がきっかけで</span>把觸發的事當主角，口語很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>友達の一言がきっかけで、転職を考えるようになった。</span>（朋友的一句話，讓我開始考慮換工作）</div><div class='gd-sec'><span class='gd-tag'>きっかけは〜</span>面試、自我介紹超常被問的一句。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を始めたきっかけは何ですか。</span>（你當初是因為什麼開始學日文的？）</div><div class='gd-ex-line'>・<span class='gd-jp'>アニメがきっかけです。</span>（是因為動畫）</div><div class='gd-sec'><span class='gd-tag'>をきっかけとして</span>意思一樣，比較正式，新聞、文章裡比較常看到。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞前面一定要加「の」或「こと」：要說<span class='gd-jp'>日本に来たのをきっかけに</span>，不能直接說「日本に来たをきっかけに」。<br>・「を」配「に」、「が」配「で」：<span class='gd-jp'>留学をきっかけに</span>／<span class='gd-jp'>留学がきっかけで</span>，兩組不要拆開亂配。<br>・它講的是「觸發你開始新的事」，不是單純的原因。像「因為大雨電車停駛」這種直接造成的結果，用<span class='gd-jp'>大雨で電車が止まった</span>就好，用きっかけ反而怪。<br>・前面好事壞事都可以放，生病、失戀、被罵都可以是きっかけ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「搬家」這件事：<br><b>をきっかけに</b>＝搬家<b>觸發</b>你開始做一件新的事：<br><span class='gd-jp'>引っ越しをきっかけに、ジョギングを始めた。</span>（趁著搬家，我開始慢跑）<br><b>て以来</b>＝<b>自從</b>那之後，一直維持某個狀態：<br><span class='gd-jp'>引っ越して以来、毎朝ジョギングしている。</span>（自從搬家以後，我每天早上都在慢跑）<br><b>に伴って</b>＝搬家<b>連帶</b>會跟著發生的事，不是你自己被啟發想做的：<br><span class='gd-jp'>引っ越しに伴って、住所変更の手続きをした。</span>（因為搬家，跟著辦了地址變更手續）</div><div class='gd-warn'>判斷小訣竅：「因為那件事，我開始～」是をきっかけに；「從那之後一直～」是て以来；「那件事一發生，就理所當然跟著～」是に伴って。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>更正式的說法有「<span class='gd-jp'>〜を機に</span>」「<span class='gd-jp'>〜を契機に</span>」，公司公告、新聞很常見：<span class='gd-jp'>結婚を機に、仕事を辞めた。</span>（趁著結婚，把工作辭了）</div>",
  "n2-60": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜あげく」就是中文的<b>「搞了老半天，結果…」「折騰到最後，到頭來…」</b>。前面是一段又長又累的過程，後面多半是讓人無奈、不想要的結果。說的人常常帶著一點抱怨或「白忙一場」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>さんざん待たされたあげく、満席だと言われた。</span>（被晾在那邊等了老半天，結果跟我說客滿）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞用<b>た形</b>（過去式那個形），後面接<span class='gd-jp'>あげく</span>：<br><span class='gd-pair'><span class='gd-jp'>迷う</span> → <span class='gd-jp'>迷ったあげく</span></span><span class='gd-pair'><span class='gd-jp'>悩む</span> → <span class='gd-jp'>悩んだあげく</span></span><br>名詞加「の」再接：<br><span class='gd-pair'><span class='gd-jp'>議論</span> → <span class='gd-jp'>議論のあげく</span></span><span class='gd-pair'><span class='gd-jp'>けんか</span> → <span class='gd-jp'>けんかのあげく</span></span><br>後面加不加「に」都可以，意思一樣。漢字寫成<span class='gd-jp'>挙げ句</span>，看到也要認得。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>白忙一場</span>前面常配<span class='gd-jp'>さんざん</span>（狠狠地、一直）、<span class='gd-jp'>何度も</span>（好幾次），後面常配<span class='gd-jp'>結局</span>（到頭來）。</div><div class='gd-ex-line'>・<span class='gd-jp'>さんざん迷ったあげく、結局何も買わなかった。</span>（猶豫了老半天，結果什麼都沒買）</div><div class='gd-ex-line'>・<span class='gd-jp'>長時間の議論のあげく、何も決まらなかった。</span>（討論了好久，結果什麼都沒決定）</div><div class='gd-sec'><span class='gd-tag'>無奈的決定</span>想了很久，最後只好做出某個決定。</div><div class='gd-ex-line'>・<span class='gd-jp'>悩んだあげく、旅行には行かないことにした。</span>（煩惱了很久，最後決定不去旅行了）</div><div class='gd-sec'><span class='gd-tag'>あげくの果てに</span>固定說法，意思是「到最後甚至還…」，用來講事情越來越糟、糟到最誇張的那一步。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は遅刻を繰り返し、あげくの果てに無断で休んだ。</span>（他一直遲到，到最後甚至沒請假就直接不來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞一定用た形：<span class='gd-jp'>迷うあげく</span>是錯的，要說<span class='gd-jp'>迷ったあげく</span>。<br>・前面要是<b>拖很久、反覆發生</b>的過程。一下子就做完的動作不能用：<span class='gd-jp'>ドアを開けたあげく</span>、<span class='gd-jp'>一度電話したあげく</span>都很怪。要像<span class='gd-jp'>何度も電話したあげく、やっと通じたと思ったら留守電だった。</span>（打了好幾次電話，好不容易以為通了，結果是語音信箱）這樣才自然。<br>・後面是<b>已經發生的結局</b>，句尾多半是過去式。不能接「我們來～吧」「請～」這種還沒發生的事。<br>・結果是好事時不要用：<span class='gd-jp'>努力したあげく合格した</span>聽起來很怪，要換成下面的<span class='gd-jp'>末に</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b><span class='gd-jp'>末に</span></b>也是「經過一番～之後，最後…」，接法也一樣（た形／名詞の＋<span class='gd-jp'>末に</span>）。差別在<span class='gd-jp'>末に</span>口氣<b>比較中性</b>，好結果、壞結果都能接，新聞、正式文章很常用；<span class='gd-jp'>あげく</span>則帶著「搞半天結果還是這樣」的抱怨感，幾乎只接不好的結果。<br>同樣是開會開很久：<br><span class='gd-jp'>何度も話し合った末に、新しい計画が決まった。</span>（討論了好幾次，最後終於決定了新計畫：好結果，只能用<span class='gd-jp'>末に</span>）<br><span class='gd-jp'>何度も話し合ったあげく、結局何も決まらなかった。</span>（討論了好幾次，結果什麼都沒決定：抱怨的口氣，用<span class='gd-jp'>あげく</span>最傳神）</div><div class='gd-warn'>判斷小訣竅：結果是好的或只是平鋪直敘，用<span class='gd-jp'>末に</span>；想抱怨「搞了半天結果…」，用<span class='gd-jp'>あげく</span>。</div>",
  "n2-61": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てはじめて」就是中文的<b>「～了之後才（懂／發現）…」「直到～才…」</b>。就像大家常說的「失去了才懂得珍惜」：前面是你<b>親身經歷</b>的事，後面是經歷之後<b>才終於明白、才第一次感受到</b>的東西。重點是：在那之前，你其實不懂。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的て形，後面直接加「はじめて」（也常寫成漢字「初めて」）。<br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なって</span> → <span class='gd-jp'>なってはじめて</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してはじめて</span></span><br><span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われて</span> → <span class='gd-jp'>言われてはじめて</span></span><br>後面通常會加逗號，再接「才發現的事」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>經歷之後才懂</span>後面最常接<span class='gd-jp'>わかる</span>、<span class='gd-jp'>気づく</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>実感する</span>這種「理解、發現」的詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>親になってはじめて、親の気持ちがわかった。</span>（自己當了父母，才懂父母的心情）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしをしてはじめて、家事の大変さに気づいた。</span>（自己一個人住之後，才發現做家事有多辛苦）</div><div class='gd-ex-line'>・<span class='gd-jp'>言われてはじめて気づきました。</span>（被人家說了我才發現）</div><div class='gd-sec'><span class='gd-tag'>講一般道理</span>用現在式，講「人就是要～過才會…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>病気になってはじめて、健康のありがたさがわかる。</span>（生了病才會知道健康的可貴）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面<b>不能接自己的打算、命令或拜託</b>。<br>×<span class='gd-jp'>日本に来てはじめて、日本語を勉強しよう。</span><br>後面要放的是「已經發生的領悟、變化」，不是「我要去做什麼」。<br>・別跟「動詞ます形＋<span class='gd-jp'>はじめる</span>」（開始～）搞混：<span class='gd-jp'>食べはじめる</span>是「開始吃」；<span class='gd-jp'>食べてはじめて</span>是「吃了之後才…」。差別就在中間有沒有那個「て」。<br>・這個句型自帶「在那之前都不知道」的感覺，所以用在本來就知道、理所當然的事會很怪。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「要做過才知道」，看兩種說法：<br><b>てはじめて</b>＝回頭看，<b>做了之後才明白</b>：<span class='gd-jp'>実際に使ってみてはじめて、よさがわかった。</span>（實際用了之後，才知道它的好）<br><b>ないことには</b>＝往前講條件，<b>不先做就沒辦法</b>，後面多半是否定：<span class='gd-jp'>実際に使ってみないことには、よさはわからない。</span>（不實際用用看，就不會知道它好不好）</div><div class='gd-warn'>判斷小訣竅：在講「經歷之後才恍然大悟」用てはじめて；在講「不先～的話就沒辦法…」用ないことには。</div>",
  "n2-63": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ものがある」就是中文的<b>「有一種～的地方」「確實讓人覺得～」</b>。你聽一場演奏、看一張老照片，心裡被某種東西打到，可是又說不清楚到底是什麼，日文就用它來講：<span class='gd-jp'>彼の演奏には心を打つものがある。</span>（他的演奏有種打動人心的力量）<br>這裡的<span class='gd-jp'>もの</span>不是指看得到的東西，而是<b>一種說不太出來的特質、感覺</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>評價人事物</span>稱讚作品、表現、能力。比起直接說「很厲害」，聽起來比較有深度、比較穩重，影評、新聞、主管講評很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の演奏には人を引き込むものがある。</span>（他的演奏有一種吸引人的魅力）</div><div class='gd-ex-line'>・<span class='gd-jp'>新人だが、彼女の企画には光るものがある。</span>（雖然是新人，她的企劃有亮眼的地方）</div><div class='gd-sec'><span class='gd-tag'>說自己的感受</span>某件事讓你有某種感覺，好的壞的都可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>この古い写真にはどこか懐かしいものがある。</span>（這張舊照片總有一種令人懷念的感覺）</div><div class='gd-ex-line'>・<span class='gd-jp'>この年で徹夜するのは、つらいものがある。</span>（到這個年紀還熬夜，真的有點吃不消）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞：直接接原形（字典上的樣子）　<span class='gd-pair'><span class='gd-jp'>心を打つ</span> → <span class='gd-jp'>心を打つものがある</span></span><br>い形容詞：直接接　<span class='gd-pair'><span class='gd-jp'>懐かしい</span> → <span class='gd-jp'>懐かしいものがある</span></span><br>な形容詞：要補一個「な」　<span class='gd-pair'><span class='gd-jp'>見事</span> → <span class='gd-jp'>見事なものがある</span></span><br>否定也可以：<span class='gd-pair'><span class='gd-jp'>納得できない</span> → <span class='gd-jp'>納得できないものがある</span></span>（有點讓人無法接受）<br>前面常用「<span class='gd-jp'>〜には</span>」帶出主角：<span class='gd-jp'>この映画には</span>、<span class='gd-jp'>彼の言葉には</span>……</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>這幾個幾乎是固定搭配，整組記起來最快：<br><span class='gd-jp'>心を打つものがある</span>（打動人心）<br><span class='gd-jp'>胸に迫るものがある</span>（令人深受感動、觸動心弦）<br><span class='gd-jp'>目を見張るものがある</span>（令人刮目相看）<br><span class='gd-jp'>光るものがある</span>（有亮眼之處）<br><span class='gd-jp'>見るべきものがある</span>（有值得一看的地方）<br><span class='gd-jp'>感慨深いものがある</span>（讓人感慨萬千）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>不是每個「ものがある」都是這個文法</b>：<span class='gd-jp'>この店にはおいしいものがある。</span>就只是「這家店有好吃的東西」，講的是真的食物。文法版的主角通常是作品、表現、經驗這種抽象的東西。<br>・<b>過去式放在ある</b>：要說「當時很感動」是<span class='gd-jp'>心を打つものがあった</span>，不要寫成心を打ったものがある。<br>・<b>な形容詞別忘了な</b>：是<span class='gd-jp'>見事なものがある</span>，不是見事ものがある，也不能直接接名詞。<br>・<b>客觀事實不要用</b>：房間大不大量得出來，直接說<span class='gd-jp'>この部屋は広い</span>就好，說成「この部屋には広いものがある」很奇怪。它是用在「讓人有感覺」的特質。<br>・語氣偏正式，但口語也會用，像<span class='gd-jp'>それはちょっとつらいものがあるね</span>（那還真有點難受耶）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ものだ（感嘆）</b>＝「～真是～啊」，對<b>一般道理、人生</b>發出感嘆：<br><span class='gd-jp'>子どもの成長は早いものだ。</span>（小孩長得真快啊）<br><b>ものがある</b>＝指著<b>某個特定的人事物</b>，說它身上有某種特質：<br><span class='gd-jp'>彼の成長ぶりには目を見張るものがある。</span>（他的進步讓人刮目相看）</div><div class='gd-warn'>判斷小訣竅：感嘆「人生、世事就是這樣啊」用ものだ；指著眼前這個人、這件作品說「它有一種～的地方」用ものがある。</div>",
  "n2-64": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜抜き」就像點飲料說「去冰」、吃麵說「不要香菜」：把<b>本來應該有的東西拿掉</b>。在日本吃壽司說<span class='gd-jp'>わさび抜きでお願いします</span>，就是「請不要放芥末」。前面一律接<b>名詞</b>，常寫成漢字<span class='gd-jp'>抜き</span>，念ぬき。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>抜きで＋動作</span>拿掉某樣東西，去做某件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>わさび抜きでお願いします。</span>（麻煩不要放芥末）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ごはん抜きで会社に行った。</span>（今天早上沒吃早餐就去公司了）</div><div class='gd-sec'><span class='gd-tag'>抜きの＋名詞</span>後面接名詞，意思是「拿掉了～的那個東西」。</div><div class='gd-ex-line'>・<span class='gd-jp'>玉ねぎ抜きのハンバーガーをください。</span>（請給我不加洋蔥的漢堡）</div><div class='gd-sec'><span class='gd-tag'>冗談抜きで</span>固定說法，意思是「說真的、不開玩笑」，口語超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談抜きで、このラーメンは日本一だと思う。</span>（說真的，我覺得這碗拉麵是日本第一）</div><div class='gd-sec'><span class='gd-tag'>抜きには〜ない</span>「沒有～就沒辦法～」，用來強調那樣東西很重要。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の協力抜きには、この仕事は終わらなかった。</span>（沒有他幫忙，這份工作不可能完成）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の夏は花火抜きには語れない。</span>（講到日本的夏天，一定要提煙火）</div><div class='gd-sec'><span class='gd-tag'>は抜きにして</span>「～就先免了、先撇開～」，聚餐、開會開場很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>堅苦しい挨拶は抜きにして、乾杯しましょう。</span>（客套話就免了，我們乾杯吧）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・只能接<b>名詞</b>。「不吃早餐」不能說成食べ抜きで，要說<span class='gd-jp'>朝ごはん抜きで</span>，或者改用動詞<span class='gd-jp'>朝ごはんを食べないで</span>。<br>・抜き的感覺是「本來會有，刻意拿掉」。如果那樣東西本來就不一定會有，例如出門沒帶傘，說<span class='gd-jp'>傘なしで出かけた</span>比較自然。<br>・「抜きには」後面幾乎都接否定或「辦不到」的意思，例如<span class='gd-jp'>できない</span>、<span class='gd-jp'>語れない</span>、<span class='gd-jp'>考えられない</span>，不要接一般的肯定句。<br>・<span class='gd-jp'>冗談抜きで</span>多半是自己強調「我接下來是認真的」，不是叫對方「不要開玩笑」。也可以說<span class='gd-jp'>冗談抜きに</span>，意思一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>抜きには〜ない</b> 和 <b>ないことには</b>（n2-19）都是「沒有／不～，就沒辦法～」，差在前面接什麼：<br>・<span class='gd-jp'>社長の許可抜きには決められない。</span>（沒有社長的許可就不能決定）：前面是名詞<br>・<span class='gd-jp'>社長が許可しないことには決められない。</span>（社長不點頭就沒辦法決定）：前面是動詞</div><div class='gd-sec'><b>抜きで</b> 和 <b>ことなく</b>（n2-48）都能翻成「沒～就做了」：<br>・<span class='gd-jp'>休憩抜きで働いた。</span>（沒休息一直工作）：拿掉「休息時間」這個名詞<br>・<span class='gd-jp'>休むことなく働いた。</span>（毫不休息地工作）：前面是動詞，語氣比較書面</div><div class='gd-warn'>判斷小訣竅：前面是<b>名詞</b>就用抜き；前面是<b>動詞</b>，就改用ないことには或ことなく。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>抜き是從動詞<span class='gd-jp'>抜く</span>（拿掉、省略）來的，生活中也很常直接用動詞：<span class='gd-jp'>忙しくて昼ごはんを抜いた。</span>（太忙了，午餐沒吃）</div>",
  "n2-65": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜きる」就是中文的<b>「〜完」「〜光」「〜到底」</b>：跑完全程、錢花光、累到不行。<br>「〜きれる」是<b>做得完</b>，「〜きれない」是<b>做不完、〜不盡</b>。重點都在「全部、徹底、一點不剩」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的ます形，把ます拿掉，再接<span class='gd-jp'>きる</span>。<br><span class='gd-pair'><span class='gd-jp'>走ります</span> → 把ます拿掉 → <span class='gd-jp'>走りきる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べきる</span></span><span class='gd-pair'><span class='gd-jp'>使います</span> → <span class='gd-jp'>使いきる</span></span><br><span class='gd-jp'>する</span>會用在<span class='gd-jp'>説明する</span>這類詞：<span class='gd-pair'><span class='gd-jp'>説明します</span> → <span class='gd-jp'>説明しきる</span></span><br>接上去之後，<span class='gd-jp'>きる</span>本身照第一類（五段動詞）變：<span class='gd-jp'>きった</span>（〜完了）、<span class='gd-jp'>きれる</span>（做得完）、<span class='gd-jp'>きれない</span>（做不完）。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>做到最後、全部做完</span>中間沒放棄，或是一點都沒剩。</div><div class='gd-ex-line'>・<span class='gd-jp'>フルマラソンを走りきった。</span>（我跑完全馬了）</div><div class='gd-ex-line'>・<span class='gd-jp'>給料を三日で使いきってしまった。</span>（薪水三天就花光了）</div><div class='gd-sec'><span class='gd-tag'>到了極點</span>接在<span class='gd-jp'>疲れる</span>、<span class='gd-jp'>困る</span>這類表示狀態的動詞後面，意思是「完全～、～到不行」。</div><div class='gd-ex-line'>・<span class='gd-jp'>残業続きで、疲れきっている。</span>（一直加班，累到不行）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな分かりきったこと、聞かないでよ。</span>（那種再明白不過的事，就別問了啦）</div><div class='gd-sec'><span class='gd-tag'>講得很肯定</span><span class='gd-jp'>言いきる</span>＝斷言，話講死、不留後路。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「絶対に勝つ」と言いきった。</span>（他斷言「一定會贏」）</div><div class='gd-sec'><span class='gd-tag'>きれる／きれない</span>問做不做得完，或是多到做不完。</div><div class='gd-ex-line'>・<span class='gd-jp'>こんなにたくさん、一人で食べきれる？</span>（這麼多，你一個人吃得完嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>空に数えきれないほど星が出ている。</span>（天上的星星多到數不完）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日からの旅行が待ちきれない。</span>（我等不及明天開始的旅行了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接ます形把ます拿掉，不是接辭書形：是<span class='gd-jp'>食べきる</span>，不是「食べるきる」。<br>・<span class='gd-jp'>食べきれない</span>專指「量太多，沒辦法全部吃完」；<span class='gd-jp'>食べられない</span>範圍比較廣，可以是「不能吃」（過敏、不敢吃），也可以是「吃不下」（<span class='gd-jp'>もうお腹いっぱいで食べられない</span>）。想清楚表達「份量太多吃不完」時，用<span class='gd-jp'>食べきれない</span>最不會被誤會。<br>・<span class='gd-jp'>待ちきれない</span>是「等不及」，不是「等不完」。<br>・<span class='gd-jp'>疲れきる</span>不是「累完了、不累了」，而是「累到極點」，剛好跟中文直覺相反。<br>・漢字寫成<span class='gd-jp'>切る</span>（<span class='gd-jp'>食べ切る</span>）也對，但不是穿衣服的<span class='gd-jp'>着る</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜終わる</b>＝那個動作<b>結束了</b>，有沒有全部做光不是重點：<br></div><div class='gd-ex-line'>・<span class='gd-jp'>もうご飯食べ終わった？</span>（你飯吃完了沒？：問吃飯這件事結束沒）</div><div class='gd-sec'><b>〜きる</b>＝<b>全部、一點不剩</b>，常帶有「量很多、很不容易」的感覺：</div><div class='gd-ex-line'>・<span class='gd-jp'>こんなに多いのに、全部食べきったの？</span>（這麼多，你全部吃光了？）</div><div class='gd-warn'>判斷小訣竅：想說「做完了、結束了」用<span class='gd-jp'>終わる</span>；想強調「全部吃光、撐到最後、一點不剩」就用<span class='gd-jp'>きる</span>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>相反的是<span class='gd-jp'>〜かける</span>（做到一半）：<span class='gd-jp'>食べかけのパン</span>是「吃到一半的麵包」，<span class='gd-jp'>食べきる</span>是「全部吃光」，兩個一起記很好分。</div>",
  "n2-66": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に先立って」就是正式場合的<b>「在～之前，先～」</b>。就像司儀說「典禮開始之前，先請主辦單位致詞」、新聞說「新品上市前，先召開記者會」，那種很正式的「之前」。日常的「吃飯前洗手」不會用它。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>前面放一件<b>正式、有規劃的大事</b>（開會、施工、上市、出發、典禮），後面講<b>在那之前先做的準備、通知或儀式</b>。新聞、公告、致詞、商業文件最常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品の発売に先立って、記者会見が開かれた。</span>（新商品上市之前，先召開了記者會）</div><div class='gd-ex-line'>・<span class='gd-jp'>出発に先立ち、参加者に注意事項が説明された。</span>（出發之前，先向參加者說明了注意事項）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞＋に先立って／に先立ち</b>：最常見，名詞多半是「開会、工事、発売」這種可以加する的詞。<br><span class='gd-pair'><span class='gd-jp'>工事</span> → <span class='gd-jp'>工事に先立って</span></span><br><b>動詞辭書形＋に先立って</b>：也可以，但比較少見。<br><span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するに先立って</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>留学するに先立って、ビザの手続きを済ませた。</span>（去留學之前，先把簽證手續辦好了）</div><div class='gd-sec'>「に先立ち」比「に先立って」更書面、更硬一點，意思一樣。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>に先立ちまして</span>致詞、典禮開場的固定說法，更客氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>開会に先立ちまして、一言ご挨拶申し上げます。</span>（在開會之前，請容我先說幾句話）</div><div class='gd-sec'><span class='gd-tag'>に先立つ＋名詞</span>直接修飾後面的名詞，意思是「在～之前舉行的～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に先立つ開会式で、選手代表が宣誓した。</span>（在比賽前的開幕式上，選手代表進行了宣誓）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面直接接「に」，不要加の：是<span class='gd-jp'>開会に先立って</span>，不是開会の先立って。<br>・動詞要用辭書形，不能用た形：不能說「決めたに先立って」。<br>・念法是<b>さきだって</b>，不是せんだって。<br>・日常小事不要用，會很誇張：「睡覺前刷牙」要說<span class='gd-jp'>寝る前に歯を磨く</span>，說成「寝るに先立って」聽起來像在發新聞稿。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>前に</b>＝一般的「之前」，什麼場合都能用：<span class='gd-jp'>会議の前に、資料を確認しておこう。</span>（開會前先把資料看一下吧）<br><b>に先立って</b>＝正式場合「為了那件大事，事先～」：<span class='gd-jp'>会議に先立ち、資料が配布された。</span>（會議開始之前，先發了資料）<br><b>際に</b>＝「～的時候」，講的是當下，不是之前：<span class='gd-jp'>ご使用の際は、十分ご注意ください。</span>（使用時請多加注意）／<span class='gd-jp'>ご使用に先立ち、説明書をお読みください。</span>（使用之前，請先閱讀說明書）</div><div class='gd-warn'>判斷小訣竅：日常講「之前」用前に；正式場合「大事開始前，先做準備」用に先立って；「做的當下」用際に。</div>",
  "n2-67": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這三個都是中文的<b>「～得要命」「～得不得了」「忍不住一直～」</b>。心裡的感覺或身體的感覺強到壓不住，就用它們。意思差不多，主要差在<b>口氣正不正式</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格の知らせを聞いて、嬉しくてたまらない。</span>（聽到考上的消息，高興得不得了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面要先變成「て」的樣子，再接<span class='gd-jp'>たまらない</span>／<span class='gd-jp'>ならない</span>／<span class='gd-jp'>しょうがない</span>。<br>動詞：用て形　<span class='gd-pair'><span class='gd-jp'>気になる</span> → <span class='gd-jp'>気になってしょうがない</span></span><br>い形容詞：把最後的「い」換成「くて」　<span class='gd-pair'><span class='gd-jp'>嬉しい</span> → <span class='gd-jp'>嬉しくてたまらない</span></span><br>な形容詞：後面加「で」　<span class='gd-pair'><span class='gd-jp'>心配</span> → <span class='gd-jp'>心配でたまらない</span></span><br>想做某事：<span class='gd-jp'>たい</span>也是把「い」換成「くて」　<span class='gd-pair'><span class='gd-jp'>会いたい</span> → <span class='gd-jp'>会いたくてたまらない</span></span></div><div class='gd-h'>三個怎麼選</div><div class='gd-sec'><span class='gd-tag'>たまらない</span>最標準，心情、身體感覺、想要什麼都能接，日常就能講。</div><div class='gd-ex-line'>・<span class='gd-jp'>国の家族に会いたくてたまらない。</span>（好想見老家的家人）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑くてたまらない。</span>（今天熱得受不了）</div><div class='gd-sec'><span class='gd-tag'>しょうがない</span>最口語，跟朋友聊天最常聽到。比較正式一點的說法是<span class='gd-jp'>しかたがない</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日あまり寝てないから、眠くてしょうがない。</span>（昨天沒怎麼睡，睏得要死）</div><div class='gd-sec'><span class='gd-tag'>ならない</span>偏書面、正式，有一種「心裡自然一直冒出這種感覺」的味道。最常跟<span class='gd-jp'>気がする</span>、<span class='gd-jp'>思われる</span>、<span class='gd-jp'>思い出される</span>這類「感覺自己跑出來」的說法放在一起。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が何か隠している気がしてならない。</span>（我總覺得他在隱瞞什麼）</div><div class='gd-ex-line'>・<span class='gd-jp'>故郷のことが思い出されてならない。</span>（總是忍不住想起故鄉）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這是講<b>自己</b>的感覺。講別人要加<span class='gd-jp'>ようだ</span>、<span class='gd-jp'>らしい</span>：<span class='gd-jp'>妹は寂しくてたまらないようだ。</span>（妹妹好像寂寞得不得了）<br>・前面只能放感覺、情緒，不能放自己決定要做的動作。「讀書讀得不得了」不能說<span class='gd-jp'>勉強してたまらない</span>。想做某件事要用<span class='gd-jp'>〜たくて</span>。<br>・<span class='gd-jp'>てならない</span>不要跟<span class='gd-jp'>てはならない</span>搞混。多一個「は」就變成「不可以」：<span class='gd-jp'>嘘をついてはならない。</span>（不可以說謊）<span class='gd-jp'>なくてはならない</span>則是「必須」。<br>・<span class='gd-jp'>てしょうがない</span>不要跟<span class='gd-jp'>てもしょうがない</span>搞混。多一個「も」就變成「～也沒用」：<span class='gd-jp'>今さら後悔してもしょうがない。</span>（現在才後悔也沒用）<br>・在正式文章或演講裡，用<span class='gd-jp'>しょうがない</span>會太隨便，改用<span class='gd-jp'>ならない</span>或<span class='gd-jp'>しかたがない</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>中文都會翻成「忍不住」，所以很容易跟<b>ずにはいられない</b>混在一起。<br><b>てたまらない</b>＝感覺強到受不了，重點在<b>心情本身</b>：<span class='gd-jp'>母の病気が心配でたまらない。</span>（我擔心媽媽的病擔心得不得了）<br><b>ずにはいられない</b>＝忍不住<b>做出某個動作</b>：<span class='gd-jp'>心配で、母に電話せずにはいられなかった。</span>（太擔心了，忍不住打電話給媽媽）</div><div class='gd-warn'>判斷小訣竅：忍不住的是「感覺」，就用てたまらない；忍不住「做了某件事」，就用ずにはいられない。</div>"
});
(window.GRAMMAR_DETAIL_LV = window.GRAMMAR_DETAIL_LV || {}).n2 = true;
